// ─────────────────────────────────────────────────────────────────────────────
//  TIPS SERVICE — reemplaza kTipsPorSitio y kTipsPorSitioEN
//  Tips cargados desde Firestore (colección: tips_por_sitio) con caché en memoria
// ─────────────────────────────────────────────────────────────────────────────
class TipsService {
  static final TipsService _instance = TipsService._internal();
  factory TipsService() => _instance;
  TipsService._internal();

  final Map<String, Map<String, String>> _cache = {};
  bool _cargado = false;

  Future<void> precargar() async {
    if (_cargado) return;
    try {
      final snapshot = await FirebaseFirestore.instance
          .collection('tips_por_sitio')
          .get(GetOptions(source: fs.Source.serverAndCache));
      for (final doc in snapshot.docs) {
        final data = doc.data();
        final nombre = data['nombre']?.toString() ?? doc.id;
        _cache[nombre] = {
          'es': data['es']?.toString() ?? '',
          'en': data['en']?.toString() ?? '',
        };
      }
      _cargado = true;
      debugPrint('✅ TipsService: \${_cache.length} tips cargados');
    } catch (e) {
      debugPrint('⚠️ TipsService: error cargando tips — \$e');
    }
  }

  String getTip(String sitioNombre) {
    final entry = _cache[sitioNombre];
    if (entry == null) return '';
    if (kLang == 'en') {
      return entry['en']?.isNotEmpty == true ? entry['en']! : (entry['es'] ?? '');
    }
    return entry['es']?.isNotEmpty == true ? entry['es']! : (entry['en'] ?? '');
  }

  bool containsKey(String sitioNombre) => _cache.containsKey(sitioNombre);
}

final tipsService = TipsService();

// ─────────────────────────────────────────
//  AUDIO MANAGER — Música épica
// ─────────────────────────────────────────
class AudioManager {
  static final AudioManager _instance = AudioManager._internal();
  factory AudioManager() => _instance;
  AudioManager._internal();

  final AudioPlayer _playerMusica = AudioPlayer();
  final AudioPlayer _playerCelebracion = AudioPlayer();

  bool _musicaIniciada = false;
  bool _silenciado = false;
  double _volumenMusica = 0.4;
  double _volumenEfectos = 0.5;

  bool get silenciado => _silenciado;
  double get volumenMusica => _volumenMusica;
  double get volumenEfectos => _volumenEfectos;

  /// Carga las preferencias de audio guardadas (silenciado, volúmenes).
  /// Se llama al iniciar la app para mantener la configuración del usuario
  /// incluso después de cerrar y reabrir la app.
  Future<void> cargarPreferencias() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _silenciado = prefs.getBool('audio_silenciado') ?? false;
      _volumenMusica = prefs.getDouble('audio_volumen_musica') ?? 0.4;
      _volumenEfectos = prefs.getDouble('audio_volumen_efectos') ?? 0.5;
    } catch (e) {
      debugPrint('⚠️ Error cargando preferencias audio: $e');
    }
  }

  /// Guarda las preferencias actuales en SharedPreferences
  Future<void> _guardarPreferencias() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool('audio_silenciado', _silenciado);
      await prefs.setDouble('audio_volumen_musica', _volumenMusica);
      await prefs.setDouble('audio_volumen_efectos', _volumenEfectos);
    } catch (e) {
      debugPrint('⚠️ Error guardando preferencias audio: $e');
    }
  }

  Future<void> iniciarMusicaPrincipal() async {
    if (_musicaIniciada) return;
    _musicaIniciada = true;
    try {
      await _playerMusica.setReleaseMode(ReleaseMode.loop);
      await _playerMusica.setVolume(_silenciado ? 0 : _volumenMusica);
      await _playerMusica.play(AssetSource('audio/musica_principal.mp3'));
    } catch (e) {
      debugPrint('🔴 Error música: $e');
      _musicaIniciada = false;
    }
  }

  Future<void> setVolumenMusica(double volumen) async {
    _volumenMusica = volumen.clamp(0.0, 1.0);
    if (!_silenciado) {
      await _playerMusica.setVolume(_volumenMusica);
    }
    await _guardarPreferencias();
  }

  Future<void> setVolumenEfectos(double volumen) async {
    _volumenEfectos = volumen.clamp(0.0, 1.0);
    await _guardarPreferencias();
  }

  Future<void> toggleSilencio() async {
    _silenciado = !_silenciado;
    await _playerMusica.setVolume(_silenciado ? 0 : _volumenMusica);
    await _guardarPreferencias();
  }

  Future<void> pausarMusica() async {
    try { await _playerMusica.pause(); } catch (_) {}
  }

  Future<void> reanudarMusica() async {
    try { await _playerMusica.resume(); } catch (_) {}
  }

  Future<void> sonarCelebracion() async {
    if (_silenciado) return;
    try {
      await _playerCelebracion.setVolume(_volumenEfectos);
      await _playerCelebracion.play(AssetSource('audio/celebracion.mp3'));
    } catch (e) {
      debugPrint('🔴 Error celebración: $e');
    }
  }

  void dispose() {
    _musicaIniciada = false;
    _playerMusica.dispose();
    _playerCelebracion.dispose();
  }
}

// ═══════════════════════════════════════════════════════════════
//  SESIÓN MANAGER — Persiste el contexto del usuario entre sesiones
// ═══════════════════════════════════════════════════════════════
//  Resuelve el problema: cuando el usuario cierra la app
//  por seguridad y la vuelve a abrir, debe encontrar:
//   - La misma ruta que estaba haciendo
//   - El último sitio que validó
//   - Sus configuraciones (sonido, idioma, modo demo si es admin)
//
//  Almacenamiento: SharedPreferences (local, sobrevive a app cerrada)
// ═══════════════════════════════════════════════════════════════

class SesionManager {
  static final SesionManager _instance = SesionManager._internal();
  factory SesionManager() => _instance;
  SesionManager._internal();

  String? _rutaActivaNombre;
  int? _ultimoSitioIndex;

  String? get rutaActivaNombre => _rutaActivaNombre;
  int? get ultimoSitioIndex => _ultimoSitioIndex;

  /// Carga la ruta activa guardada (llamar al iniciar la app)
  Future<void> cargarRutaActiva() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      _rutaActivaNombre = prefs.getString('sesion_ruta_activa');
      _ultimoSitioIndex = prefs.getInt('sesion_ultimo_sitio');
    } catch (e) {
      debugPrint('⚠️ Error cargando ruta activa: $e');
    }
  }

  /// Guarda la ruta que el usuario está realizando ahora.
  /// Llamar cuando el usuario abre/entra a una RouteDetailScreen.
  Future<void> setRutaActiva(String nombreRuta) async {
    _rutaActivaNombre = nombreRuta;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('sesion_ruta_activa', nombreRuta);
    } catch (e) {
      debugPrint('⚠️ Error guardando ruta activa: $e');
    }
  }

  /// Guarda el último sitio visto/validado (para retomar)
  Future<void> setUltimoSitio(int index) async {
    _ultimoSitioIndex = index;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setInt('sesion_ultimo_sitio', index);
    } catch (e) {
      debugPrint('⚠️ Error guardando último sitio: $e');
    }
  }

  /// Limpia la ruta activa (cuando el usuario completa la ruta o la abandona)
  Future<void> limpiarRutaActiva() async {
    _rutaActivaNombre = null;
    _ultimoSitioIndex = null;
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.remove('sesion_ruta_activa');
      await prefs.remove('sesion_ultimo_sitio');
    } catch (e) {
      debugPrint('⚠️ Error limpiando ruta activa: $e');
    }
  }
}

