  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: SafeArea(child: SingleChildScrollView(
        padding: const EdgeInsets.all(24),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [
            GestureDetector(
              onTap: () => Navigator.pop(context),
              child: Container(width: 40, height: 40,
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(0.08), shape: BoxShape.circle),
                child: const Center(child: Text('←',
                  style: TextStyle(color: kText, fontSize: 18))))),
          ]),
          const SizedBox(height: 24),
          Center(child: Container(
            width: 90, height: 90,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              gradient: LinearGradient(colors: [RDSColor.green, kOrchid]),
              boxShadow: [BoxShadow(color: RDSColor.green.withOpacity(0.4), blurRadius: 20)]),
            child: Center(child: Text(
              usuario.isNotEmpty ? usuario[0].toUpperCase() : '?',
              style: const TextStyle(color: Colors.white, fontSize: 42, fontWeight: FontWeight.w900))))),
          const SizedBox(height: 16),
          Center(child: Text(usuario,
            style: const TextStyle(color: kText, fontSize: 24, fontWeight: FontWeight.w900))),
          const SizedBox(height: 4),
          Center(child: Text(t('Rutero MDE', 'Rutero MDE'),
            style: TextStyle(color: kGreen, fontSize: 13, fontWeight: FontWeight.w600))),
          const SizedBox(height: 32),
          // Cargar insignias desde Firestore
          StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('usuarios_publicos')
                .doc(usuario)
                .collection('insignias')
                .snapshots(),
            builder: (ctx, snap) {
              if (!snap.hasData) {
                return const Center(child: Padding(
                  padding: EdgeInsets.all(40),
                  child: CircularProgressIndicator(color: kGreen)));
              }
              final docs = snap.data?.docs ?? [];
              if (docs.isEmpty) {
                return Padding(
                  padding: const EdgeInsets.all(40),
                  child: Column(children: [
                    const Text('🏆', style: TextStyle(fontSize: 48)),
                    const SizedBox(height: 12),
                    Text(t('Aún sin insignias públicas',
                           'No public badges yet'),
                      style: const TextStyle(color: kTextMuted, fontSize: 14)),
                  ]));
              }
              return Column(children: [
                Text(t('${docs.length} insignias ganadas',
                       '${docs.length} badges earned'),
                  style: TextStyle(color: kGold, fontSize: 14, fontWeight: FontWeight.w700)),
                const SizedBox(height: 16),
                GridView.count(
                  crossAxisCount: 3,
                  shrinkWrap: true,
                  physics: const NeverScrollableScrollPhysics(),
                  mainAxisSpacing: 12, crossAxisSpacing: 12,
                  children: docs.map((d) {
                    final data = d.data() as Map<String, dynamic>;
                    return Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: RDSColor.card, borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: RDSColor.gold.withOpacity(0.3))),
                      child: Column(mainAxisAlignment: MainAxisAlignment.center, children: [
                        const Text('🏅', style: TextStyle(fontSize: 32)),
                        const SizedBox(height: 6),
                        Text(data['nombre']?.toString() ?? '',
                          textAlign: TextAlign.center,
                          maxLines: 2, overflow: TextOverflow.ellipsis,
                          style: const TextStyle(color: kText, fontSize: 10, fontWeight: FontWeight.w700)),
                      ]));
                  }).toList()),
              ]);
            }),
        ]))));
  }
}

