// ─────────────────────────────────────────────────────────────────────────
//  SISTEMA DE DETECCIÓN DE CIUDAD POR GPS — 23/05/2026
//  Escalable: agregar ciudad nueva = agregar una línea a kCiudadesRegistradas
//  Compatible con cualquier ciudad y país del mundo
// ─────────────────────────────────────────────────────────────────────────

/// Ciudad registrada con identidad de marca propia
class _CiudadRegistrada {
  final String ciudad;
  final String pais;
  final double lat;
  final double lng;
  final double radioKm;
  final String codigo;      // Código de marca: MDE, BTA, CTG, etc.
  final String emoji;       // Emoji representativo de la ciudad
  final String taglineES;   // Tagline en español
  final String taglineEN;   // Tagline en inglés
  final String nombreApp;   // Nombre de la app en esa ciudad
