/// Feria oficial activa: 31 jul – 9 ago
bool get feriaActiva {
  final now = DateTime.now();
  final inicio = DateTime(kFeriaAno, kFeriaInicio[0], kFeriaInicio[1]);
  final fin = DateTime(kFeriaAno, kFeriaFin[0], kFeriaFin[1], 23, 59);
  return now.isAfter(inicio.subtract(const Duration(hours: 1))) && now.isBefore(fin);
}

/// Pre-feria activa: 19 jul – 30 jul
bool get preFeriaActiva {
  final now = DateTime.now();
  final preInicio = DateTime(kFeriaAno, kFeriaPreInicio[0], kFeriaPreInicio[1]);
  final feriaInicio = DateTime(kFeriaAno, kFeriaInicio[0], kFeriaInicio[1]);
  return now.isAfter(preInicio.subtract(const Duration(days: 1))) && now.isBefore(feriaInicio);
}

/// Días para el inicio de la Feria (negativo = ya empezó)
/// Días para el PRÓXIMO hito de la feria:
/// - Si no ha empezado pre-feria → días para 19 jul
/// - Si está en pre-feria → días para apertura 31 jul
/// - Si está en feria → días para el Desfile (9 ago)
int get diasParaFeria {
  final now = DateTime.now();
  if (feriaActiva) {
    // En feria: contar hacia el Desfile de Silleteros
    final desfile = DateTime(kFeriaAno, kFeriaDesfile[0], kFeriaDesfile[1]);
    return desfile.difference(now).inDays;
  }
  if (preFeriaActiva) {
    // En pre-feria: contar hacia la apertura oficial
    final apertura = DateTime(kFeriaAno, kFeriaInicio[0], kFeriaInicio[1]);
    return apertura.difference(now).inDays;
  }
  // Antes de todo: contar hacia la pre-feria
  final preInicio = DateTime(kFeriaAno, kFeriaPreInicio[0], kFeriaPreInicio[1]);
  return preInicio.difference(now).inDays;
}

/// Texto del contador según el momento
String get textoContadorFeria {
  if (feriaActiva) {
    final d = diasParaFeria;
    return d == 0
      ? t('¡Hoy es el Desfile de Silleteros! 🌹', 'Today is the Silleteros Parade! 🌹')
      : t('$d días para el Desfile · ¡La Feria está activa! 🌹', '$d days to the Parade · Festival is live! 🌹');
  }
  if (preFeriaActiva) {
    final d = diasParaFeria;
    return d == 0
      ? t('¡Hoy abre la Feria!', 'The Festival opens today!')
      : t('Faltan $d días para la apertura oficial', '$d days to the official opening');
  }
  final d = diasParaFeria;
  return t('La pre-feria arranca en $d días · 19 julio', 'Pre-festival starts in $d days · July 19');
}

/// Verifica si hoy es el día de un evento específico [mes, dia]
bool esDiaEvento(List<int> fechaEvento) {
  final now = DateTime.now();
  return now.month == fechaEvento[0] && now.day == fechaEvento[1];
}

/// Días para un evento específico
int diasParaEvento(List<int> fechaEvento) {
  final now = DateTime.now();
  final evento = DateTime(kFeriaAno, fechaEvento[0], fechaEvento[1]);
  return evento.difference(now).inDays;
}

/// Agenda del día — filtra eventos de hoy
List<Map<String, dynamic>> get agendaHoy {
  final now = DateTime.now();
  return kFeriaAgenda.where((e) {
    final mes = e['mes'] as int?;
    final dia = e['dia'] as int?;
    if (mes == null || dia == null) return false;
    return now.month == mes && now.day == dia;
  }).toList();
}

/// Agenda del día siguiente
List<Map<String, dynamic>> get agendaManana {
  final manana = DateTime.now().add(const Duration(days: 1));
  return kFeriaAgenda.where((e) {
    final mes = e['mes'] as int?;
    final dia = e['dia'] as int?;
    if (mes == null || dia == null) return false;
    return manana.month == mes && manana.day == dia;
  }).toList();
}

