class _RDSMenuOpcion extends StatelessWidget {
  final IconData? icon;
  final String? emoji;          // Mantener para los casos actuales (📸 🚨 🛎️ 📱)
  final String titulo;
  final String subtitulo;
  final Color color;
  final VoidCallback onTap;

  const _RDSMenuOpcion({
    this.icon,
    this.emoji,
    required this.titulo,
    required this.subtitulo,
    required this.color,
    required this.onTap,
  }) : assert(icon != null || emoji != null);

  @override
  Widget build(BuildContext context) => GestureDetector(
    onTap: onTap,
    child: Container(
      padding: const EdgeInsets.all(RDSSpace.md),
      decoration: BoxDecoration(
        color: RDSColor.card,
        borderRadius: RDSRadius.bMd,                    // circular(14) → token
        border: Border.all(color: color.withOpacity(0.30))),
      child: Row(children: [
        Container(
          width: 42, height: 42,
          decoration: BoxDecoration(
            color: color.withOpacity(0.12), shape: BoxShape.circle),
          child: Center(
            child: icon != null
                ? Icon(icon, size: 20, color: color)
                : Text(emoji!, style: const TextStyle(fontSize: 20)))),
        const SizedBox(width: RDSSpace.md - 4),
        Expanded(child: Column(
          crossAxisAlignment: CrossAxisAlignment.start, children: [
          Text(titulo,
            style: RDSType.headlineMd.copyWith(color: color)),
          const SizedBox(height: 2),
          Text(subtitulo,
            style: RDSType.caption.copyWith(
              color: RDSColor.textMuted.withOpacity(0.8))),
        ])),
        Icon(RDSIcons.actionExplore,                   // Icons.arrow_forward_ios → token
          color: color.withOpacity(0.50), size: 14),
      ])));
}

// ── INPUT — Campo de texto estándar ──────────────────────────────────────
// Patrón unificado. Reemplaza los TextField inline en cada pantalla.
// En Fase 3, cada pantalla que use TextField migra a _RDSInput.
class _RDSInput extends StatelessWidget {
  final TextEditingController? controller;
  final String hint;
  final int maxLines;
  final TextInputType? keyboardType;
  final bool obscureText;
  final Widget? suffixIcon;
  final Widget? prefixIcon;
  final void Function(String)? onChanged;
  final Color? accentColor;       // Color de borde activo; default RDSColor.green
  final bool readOnly;

  const _RDSInput({
    this.controller,
    required this.hint,
    this.maxLines = 1,
    this.keyboardType,
    this.obscureText = false,
    this.suffixIcon,
    this.prefixIcon,
    this.onChanged,
    this.accentColor,
    this.readOnly = false,
  });

  @override
  Widget build(BuildContext context) {
    final Color accent = accentColor ?? RDSColor.green;
    return TextField(
      controller: controller,
      maxLines: maxLines,
      keyboardType: keyboardType,
      obscureText: obscureText,
      readOnly: readOnly,
      onChanged: onChanged,
      style: RDSType.bodyMd.copyWith(color: RDSColor.textPrimary),
      decoration: InputDecoration(
        hintText: hint,
        hintStyle: RDSType.bodyMd,                     // RDSColor.textMuted ya en token
        filled: true,
        fillColor: RDSColor.base,                       // RDSColor.base → token
        prefixIcon: prefixIcon,
        suffixIcon: suffixIcon,
        contentPadding: const EdgeInsets.symmetric(
          horizontal: RDSSpace.md, vertical: RDSSpace.md - 4),
        border: OutlineInputBorder(
          borderRadius: RDSRadius.bMd,                  // circular(12) → token
          borderSide: BorderSide(color: accent.withOpacity(0.20))),
        enabledBorder: OutlineInputBorder(
          borderRadius: RDSRadius.bMd,
          borderSide: BorderSide(color: accent.withOpacity(0.20))),
        focusedBorder: OutlineInputBorder(
          borderRadius: RDSRadius.bMd,
          borderSide: BorderSide(color: accent, width: 1.5)),
        errorBorder: OutlineInputBorder(
          borderRadius: RDSRadius.bMd,
          borderSide: BorderSide(color: RDSColor.accent, width: 1.5)),
      ));
  }
}

// ── EMPTY STATE ───────────────────────────────────────────────────────────
// Para listas vacías, búsquedas sin resultado, logros sin desbloquear.
// Lucide Icons (trazo fino) — no compiten con el contenido.
class _RDSEmptyState extends StatelessWidget {
  final IconData icon;
  final String title;
  final String? subtitle;
  final Widget? action;           // Botón CTA opcional

  const _RDSEmptyState({
    required this.icon,
    required this.title,
    this.subtitle,
    this.action,
  });

  @override
  Widget build(BuildContext context) => Center(
    child: Padding(
      padding: const EdgeInsets.all(RDSSpace.xl),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        Icon(icon, size: 56, color: RDSColor.textMuted.withOpacity(0.40)),
        const SizedBox(height: RDSSpace.md),
        Text(title,
          textAlign: TextAlign.center,
          style: RDSType.headlineMd.copyWith(color: RDSColor.textMuted)),
        if (subtitle != null) ...[
          const SizedBox(height: RDSSpace.sm),
          Text(subtitle!,
            textAlign: TextAlign.center,
            style: RDSType.bodySm),
        ],
        if (action != null) ...[
          const SizedBox(height: RDSSpace.lg),
          action!,
        ],
      ])));
}

// ── SKELETON — Placeholder de carga ──────────────────────────────────────
// Animación shimmer simple sin dependencia externa (no hay shimmer package).
// Usa AnimatedOpacity para pulso suave. En Fase 3, reemplazar spinners
// inline por _RDSSkeleton mientras carga Firestore.
class _RDSSkeleton extends StatefulWidget {
  final double width;
  final double height;
  final BorderRadius? borderRadius;

  const _RDSSkeleton({
    required this.width,
    required this.height,
    this.borderRadius,
  });

  // Preset: esqueleto de RouteCard
  const _RDSSkeleton.card()
      : width = double.infinity,
        height = 0,           // AspectRatio maneja el alto
        borderRadius = null;

  @override
  State<_RDSSkeleton> createState() => _RDSSkeletonState();
}

class _RDSSkeletonState extends State<_RDSSkeleton>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _anim;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this, duration: const Duration(milliseconds: 900))
      ..repeat(reverse: true);
    _anim = Tween<double>(begin: 0.3, end: 0.7)
        .animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeInOut));
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: _anim,
    builder: (_, __) => Opacity(
      opacity: _anim.value,
      child: Container(
        width: widget.width == 0 ? double.infinity : widget.width,
        height: widget.height == 0 ? null : widget.height,
        decoration: BoxDecoration(
          color: RDSColor.card,
          borderRadius: widget.borderRadius ?? RDSRadius.bMd))));
}

// ── DIALOG — Diálogo estándar del sistema ────────────────────────────────
// Reemplaza los AlertDialog inline. Úsalo con showRDSDialog().
// En Fase 3 migrar todos los showDialog() a showRDSDialog().
class _RDSDialog extends StatelessWidget {
  final String title;
  final String? message;
  final Widget? content;          // Contenido custom (alternativo a message)
  final List<_RDSDialogAction> actions;

  const _RDSDialog({
    required this.title,
    this.message,
    this.content,
    required this.actions,
  });

  @override
  Widget build(BuildContext context) => AlertDialog(
    backgroundColor: RDSColor.card,                    // RDSColor.card → token
    surfaceTintColor: Colors.transparent,
    shape: RoundedRectangleBorder(
      borderRadius: RDSRadius.bLg,                     // circular(16) → token
      side: BorderSide(color: RDSColor.borderSubtle)),
    title: Text(title,
      style: RDSType.headlineLg.copyWith(color: RDSColor.gold)),
    content: content ??
        (message != null
            ? Text(message!, style: RDSType.bodyMd)
            : null),
    actionsPadding: const EdgeInsets.fromLTRB(
      RDSSpace.md, 0, RDSSpace.md, RDSSpace.md),
    actions: actions.map((a) => TextButton(
      onPressed: a.onTap,
      child: Text(a.label,
        style: RDSType.labelMd.copyWith(
          color: a.isPrimary ? RDSColor.green : RDSColor.textMuted)))).toList());
}

class _RDSDialogAction {
  final String label;
  final VoidCallback onTap;
  final bool isPrimary;
  const _RDSDialogAction({
    required this.label,
    required this.onTap,
    this.isPrimary = false,
  });
}

// Helper global — reemplaza showDialog() inline
Future<void> showRDSDialog({
  required BuildContext context,
  required String title,
  String? message,
  Widget? content,
  required List<_RDSDialogAction> actions,
}) => showDialog(
  context: context,
  builder: (_) => _RDSDialog(
    title: title,
    message: message,
    content: content,
    actions: actions));

// ── Bottom Sheet estándar ────────────────────────────────────────────────
// Reemplaza los showModalBottomSheet inline (SOS, filtros, etc.)
Future<T?> showRDSSheet<T>({
  required BuildContext context,
  required Widget child,
  bool isScrollControlled = true,
}) => showModalBottomSheet<T>(
  context: context,
  backgroundColor: RDSColor.card,                     // RDSColor.base → RDSColor.card
  isScrollControlled: isScrollControlled,
  useSafeArea: true,
  shape: const RoundedRectangleBorder(
    borderRadius: BorderRadius.vertical(
      top: Radius.circular(RDSRadius.xl))),            // circular(20) → token
  builder: (_) => Column(mainAxisSize: MainAxisSize.min, children: [
    // Drag handle
    Container(
      width: 40, height: 4,
      margin: const EdgeInsets.symmetric(vertical: RDSSpace.md),
      decoration: BoxDecoration(
        color: RDSColor.textMuted.withOpacity(0.30),
        borderRadius: RDSRadius.bFull)),
    child,
  ]));

// ─────────────────────────────────────────
//  SPLASH SCREEN — ESTILO PAISA
// ─────────────────────────────────────────
class SplashScreen extends StatefulWidget {
  const SplashScreen({super.key});
  @override
  State<SplashScreen> createState() => _SplashScreenState();
}

class _SplashScreenState extends State<SplashScreen> with TickerProviderStateMixin {
  late AnimationController _ctrl;
  late AnimationController _floatCtrl;
  late Animation<double> _fadeAnim, _scaleAnim, _progressAnim;
  late Animation<double> _floatAnim;


  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 2200));
    _floatCtrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 2000))
      ..repeat(reverse: true);

    _fadeAnim = CurvedAnimation(parent: _ctrl, curve: Curves.easeIn);
    _scaleAnim = Tween<double>(begin: 0.7, end: 1.0)
        .animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeOutBack));
    _progressAnim = Tween<double>(begin: 0.0, end: 1.0)
        .animate(CurvedAnimation(parent: _ctrl, curve: const Interval(0.4, 1.0, curve: Curves.easeInOut)));
    _floatAnim = Tween<double>(begin: -6.0, end: 6.0)
        .animate(CurvedAnimation(parent: _floatCtrl, curve: Curves.easeInOut));

    _ctrl.forward();

    Future.delayed(const Duration(milliseconds: 3200), () async {
      if (!mounted) return;
  
      User? usuarioActual = FirebaseAuth.instance.currentUser;
  
      if (usuarioActual == null) {
            try {
          usuarioActual = await FirebaseAuth.instance
            .authStateChanges()
            .first
            .timeout(const Duration(seconds: 5));
              } catch (e) {
                usuarioActual = null;
        }
      }

      if (!mounted) return;

      if (usuarioActual != null) {
            Navigator.of(context).pushReplacement(PageRouteBuilder(
          pageBuilder: (_, __, ___) => const MainShell(),
          transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
          transitionDuration: const Duration(milliseconds: 700),
        ));
        return;
      }
        Navigator.of(context).pushReplacement(PageRouteBuilder(
        pageBuilder: (_, __, ___) => const LangSelectScreen(),
        transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
        transitionDuration: const Duration(milliseconds: 700),
      ));
    });
  }

  @override
  void dispose() { _ctrl.dispose(); _floatCtrl.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.of(context).size;
    return Scaffold(
      backgroundColor: const Color(0xFF060A04),
      body: Stack(children: [

        // CAPA 1: Foto full-screen protagonista
        Positioned.fill(
          child: Image.asset(
            'assets/images/splash_bg.png',
            fit: BoxFit.cover,
            errorBuilder: (_, __, ___) => Container(
              decoration: const BoxDecoration(
                gradient: LinearGradient(
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                  colors: [Color(0xFF0D2010), Color(0xFF060A04)]))))),

        // CAPA 2: Overlay cinematografico 5 zonas
        Positioned.fill(
          child: Container(
            decoration: const BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter,
                end: Alignment.bottomCenter,
                stops: [0.0, 0.25, 0.50, 0.72, 1.0],
                colors: [
                  Color(0xBB000000),
                  Color(0x33000000),
                  Color(0x66000000),
                  Color(0xCC060A04),
                  Color(0xFF060A04),
                ])))),

        // CAPA 3: Resplandor radial verde
        Positioned(
          bottom: size.height * 0.25,
          left: size.width / 2 - 140,
          child: Container(
            width: 280, height: 280,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              gradient: RadialGradient(colors: [
                RDSColor.green.withOpacity(0.12),
                Colors.transparent,
              ])))),

        // CAPA 4: Contenido anclado al fondo
        Positioned(
          bottom: 0, left: 0, right: 0,
          child: FadeTransition(
            opacity: _fadeAnim,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(32, 0, 32, 52),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [

                  // Logo con glow flotante
                  AnimatedBuilder(
                    animation: _floatAnim,
                    builder: (_, __) => Transform.translate(
                      offset: Offset(0, _floatAnim.value),
                      child: Container(
                        width: 100, height: 100,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          boxShadow: [
                            BoxShadow(color: RDSColor.green.withOpacity(0.5),
                              blurRadius: 48, spreadRadius: 6),
                            BoxShadow(color: RDSColor.gold.withOpacity(0.2),
                              blurRadius: 24),
                            BoxShadow(color: Colors.black.withOpacity(0.5),
                              blurRadius: 12, offset: const Offset(0, 6)),
                          ]),
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(100),
                          child: Image.asset(
                            'assets/images/logo_splash.png',
                            width: 100, height: 100, fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => Container(
                              decoration: BoxDecoration(
                                shape: BoxShape.circle,
                                color: RDSColor.green.withOpacity(0.15)),
                              child: const Center(
                                child: Icon(Icons.explore_rounded,
                                  color: RDSColor.green, size: 44)))))))),

                  const SizedBox(height: 20),

                  // Titulo RUTERO gradiente dorado
                  ShaderMask(
                    shaderCallback: (b) => const LinearGradient(
                      colors: [Color(0xFFD4AF7A), Color(0xFFF5E4A0),
                               Color(0xFFE8C96B), Color(0xFFD4AF7A)],
                      stops: [0.0, 0.35, 0.65, 1.0],
                    ).createShader(b),
                    child: const Text('RUTERO',
                      textAlign: TextAlign.center,
                      style: TextStyle(
                        fontFamily: 'PlayfairDisplay',
                        fontSize: 48, fontWeight: FontWeight.w900,
                        color: Colors.white, letterSpacing: 5, height: 1.0))),

                  const SizedBox(height: 4),

                  // MEDELLIN separador
                  Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    Container(width: 28, height: 1,
                      decoration: BoxDecoration(gradient: LinearGradient(
                        colors: [Colors.transparent, RDSColor.gold.withOpacity(0.5)]))),
                    const SizedBox(width: 10),
                    const Text('MEDELLÍN',
                      style: TextStyle(
                        fontFamily: 'SpaceGrotesk',
                        fontSize: 10, fontWeight: FontWeight.w600,
                        color: Color(0xFF8BA878), letterSpacing: 6)),
                    const SizedBox(width: 10),
                    Container(width: 28, height: 1,
                      decoration: BoxDecoration(gradient: LinearGradient(
                        colors: [RDSColor.gold.withOpacity(0.5), Colors.transparent]))),
                  ]),

                  const SizedBox(height: 18),

                  // Tagline
                  Text(tTaglineSplash,
                    textAlign: TextAlign.center,
                    style: TextStyle(
                      fontFamily: 'Inter', fontSize: 11,
                      color: const Color(0xFFD4AF7A).withOpacity(0.8),
                      fontStyle: FontStyle.italic,
                      letterSpacing: 0.3, height: 1.4)),

                  const SizedBox(height: 32),

                  // Barra de progreso
                  AnimatedBuilder(
                    animation: _progressAnim,
                    builder: (_, __) => SizedBox(
                      width: 120,
                      child: ClipRRect(
                        borderRadius: BorderRadius.circular(1),
                        child: LinearProgressIndicator(
                          value: _progressAnim.value,
                          backgroundColor: Colors.white.withOpacity(0.07),
                          valueColor: AlwaysStoppedAnimation<Color>(
                            Color.lerp(RDSColor.green, RDSColor.gold,
                              _progressAnim.value) ?? RDSColor.green),
                          minHeight: 2)))),

                  const SizedBox(height: 20),

                  // Badge Creame
                  Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                    const Icon(Icons.account_balance_rounded,
                      size: 9, color: Color(0xFF6A8AAA)),
                    const SizedBox(width: 5),
                    const Text('Créame · Alcaldía de Medellín',
                      style: TextStyle(
                        color: Color(0xFF6A8AAA),
                        fontSize: 8, letterSpacing: 0.5)),
                  ]),


                ])))),
      ]),
    );
  }
}
// ─────────────────────────────────────────
//  MIS PREMIOS SCREEN
// ─────────────────────────────────────────
class MisPremiosScreen extends StatelessWidget {
  const MisPremiosScreen({super.key});
  @override
  Widget build(BuildContext context) {
    final user = AuthService.currentUser;
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        // Header
        Container(
          decoration: const BoxDecoration(
            gradient: LinearGradient(begin: Alignment.topLeft, end: Alignment.bottomRight,
              colors: [Color(0xFF1A1000), Color(0xFF2A1A00)])),
          child: SafeArea(child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 16, 20, 20),
            child: Row(children: [
              GestureDetector(
                onTap: () {
                  if (Navigator.canPop(context)) {
                    Navigator.pop(context);
                  }
                },
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(color: Colors.black.withOpacity(0.4), shape: BoxShape.circle),
                  child: const Center(child: Icon(RDSIcons.back, color: RDSColor.textPrimary, size: 18)))),
              const SizedBox(width: 14),
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(tMisPremiosTitle, style: const TextStyle(fontSize: 20, fontWeight: FontWeight.w900,
                  color: RDSColor.gold, letterSpacing: 2)),
                Text(tCodigosGanados,
                  style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
              ]),
            ]))),
        ),

        // Lista de premios
        Expanded(
          child: user == null
            ? Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
                const Text('🔒', style: TextStyle(fontSize: 48)),
                const SizedBox(height: 12),
                Text(tIniciarSesionPremios,
                  style: const TextStyle(color: RDSColor.textMuted, fontSize: 14)),
              ]))
            : StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                  .collection('usuarios').doc(user.uid)
                  .collection('premios')
                  .orderBy('fecha', descending: true)
                  .snapshots(),
                builder: (ctx, snap) {
                  if (snap.connectionState == ConnectionState.waiting)
                    return const Center(child: CircularProgressIndicator(color: RDSColor.gold));
                  final premios = snap.data?.docs ?? [];
                  if (premios.isEmpty)
                    return Center(child: Column(mainAxisSize: MainAxisSize.min, children: [
                      const Text('🏆', style: TextStyle(fontSize: 52)),
                      const SizedBox(height: 12),
                      Text(tSinPremios, style: const TextStyle(color: RDSColor.textPrimary, fontSize: 16, fontWeight: FontWeight.w700)),
                      const SizedBox(height: 6),
                      Text(tCompletaRutaPremio,
                        style: const TextStyle(color: RDSColor.textMuted, fontSize: 13), textAlign: TextAlign.center),
                    ]));
                  // Deduplicar premios por rutaNombre — evitar QR repetidos
                  final _seenRutas = <String>{};
                  final premiosUnicos = premios.where((doc) {
                    final d = doc.data() as Map<String, dynamic>;
                    final rn = d['rutaNombre']?.toString() ?? doc.id;
                    return _seenRutas.add(rn);
                  }).toList();
                  return ListView.builder(
                    padding: const EdgeInsets.all(16),
                    itemCount: premiosUnicos.length,
                    itemBuilder: (ctx, i) {
                      final data = premiosUnicos[i].data() as Map<String, dynamic>;
                      final canjeado = data['canjeado'] ?? false;
                      return Container(
                        margin: const EdgeInsets.only(bottom: 12),
                        padding: const EdgeInsets.all(16),
                        decoration: BoxDecoration(
                          color: RDSColor.card,
                          borderRadius: BorderRadius.circular(16),
                          border: Border.all(color: canjeado
                            ? Colors.white.withOpacity(0.06)
                            : RDSColor.gold.withOpacity(0.3))),
                        child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                          Row(children: [
                            // Insignia ilustrada si existe
                            data['insigniaImg'] != null
                              ? Image.asset(data['insigniaImg'], width: 56, height: 56,
                                  fit: BoxFit.contain,
                                  errorBuilder: (_, __, ___) =>
                                    Text(data['emoji'] ?? '🏆', style: const TextStyle(fontSize: 28)))
                              : Text(data['emoji'] ?? '🏆', style: const TextStyle(fontSize: 28)),
                            const SizedBox(width: 10),
                            Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                              Text(data['rutaNombre'] ?? '',
                                style: const TextStyle(color: RDSColor.textPrimary, fontSize: 13, fontWeight: FontWeight.w700)),
                              Text(data['insignia'] ?? '',
                                style: const TextStyle(color: RDSColor.textMuted, fontSize: 11)),
                            ])),
                            Container(
                              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                              decoration: BoxDecoration(
                                color: canjeado ? RDSColor.textMuted.withOpacity(0.1) : RDSColor.green.withOpacity(0.15),
                                borderRadius: BorderRadius.circular(RDSRadius.xl)),
                              child: Text(canjeado ? 'Canjeado' : 'Disponible',
                                style: TextStyle(color: canjeado ? RDSColor.textMuted : RDSColor.green,
                                  fontSize: 10, fontWeight: FontWeight.w700))),
                          ]),
                          const SizedBox(height: 12),
                          // Código
                          Container(
                            width: double.infinity,
                            padding: const EdgeInsets.all(12),
                            decoration: BoxDecoration(
                              color: RDSColor.surface,
                              borderRadius: BorderRadius.circular(10),
                              border: Border.all(color: RDSColor.gold.withOpacity(0.2))),
                            child: Column(children: [
                              Text(data['codigo'] ?? '',
                                style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w900,
                                  color: RDSColor.gold, letterSpacing: 3)),
                              const SizedBox(height: 6),
                              // Mini QR
                              Container(
                                padding: const EdgeInsets.all(8),
                                decoration: BoxDecoration(color: Colors.white, borderRadius: BorderRadius.circular(8)),
                                child: QrImageView(
                                  data: 'RUTERO-MDE|CODIGO:${data['codigo']}|RUTA:${data['rutaNombre']}',
                                  version: QrVersions.auto, size: 80,
                                  backgroundColor: Colors.white)),
                            ])),
                          const SizedBox(height: 10),
                          Text(data['premio'] ?? '',
                            style: const TextStyle(color: RDSColor.textMuted, fontSize: 11, height: 1.4)),
                        ]));
                    });
                })),
      ]),
    );
  }
}

// ─────────────────────────────────────────
//  COMPRA SCREEN — Pantalla de compra de ruta
// ─────────────────────────────────────────
class CompraScreen extends StatefulWidget {
  final Map<String, dynamic> ruta;
  const CompraScreen({super.key, required this.ruta});
  @override
  State<CompraScreen> createState() => _CompraScreenState();
}

class _CompraScreenState extends State<CompraScreen> {
  String _metodoPago = 'nequi';
  bool _procesando = false;

  // ── Genera firma de integridad para Wompi ──
  String _generarFirmaWompi({
    required String referencia,
    required int montoEnCentavos,
    required String moneda,
  }) {
    final cadena = '$referencia${montoEnCentavos}${moneda}$kWompiIntegrityKey';
    final bytes = utf8.encode(cadena);
    final digest = sha256.convert(bytes);
    return digest.toString();
  }

  Future<void> _procesarPago() async {
    setState(() => _procesando = true);
    try {
      // Generar referencia única: RUT-{uid}-{timestamp}
      final uid = AuthService.currentUser?.uid ?? 'anonimo';
      final timestamp = DateTime.now().millisecondsSinceEpoch;
      final nombreRuta = widget.ruta['nombre']?.toString()
        .replaceAll(' ', '_').toUpperCase() ?? 'RUTA';
      final referencia = 'RUT-${nombreRuta.substring(0, nombreRuta.length.clamp(0, 8))}-$timestamp';

      // Precio en centavos COP — los precios están en COP formato '\$21.900'
      // Limpiar: '\$21.900' → '21900' → 21900 → × 100 = 2190000 centavos
      final precioRaw = widget.ruta['precio'];
      final precioStr = precioRaw?.toString()
          .replaceAll('\$', '').replaceAll(',', '').replaceAll('.', '')
          .trim() ?? '10000';
      final precioCOP = precioRaw is num
          ? precioRaw.toDouble()
          : double.tryParse(precioStr) ?? 10000.0;
      final montoEnCentavos = (precioCOP * 100).toInt();
      const moneda = 'COP';

      // Firma de integridad
      final firma = _generarFirmaWompi(
        referencia: referencia,
        montoEnCentavos: montoEnCentavos,
        moneda: moneda,
      );

      // URL del checkout Wompi
      final urlWompi = Uri.https('checkout.wompi.co', '/p/', {
        'public-key':         kWompiPublicKey,
        'currency':           moneda,
        'amount-in-cents':    montoEnCentavos.toString(),
        'reference':          referencia,
        'signature:integrity': firma,
        'redirect-url':       kWompiRedirectUrl,
      });

      // Guardar intención de pago en Firestore ANTES de abrir Wompi
      if (AuthService.currentUser != null) {
        await FirebaseFirestore.instance
          .collection('pagos_pendientes')
          .doc(referencia)
          .set({
            'uid':        uid,
            'referencia': referencia,
            'rutaNombre': widget.ruta['nombre'],
            'emoji':      widget.ruta['emoji'],
            'precioUSD':  precioCOP,
            'moneda':     moneda,
            'estado':     'pendiente',
            'sandbox':    kWompiSandbox,
            'fechaInicio': FieldValue.serverTimestamp(),
          });
      }

      setState(() => _procesando = false);

      // DEBUG — ver URL exacta en consola antes de abrir
      // Wompi params generados — omitidos del log por seguridad

      // Abrir checkout Wompi en navegador del dispositivo
      if (await canLaunchUrl(urlWompi)) {
        await launchUrl(urlWompi, mode: LaunchMode.externalApplication);
        // Mostrar diálogo de espera — el turista vuelve tras pagar
        if (mounted) _mostrarEsperandoPago(referencia);
      } else {
        throw Exception('No se pudo abrir Wompi');
      }
    } catch (e) {
      setState(() => _procesando = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error al procesar pago: $e'),
            backgroundColor: RDSColor.accent));
      }
    }
  }

  // Diálogo que aparece mientras el turista paga en Wompi
  void _mostrarEsperandoPago(String referencia) {
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (_) => Dialog(
        backgroundColor: RDSColor.card,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(RDSRadius.xl)),
        child: Padding(
          padding: const EdgeInsets.all(28),
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            const Text('🔒', style: TextStyle(fontSize: 48)),
            const SizedBox(height: 12),
            const Text('PAGO EN PROCESO',
              style: TextStyle(fontSize: 16, fontWeight: FontWeight.w900,
                color: RDSColor.gold, letterSpacing: 2)),
            const SizedBox(height: 8),
            Text(t('Completa el pago en el navegador y regresa aquí.',
                   'Complete the payment in the browser and return here.'),
              textAlign: TextAlign.center,
              style: const TextStyle(color: RDSColor.textMuted, fontSize: 13)),
            const SizedBox(height: 20),
            // Botón: ya pagué
            GestureDetector(
              onTap: () async {
                Navigator.pop(context); // cerrar diálogo espera
                await _verificarPago(referencia);
              },
              child: Container(width: double.infinity,
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  color: RDSColor.green,
                  borderRadius: BorderRadius.circular(14)),
                child: Center(child: Text(
                  t('✅  YA PAGUÉ', '✅  I PAID'),
                  style: const TextStyle(color: Colors.white,
                    fontWeight: FontWeight.w800, fontSize: 14))))),
            const SizedBox(height: 10),
            // Botón: cancelar
            GestureDetector(
              onTap: () => Navigator.pop(context),
              child: Text(t('Cancelar', 'Cancel'),
                style: const TextStyle(color: RDSColor.textMuted, fontSize: 13))),
          ]))));
  }

  // Verificar en Firestore si el pago fue confirmado por Wompi
  Future<void> _verificarPago(String referencia) async {
    setState(() => _procesando = true);
    try {
      // Consultar estado del pago en Firestore
      final doc = await FirebaseFirestore.instance
        .collection('pagos_pendientes')
        .doc(referencia)
        .get();

      final estado = doc.data()?['estado'] ?? 'pendiente';

      if (estado == 'aprobado') {
        // Registrar ruta como comprada
        if (AuthService.currentUser != null) {
          await FirebaseFirestore.instance
            .collection('usuarios')
            .doc(AuthService.currentUser!.uid)
            .collection('rutasCompradas')
            .doc(widget.ruta['nombre'])
            .set({
              'rutaNombre':  widget.ruta['nombre'],
              'emoji':       widget.ruta['emoji'],
              'precio':      widget.ruta['precio'],
              'fechaCompra': FieldValue.serverTimestamp(),
              'referencia':  referencia,
              'pagadoCon':   'wompi',
            });
        }
        setState(() => _procesando = false);
        if (mounted) {
          showDialog(
            context: context,
            barrierDismissible: false,
            builder: (_) => _DialogCompraExitosa(ruta: widget.ruta));
        }
      } else {
        // Pago aún pendiente — sandbox puede tardar
        setState(() => _procesando = false);
        if (mounted) {
          showDialog(
            context: context,
            builder: (_) => AlertDialog(
              backgroundColor: RDSColor.card,
              title: Text(t('Pago pendiente', 'Payment pending'),
                style: const TextStyle(color: RDSColor.gold)),
              content: Text(
                t('Tu pago está siendo procesado. Si ya pagaste, espera unos minutos y vuelve a intentar.',
                  'Your payment is being processed. If you already paid, wait a few minutes and try again.'),
                style: const TextStyle(color: RDSColor.textMuted, fontSize: 13)),
              actions: [
                TextButton(
                  onPressed: () => Navigator.pop(context),
                  child: Text(t('Entendido', 'Got it'),
                    style: const TextStyle(color: RDSColor.green))),
                TextButton(
                  onPressed: () async {
                    Navigator.pop(context);
                    await _verificarPago(referencia);
                  },
                  child: Text(t('Reintentar', 'Retry'),
                    style: const TextStyle(color: RDSColor.gold))),
              ]));
        }
      }
    } catch (e) {
      setState(() => _procesando = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Error verificando pago: $e'),
            backgroundColor: RDSColor.accent));
      }
    }
  }

