            const SizedBox(height: 20),

            // Botón login email
            _GoldButton(
              label: _cargando ? t('Entrando...','Signing in...') : t('ENTRAR CON EMAIL','SIGN IN WITH EMAIL'),
              onTap: _cargando ? () {} : _loginEmail),
            const SizedBox(height: 12),

            // Divider
            Row(children: [
              Expanded(child: Divider(color: Colors.white.withOpacity(0.1))),
              const Padding(padding: EdgeInsets.symmetric(horizontal: 12),
                child: Text('o', style: TextStyle(color: RDSColor.textMuted, fontSize: 12))),
              Expanded(child: Divider(color: Colors.white.withOpacity(0.1))),
            ]),
            const SizedBox(height: 12),

            // Botón Google
            GestureDetector(
              onTap: _cargando ? null : _loginGoogle,
              child: Container(width: double.infinity,
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  color: RDSColor.card,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: Colors.white.withOpacity(0.1))),
                child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                  const Text('G', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w900,
                    color: Color(0xFF4285F4))),
                  const SizedBox(width: 10),
                  Text(tContinuarGoogleUp,
                    style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: RDSColor.textPrimary, letterSpacing: 1)),
                ]))),
            const SizedBox(height: RDSSpace.sm),

            // ── Botón Sign in with Apple — Guideline 4.8 ──────────────
            GestureDetector(
              onTap: _cargando ? null : () async {
                setState(() => _cargando = true);
                final result = await AuthService.loginConApple();
                if (!mounted) return;
                if (result != null) {
                  Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
                    MaterialPageRoute(builder: (_) => const MainShell()), (r) => false);
                } else {
                  setState(() { _cargando = false; _error = t('Error con Apple ID','Apple ID error'); });
                }
              },
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.symmetric(vertical: 14),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: Colors.white.withOpacity(0.1))),
                child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                  const Icon(Icons.apple, color: Colors.black, size: 20),
                  const SizedBox(width: 10),
                  Text(t('Continuar con Apple', 'Continue with Apple'),
                    style: const TextStyle(
                      fontSize: 13, fontWeight: FontWeight.w700,
                      color: Colors.black, letterSpacing: 1)),
                ]))),
            const SizedBox(height: 24),

            // Ir a registro
            Row(mainAxisAlignment: MainAxisAlignment.center, children: [
              Text(tNoTienesCuenta, style: const TextStyle(color: RDSColor.textMuted, fontSize: 13)),
              GestureDetector(
                onTap: () => Navigator.of(context).push(
                  MaterialPageRoute(builder: (_) => const RegisterScreen())),
                child: Text(tCrearCuenta,
                  style: const TextStyle(color: RDSColor.green, fontSize: 13, fontWeight: FontWeight.w700))),
            ]),
            const SizedBox(height: 16),

            // Explorar sin cuenta
            GestureDetector(
              onTap: () => Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
                MaterialPageRoute(builder: (_) => const MainShell()),
                (route) => false),
              child: Text(t('Explorar sin cuenta →','Explore without account →'),
                style: TextStyle(color: RDSColor.textMuted, fontSize: 12,
                  decoration: TextDecoration.underline))),
          ]))
        ]))
      )));
  }
}

// ─────────────────────────────────────────
//  REGISTER SCREEN
// ─────────────────────────────────────────
class RegisterScreen extends StatefulWidget {
  const RegisterScreen({super.key});
  @override
  State<RegisterScreen> createState() => _RegisterScreenState();
}

class _RegisterScreenState extends State<RegisterScreen> {
  final _nombreCtrl = TextEditingController();
  final _emailCtrl = TextEditingController();
  final _passCtrl = TextEditingController();
  final _pass2Ctrl = TextEditingController();
  final _hotelCtrl = TextEditingController();
  bool _cargando = false;
  String _error = '';

  @override
  void dispose() {
    _nombreCtrl.dispose(); _emailCtrl.dispose();
    _passCtrl.dispose(); _pass2Ctrl.dispose();
    super.dispose();
  }

  Future<void> _registrar() async {
    if (_passCtrl.text != _pass2Ctrl.text) {
      setState(() => _error = t('Las contraseñas no coinciden','Passwords do not match'));
      return;
    }
    if (_passCtrl.text.length < 8) {
      setState(() => _error = t('La contraseña debe tener mínimo 8 caracteres','Password must be at least 8 characters'));
      return;
    }
    setState(() { _cargando = true; _error = ''; });
    final cred = await AuthService.registerWithEmail(
      _nombreCtrl.text.trim(), _emailCtrl.text.trim(), _passCtrl.text);
    if (mounted) {
      setState(() => _cargando = false);
      if (cred == null) {
        setState(() => _error = AuthService._ultimoError ?? t('No se pudo crear la cuenta. Intenta de nuevo.','Could not create account. Please try again.'));
      } else {
        await showDialog(
          context: context,
          barrierDismissible: false,
          builder: (_) => AlertDialog(
            backgroundColor: RDSColor.card,
            shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(20)),
            title: Row(children: [
              const Icon(Icons.mark_email_unread_rounded, color: RDSColor.gold, size: 28),
              const SizedBox(width: 12),
              Text(t('Verifica tu correo', 'Verify your email'),
                style: const TextStyle(color: RDSColor.textPrimary, fontSize: 18, fontWeight: FontWeight.w800)),
            ]),
            content: Text(
              t('Te enviamos un correo de verificación. Verifica tu cuenta para acceder a todas las funciones.',
                'We sent a verification email. Verify your account to access all features.'),
              style: const TextStyle(color: RDSColor.textMuted, fontSize: 13, height: 1.5)),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                style: TextButton.styleFrom(
                  backgroundColor: RDSColor.green,
                  shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),
                child: Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
                  child: Text(t('¡Vamos!', "Let's go!"),
                    style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w800)))),
            ]));
        if (mounted) {
          Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
            MaterialPageRoute(builder: (_) => const MainShell()),
            (route) => false);
        }
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF060A04),
      body: Stack(children: [
        // ── Hero header cinematográfico ──
        Positioned(top: 0, left: 0, right: 0, height: 200,
          child: Stack(fit: StackFit.expand, children: [
            Image.asset('assets/images/rutas/ruta_04_metrocable.jpg',
              fit: BoxFit.cover, cacheWidth: 600,
              errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0D200A))),
            Container(decoration: const BoxDecoration(
              gradient: LinearGradient(
                begin: Alignment.topCenter, end: Alignment.bottomCenter,
                stops: [0.0, 0.4, 1.0],
                colors: [Color(0x44000000), Colors.transparent, Color(0xFF060A04)]))),
          ])),

        // ── Contenido scrolleable ──
        SafeArea(child: SingleChildScrollView(
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            // Botón atrás sobre la foto
            Padding(padding: const EdgeInsets.fromLTRB(20, 8, 20, 0),
              child: GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 38, height: 38,
                  decoration: BoxDecoration(
                    color: Colors.black.withOpacity(0.45),
                    shape: BoxShape.circle,
                    border: Border.all(color: Colors.white.withOpacity(0.15))),
                  child: const Center(child: Icon(
                    Icons.arrow_back_ios_new_rounded,
                    color: Colors.white, size: 16))))),

            const SizedBox(height: 120), // espacio para la foto

            Padding(padding: const EdgeInsets.fromLTRB(28, 0, 28, 40),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(tCrearCuenta,
                  style: const TextStyle(
                    fontFamily: 'PlayfairDisplay',
                    fontSize: 30, fontWeight: FontWeight.w900,
                    color: RDSColor.textPrimary)),
                const SizedBox(height: 4),
                Text(tUneteRuteros,
                  style: const TextStyle(fontSize: 13, color: RDSColor.textMuted)),
                const SizedBox(height: 28),

                _InputField(ctrl: _nombreCtrl, hint: 'Nombre completo', emoji: '👤'),
                const SizedBox(height: 12),
                _InputField(ctrl: _emailCtrl, hint: tCorreo,
                  emoji: '📧', keyboardType: TextInputType.emailAddress),
                const SizedBox(height: 12),
                _InputField(ctrl: _passCtrl, hint: 'Contraseña (mín. 8 caracteres)',
                  emoji: '🔒', obscure: true),
                const SizedBox(height: 12),
                _InputField(ctrl: _pass2Ctrl, hint: 'Confirmar contraseña',
                  emoji: '🔒', obscure: true),
                const SizedBox(height: 8),

                if (_error.isNotEmpty)
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: RDSColor.accent.withOpacity(0.1),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: RDSColor.accent.withOpacity(0.3))),
                    child: Text(_error,
                      style: const TextStyle(color: RDSColor.accent, fontSize: 12))),
                const SizedBox(height: 20),

                _GoldButton(
                  label: _cargando ? 'Creando cuenta...' : 'CREAR MI CUENTA',
                  onTap: _cargando ? () {} : _registrar),
              ])),
          ])))
      ]));
  }
}

// ─────────────────────────────────────────
//  CONVERSIÓN — Bottom Sheet para usuarios sin cuenta
//  Aparece cuando un anónimo intenta validar un sitio.
//  Retorna: true → ir a Registro · false → ir a Login · null → continuar sin cuenta
// ─────────────────────────────────────────
Future<bool?> mostrarBottomSheetConversion(BuildContext context) async {
  return showModalBottomSheet<bool>(
    context: context,
    backgroundColor: Colors.transparent,
    isScrollControlled: true,
    builder: (ctx) => Container(
      decoration: const BoxDecoration(
        color: Color(0xFF1A1A1A),
        borderRadius: BorderRadius.vertical(top: Radius.circular(28)),
      ),
      padding: const EdgeInsets.fromLTRB(28, 20, 28, 40),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        // Handle
        Container(width: 40, height: 4,
          decoration: BoxDecoration(color: Colors.white24, borderRadius: BorderRadius.circular(2))),
        const SizedBox(height: 24),
        const Text('🏆', style: TextStyle(fontSize: 52)),
        const SizedBox(height: 12),
        Text(
          t('¡Estás en el lugar!', "You're at the spot!"),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 22, fontWeight: FontWeight.w900),
          textAlign: TextAlign.center),
        const SizedBox(height: 8),
        Text(
          t(
            'Crea una cuenta gratis para guardar tu progreso,\ninsignias y puntos.',
            'Create a free account to save your progress,\nbadges and points.',
          ),
          style: const TextStyle(color: RDSColor.textMuted, fontSize: 14, height: 1.5),
          textAlign: TextAlign.center),
        const SizedBox(height: 28),
        // Botón principal — Registrarse
        GestureDetector(
          onTap: () => Navigator.pop(ctx, true),
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 16),
            decoration: BoxDecoration(
              gradient: const LinearGradient(colors: [RDSColor.green, Color(0xFF3D8B55)]),
              borderRadius: BorderRadius.circular(14),
              boxShadow: [BoxShadow(color: RDSColor.green.withOpacity(0.35), blurRadius: 20, offset: const Offset(0, 8))]),
            child: Text(
              t('🌿  CREAR CUENTA GRATIS', '🌿  CREATE FREE ACCOUNT'),
              textAlign: TextAlign.center,
              style: const TextStyle(color: Colors.white, fontSize: 15, fontWeight: FontWeight.w800, letterSpacing: 1.2)))),
        const SizedBox(height: 12),
        // Botón secundario — Ya tengo cuenta
        GestureDetector(
          onTap: () => Navigator.pop(ctx, false),
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 14),
            decoration: BoxDecoration(
              border: Border.all(color: Colors.white12),
              borderRadius: BorderRadius.circular(14)),
            child: Text(
              t('Ya tengo cuenta — Iniciar sesión', 'I have an account — Sign in'),
              textAlign: TextAlign.center,
              style: const TextStyle(color: RDSColor.textMuted, fontSize: 14, fontWeight: FontWeight.w600)))),
        const SizedBox(height: 12),
        // Escape — continuar sin guardar
        GestureDetector(
          onTap: () => Navigator.pop(ctx, null),
          child: Text(
            t('Continuar sin guardar →', 'Continue without saving →'),
            style: TextStyle(
              color: RDSColor.textMuted.withOpacity(0.5),
              fontSize: 12,
              decoration: TextDecoration.underline))),
      ]),
    ),
  );
}

class _InputField extends StatelessWidget {
  final TextEditingController ctrl;
  final String hint;
  final String? emoji;
  final IconData? icon;
  final bool obscure;
  final TextInputType? keyboardType;
  final Widget? suffix;
  const _InputField({
    required this.ctrl, required this.hint,
    this.emoji, this.icon,
    this.obscure = false, this.keyboardType, this.suffix});
  @override
  Widget build(BuildContext context) => Container(
    decoration: BoxDecoration(
      color: RDSColor.surface,
      borderRadius: RDSRadius.bMd,
      border: Border.all(color: RDSColor.borderSubtle)),
    child: TextField(
      controller: ctrl, obscureText: obscure, keyboardType: keyboardType,
      style: const TextStyle(color: RDSColor.textPrimary, fontSize: 14),
      decoration: InputDecoration(
        hintText: hint,
        hintStyle: const TextStyle(color: RDSColor.textMuted, fontSize: 13),
        prefixIcon: icon != null
          ? Icon(icon, color: RDSColor.textMuted, size: 18)
          : Padding(padding: const EdgeInsets.all(12),
              child: Text(emoji ?? '', style: const TextStyle(fontSize: 16))),
        suffixIcon: suffix != null
          ? Padding(padding: const EdgeInsets.all(12), child: suffix)
          : null,
        border: InputBorder.none,
        contentPadding: const EdgeInsets.symmetric(vertical: RDSSpace.md))));
}

