    required this.nombre,
    required this.nombreEN,
    required this.detalle,
    required this.detalleEN,
    required this.telefono,
    required this.emoji,
    this.direccionMaps,
    this.alquilerVehiculos,
    this.alquilerVehiculosEN,
  });
}

