class ServiciosScreen extends StatelessWidget {
  const ServiciosScreen({super.key});

  Future<void> _abrirWhatsApp(String numero, BuildContext context) async {
    final numeroLimpio = numero.replaceAll(RegExp(r'[^\d+]'), '');
    final mensaje = Uri.encodeComponent(
      t('Hola, vengo de Rutero MDE y me gustaría información sobre sus servicios.',
        'Hi, I found you through Rutero MDE and would like information about your services.'));
    final uri = Uri.parse('https://wa.me/$numeroLimpio?text=$mensaje');
    if (await canLaunchUrl(uri)) {
      await launchUrl(uri, mode: LaunchMode.externalApplication);
    } else if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('No se pudo abrir WhatsApp', 'Could not open WhatsApp')),
        backgroundColor: Colors.red));
    }
  }

  // Construye la card de servicio desde Firestore o desde datos hardcodeados
  Widget _buildCard(Map<String, dynamic> data, BuildContext context) {
    final nombre = data['nombre']?.toString() ?? '';
    final empresa = data['empresa']?.toString() ?? '';
    final descripcion = kLang == 'en'
      ? (data['descripcionEN']?.toString() ?? data['descripcion']?.toString() ?? '')
      : (data['descripcion']?.toString() ?? '');
    final whatsapp = data['whatsapp']?.toString() ?? '';
    final idiomas = kLang == 'en'
      ? (data['idiomasEN']?.toString() ?? data['idiomas']?.toString() ?? '')
      : (data['idiomas']?.toString() ?? '');
    final emoji = data['emoji']?.toString() ?? '🛎️';
    final logoAsset = data['logoAsset']?.toString();
    final colorHex = data['color']?.toString() ?? '#1B6B3A';
    Color color;
    try {
      color = Color(int.parse(colorHex.replaceAll('#', '0xFF')));
    } catch (_) {
      color = RDSColor.green;
    }

    return Container(
      margin: const EdgeInsets.only(bottom: 14),
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: RDSColor.card, borderRadius: BorderRadius.circular(16),
        border: Border.all(color: color.withOpacity(0.25))),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          Container(
            width: 56, height: 56,
            decoration: BoxDecoration(
              shape: BoxShape.circle,
              color: color == const Color(0xFFFFD000) ? Colors.black : Colors.white,
              border: Border.all(color: color.withOpacity(0.4), width: 1.5),
              boxShadow: [BoxShadow(color: color.withOpacity(0.20), blurRadius: 8)]),
            child: ClipOval(child: logoAsset != null
              ? Padding(
                  padding: const EdgeInsets.all(6),
                  child: Image.asset(logoAsset, fit: BoxFit.contain, width: 44, height: 44,
                    errorBuilder: (_, __, ___) => Center(child: Text(emoji, style: const TextStyle(fontSize: 22)))))
              : Center(child: Text(emoji, style: const TextStyle(fontSize: 22))))),
          const SizedBox(width: 12),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(nombre, style: const TextStyle(color: RDSColor.textPrimary, fontSize: 14, fontWeight: FontWeight.w800)),
            Text(empresa, style: TextStyle(color: color, fontSize: 11, fontWeight: FontWeight.w700)),
          ])),
        ]),
        const SizedBox(height: 10),
        if (idiomas.isNotEmpty)
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
            decoration: BoxDecoration(
              color: color.withOpacity(0.08), borderRadius: BorderRadius.circular(8)),
            child: Text(idiomas, style: TextStyle(color: color, fontSize: 11, fontWeight: FontWeight.w700))),
        const SizedBox(height: 10),
        if (descripcion.isNotEmpty)
          Text(descripcion, style: TextStyle(color: RDSColor.textMuted.withOpacity(0.85), fontSize: 12, height: 1.5)),
        const SizedBox(height: 14),
        if (whatsapp.isNotEmpty)
          GestureDetector(
            onTap: () => _abrirWhatsApp(whatsapp, context),
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(vertical: 12),
              decoration: BoxDecoration(
                color: const Color(0xFF25D366).withOpacity(0.12),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: const Color(0xFF25D366).withOpacity(0.4))),
              child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                const Text('💬', style: TextStyle(fontSize: 16)),
                const SizedBox(width: 8),
                Text(t('Contactar por WhatsApp', 'Contact via WhatsApp'),
                  style: const TextStyle(color: Color(0xFF25D366), fontSize: 13, fontWeight: FontWeight.w800)),
              ])))
        else if (empresa == 'Whoosh')
          GestureDetector(
            onTap: () async {
              final uri = Uri.parse('https://whoosh.bike/es_la');
              if (await canLaunchUrl(uri)) {
                await launchUrl(uri, mode: LaunchMode.externalApplication);
              }
            },
            child: Container(
              width: double.infinity,
              padding: const EdgeInsets.symmetric(vertical: 12),
              decoration: BoxDecoration(
                color: const Color(0xFFFFD000).withOpacity(0.12),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: const Color(0xFFFFD000).withOpacity(0.5))),
              child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                const Text('🛴', style: TextStyle(fontSize: 16)),
                const SizedBox(width: 8),
                Text(t('Ver app en whoosh.bike', 'Get app at whoosh.bike'),
                  style: const TextStyle(color: Color(0xFFFFD000), fontSize: 13, fontWeight: FontWeight.w800)),
              ]))),
      ]));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        Container(
          decoration: BoxDecoration(
            color: RDSColor.base,
            border: Border(bottom: BorderSide(color: RDSColor.gold.withOpacity(0.1)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
            child: Row(children: [
              GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06), shape: BoxShape.circle,
                    border: Border.all(color: RDSColor.gold.withOpacity(0.2))),
                  child: const Center(child: Icon(Icons.arrow_back_ios_new_rounded, color: RDSColor.textPrimary, size: 18)))),
              const SizedBox(width: 12),
              Expanded(child: Text(t('Servicios para viajeros', 'Traveler services'),
                style: const TextStyle(fontFamily: 'PlayfairDisplay',
                  fontSize: 18, fontWeight: FontWeight.w900, color: RDSColor.textPrimary))),
              const Text('🛎️', style: TextStyle(fontSize: 20)),
            ])))),
        Expanded(child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 16, 20, 40),
          children: [
            Text(t('Servicios verificados por Rutero MDE', 'Services verified by Rutero MDE'),
              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                color: RDSColor.textMuted, letterSpacing: 1.5)),
            const SizedBox(height: 4),
            Text(t('Contacta directamente por WhatsApp — di que vienes de Rutero MDE',
                'Contact directly via WhatsApp — mention you come from Rutero MDE'),
              style: TextStyle(color: RDSColor.textMuted.withOpacity(0.6), fontSize: 11)),
            const SizedBox(height: 16),
            // Leer de Firestore, con fallback a datos hardcodeados
            StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                .collection('serviciosViajero')
                .where('activo', isEqualTo: true)
                .snapshots(),
              builder: (ctx, snap) {
                // Mientras carga o si Firestore está vacío → usar hardcodeados
                final List<Map<String, dynamic>> items = [];
                if (snap.hasData && snap.data!.docs.isNotEmpty) {
                  for (final doc in snap.data!.docs) {
                    items.add(doc.data() as Map<String, dynamic>);
                  }
                } else {
                  // Fallback a hardcodeados
                  for (final s in kServiciosViajero) {
                    items.add({
                      'nombre': s.nombre, 'empresa': s.empresa,
                      'descripcion': s.descripcion, 'descripcionEN': s.descripcionEN,
                      'whatsapp': s.whatsapp, 'emoji': s.emoji,
                      'logoAsset': s.logoAsset, 'idiomas': s.idiomas, 'idiomasEN': s.idiomasEN,
                      'color': '#${s.color.value.toRadixString(16).substring(2).toUpperCase()}',
                    });
                  }
                }
                return Column(children: items.map((d) => _buildCard(d, context)).toList());
              }),
            const SizedBox(height: 24),
            // ── Banner reclutamiento de servicios ──────────────────────────
            GestureDetector(
              onTap: () async {
                final uri = Uri.parse('mailto:paulflopezp@gmail.com?subject=Quiero%20ofrecer%20un%20servicio%20en%20Rutero%20MDE');
                if (await canLaunchUrl(uri)) {
                  await launchUrl(uri, mode: LaunchMode.externalApplication);
                }
              },
              child: Container(
                width: double.infinity,
                padding: const EdgeInsets.all(18),
                decoration: BoxDecoration(
                  color: RDSColor.card,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: RDSColor.gold.withOpacity(0.35)),
                  gradient: LinearGradient(
                    colors: [RDSColor.gold.withOpacity(0.06), RDSColor.card],
                    begin: Alignment.topLeft, end: Alignment.bottomRight)),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Text('🤝', style: TextStyle(fontSize: 22)),
                    const SizedBox(width: 10),
                    Expanded(child: Text(
                      t('¿Tenés un servicio para viajeros?', 'Do you offer a traveler service?'),
                      style: const TextStyle(color: RDSColor.gold, fontSize: 14, fontWeight: FontWeight.w900))),
                  ]),
                  const SizedBox(height: 8),
                  Text(
                    t('Si ofrecés transporte, guías, hospedaje u otros servicios para turistas en Medellín, contáctanos. Queremos conectarte con viajeros de todo el mundo.',
                      'If you offer transport, guides, accommodation or other traveler services in Medellín, reach out. We want to connect you with travelers from around the world.'),
                    style: TextStyle(color: RDSColor.textMuted.withOpacity(0.8), fontSize: 12, height: 1.5)),
                  const SizedBox(height: 12),
                  Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(vertical: 11),
                    decoration: BoxDecoration(
                      color: RDSColor.gold.withOpacity(0.12),
                      borderRadius: BorderRadius.circular(10),
                      border: Border.all(color: RDSColor.gold.withOpacity(0.4))),
                    child: Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                      const Text('✉️', style: TextStyle(fontSize: 15)),
                      const SizedBox(width: 8),
                      Text(t('Contáctanos — paulflopezp@gmail.com', 'Contact us — paulflopezp@gmail.com'),
                        style: const TextStyle(color: RDSColor.gold, fontSize: 12, fontWeight: FontWeight.w800)),
                    ])),
                ]))),
          ])),
      ]));
  }
}


// ═══════════════════════════════════════════════════════════════════════════
//  🗓️ RUTERO PLANNER IA
//  Itinerario personalizado generado por Claude según fechas, intereses y
//  presupuesto del viajero. Versión gratuita: hasta 2 días.
// ═══════════════════════════════════════════════════════════════════════════

// ── Modelo de itinerario ─────────────────────────────────────────────────
class _PlannerBloque {
  final String periodo;  // 'Mañana', 'Tarde', 'Noche'
  final String periodoEN;
  final String emoji;
  final String rutaNombre;
  final String descripcion;
  final String duracion;
  final String precio;
  final String transporte;
  const _PlannerBloque({
    required this.periodo, required this.periodoEN, required this.emoji,
    required this.rutaNombre, required this.descripcion,
    required this.duracion, required this.precio, required this.transporte,
  });
}

class _PlannerDia {
  final int numero;
  final String fecha;
  final List<_PlannerBloque> bloques;
  final bool esFeria;
  const _PlannerDia({
    required this.numero, required this.fecha,
    required this.bloques, this.esFeria = false,
  });
}

// ── Pantalla principal del Planner ────────────────────────────────────────
class PlannerScreen extends StatefulWidget {
  const PlannerScreen({super.key});
  @override
  State<PlannerScreen> createState() => _PlannerScreenState();
}

class _PlannerScreenState extends State<PlannerScreen> {
  int _paso = 0;
  Map<String, dynamic>? _itinerarioPrevio;
  int _diasPrevio = 1;
  bool _cargandoPrevio = true;

  @override
  void initState() {
    super.initState();
    _cargarItinerarioPrevio();
  }

  Future<void> _cargarItinerarioPrevio() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final json = prefs.getString('planner_ultimo_itinerario');
      final dias = prefs.getInt('planner_ultimo_dias') ?? 1;
      if (json != null && mounted) {
        setState(() {
          _itinerarioPrevio = jsonDecode(json) as Map<String, dynamic>;
          _diasPrevio = dias;
        });
      }
    } catch (e) {
      debugPrint('Planner previo: $e');
    } finally {
      if (mounted) setState(() => _cargandoPrevio = false);
    }
  }

  Future<void> _guardarItinerario(Map<String, dynamic> data, int dias) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('planner_ultimo_itinerario', jsonEncode(data));
      await prefs.setInt('planner_ultimo_dias', dias);
    } catch (e) { debugPrint('Planner guardar: $e'); }
  }

  Future<void> _borrarItinerarioPrevio() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.remove('planner_ultimo_itinerario');
      await prefs.remove('planner_ultimo_dias');
      if (mounted) setState(() => _itinerarioPrevio = null);
    } catch (_) {}
  }

  // ── Estado del formulario ──────────────────────────────────────────
  // _paso: 0-3 = form, 4 = resumen

  // Paso 0 — Cuándo y cuánto
  int _dias = 1;
  DateTime _llegada = DateTime.now();
  DateTime _salida  = DateTime.now().add(const Duration(days: 1));
  String _horaLlegada = 'Mañana';
  String _horaSalida  = 'No sé aún';

  // Paso 1 — Dónde y cómo te movés
  String _zonaHotel   = 'El Poblado';
  String _alojamiento = 'Hotel';
  String _transporte  = 'Mix';
  String _ritmo       = 'Moderado';

  // Paso 2 — Qué querés vivir
  final Set<String> _intereses = {};
  String _tipoExperiencia  = 'Turista clásico';
  String _horarioPreferido = 'Mañanero';

  // Paso 3 — Quién sos como viajero
  String _compania    = 'Solo';
  String _presupuesto = 'Medio';
  bool   _primeraVez  = true;
  String _descuento   = 'Ninguno';

  // ── Opciones ───────────────────────────────────────────────────────
  final List<String> _zonasHotel = ['El Poblado', 'Laureles', 'Centro', 'Otro'];

  final List<Map<String, String>> _interesesOpts = [
    {'emoji': '🏛️', 'label': 'Cultura',       'labelEN': 'Culture'},
    {'emoji': '🍽️', 'label': 'Gastronomía',   'labelEN': 'Food'},
    {'emoji': '🌿', 'label': 'Naturaleza',     'labelEN': 'Nature'},
    {'emoji': '🎨', 'label': 'Arte',           'labelEN': 'Art'},
    {'emoji': '🌙', 'label': 'Vida nocturna',  'labelEN': 'Nightlife'},
    {'emoji': '⚡', 'label': 'Aventura',       'labelEN': 'Adventure'},
    {'emoji': '📸', 'label': 'Fotografía',     'labelEN': 'Photography'},
    {'emoji': '🛍️', 'label': 'Compras',        'labelEN': 'Shopping'},
  ];

  // ── Helpers ────────────────────────────────────────────────────────
  bool get _esFeria {
    final inicio = DateTime(kFeriaAno, 7, 31);
    final fin    = DateTime(kFeriaAno, 8, 9, 23, 59);
    return _llegada.isAfter(inicio.subtract(const Duration(days: 1))) &&
           _llegada.isBefore(fin);
  }

  String _formatFecha(DateTime d) {
    final meses = kLang == 'en'
      ? ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
      : ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
    return '${d.day} ${meses[d.month - 1]}';
  }

  int get _totalPasos => 5;

  void _siguiente() {
    if (_paso == 2 && _intereses.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Elegí al menos un interés', 'Choose at least one interest')),
        backgroundColor: RDSColor.accent));
      return;
    }
    if (_paso < 4) setState(() => _paso++);
    else _generarItinerario();
  }

  void _anterior() {
    if (_paso > 0) setState(() => _paso--);
    else Navigator.pop(context);
  }

  // ── Generación ─────────────────────────────────────────────────────
  Future<void> _generarItinerario() async {
    Future.microtask(() async {
      try {
        final uid    = FirebaseAuth.instance.currentUser?.uid ?? 'anonimo';
        final nombre = FirebaseAuth.instance.currentUser?.displayName ?? 'Viajero';
        await FirebaseFirestore.instance.collection('planner_metricas').add({
          'uid': uid, 'nombre': nombre,
          'timestamp': FieldValue.serverTimestamp(),
          'dias': _dias,
          'llegada': _formatFecha(_llegada), 'salida': _formatFecha(_salida),
          'horaLlegada': _horaLlegada,       'horaSalida': _horaSalida,
          'zonaHotel': _zonaHotel,           'alojamiento': _alojamiento,
          'transporte': _transporte,          'ritmo': _ritmo,
          'intereses': _intereses.toList(),
          'tipoExperiencia': _tipoExperiencia,
          'horarioPreferido': _horarioPreferido,
          'compania': _compania,              'presupuesto': _presupuesto,
          'primeraVez': _primeraVez,          'descuento': _descuento,
          'idioma': kLang,                    'esFeria': _esFeria,
        });
      } catch (_) {}
    });

    final rutasDisponibles = RutasService().rutas
      .where((r) => r['activa'] != false && r['pausada'] != true)
      .map((r) => '- ${r['nombre']}: ${r['subtitulo'] ?? ''} (${r['tiempo'] ?? ''}, ${r['zona'] ?? ''})')
      .take(30).join('\n');

    final interesesStr   = _intereses.join(', ');
    final feriaStr       = _esFeria ? '\n- Las fechas coinciden con la Feria de las Flores 2026 (31 jul – 9 ago). Incluir eventos de Feria relevantes.' : '';
    // Hotel partner — priorizar rutas del hotel en Felo
    final hotelPartner = await HotelPartnerService.getHotelActivo();
    final hotelStr = hotelPartner != null
      ? '\n- El turista se hospeda en \${hotelPartner.nombre} (zona \${hotelPartner.zona}). Priorizar rutas cercanas: \${hotelPartner.rutasDestacadas.join(", ")}.'
      : '';

    final familiarStr    = _compania == 'Familia'
      ? '\n- VIAJA CON FAMILIA Y NIÑOS: priorizar rutas marcadas como familiares. Evitar vida nocturna, bares y actividades largas. Incluir pausas cada 2 horas. Máx 2-3 sitios por bloque. Preferir Metrocable & Arví, Fincas, Parques, Transformación Urbana, Guatapé, Santa Fe de Antioquia, museos interactivos.'
      : '';
    final descuentoStr   = _descuento != 'Ninguno' ? '\n- Descuento aplicable: $_descuento.' : '';
    final horarioStr     = '\n- Horario preferido: $_horarioPreferido.';
    final ritmoStr       = '\n- Ritmo: $_ritmo. ${_ritmo == 'Relajado' ? 'Máx 2 actividades/día.' : _ritmo == 'Intenso' ? 'Aprovechar cada franja.' : 'Balance actividad-pausa.'}';
    final transporteStr  = '\n- Transporte preferido: $_transporte.';
    final experienciaStr = '\n- Tipo de experiencia: $_tipoExperiencia.';

    final promptES = '''
Sos Rutero MDE, la IA de turismo de Medellín, Colombia.
Creá un itinerario personalizado de $_dias día(s) (versión GRATUITA: máximo 2 días) para un viajero con estos datos:
- Llegada: ${_formatFecha(_llegada)}, Salida: ${_formatFecha(_salida)}, Hora llegada: $_horaLlegada, Hora salida último día: $_horaSalida
- Zona alojamiento: $_zonaHotel, Tipo: $_alojamiento
- Intereses: $interesesStr
- Viaja: $_compania
- Presupuesto: $_presupuesto (${_presupuesto == 'Bajo' ? r'$40K-120K COP/día' : _presupuesto == 'Medio' ? r'$120K-320K COP/día' : r'+$320K COP/día'})
- Primera vez en Medellín: ${_primeraVez ? 'SÍ' : 'NO'}$hotelStr$feriaStr$familiarStr$descuentoStr$horarioStr$ritmoStr$transporteStr$experienciaStr
${_horaSalida != 'No sé aún' ? '- Hora salida último día: $_horaSalida. Ajustá actividades para llegar a tiempo.' : ''}
${_primeraVez ? '\nIMPORTANTE: incluir íconos de Medellín mapeados a rutas Rutero: Provenza=HUELLAS VIVAS DE EL POBLADO, Pueblito Paisa=DEL ORIGEN PAISA A LA MEDELLIN MODERNA, Escaleras=RUTA TRANSFORMACION URBANA, Botero=DEL ORIGEN PAISA A LA MEDELLIN MODERNA. Si 2+ días incluir RUTA GUATAPE.' : ''}

Rutas disponibles:
$rutasDisponibles

Respondé SOLO con JSON válido (sin markdown):
{"saludo":"...","dias":[{"numero":1,"fecha":"...","esFeria":false,"bloques":[{"periodo":"Mañana","periodoEN":"Morning","emoji":"🌅","rutaNombre":"NOMBRE EXACTO","descripcion":"...","duracion":"2-3 horas","precio":"Gratis","transporte":"Metro L.A → Est. Acevedo"}]}],"resumen":{"rutas":3,"horasTotales":"6-8 horas","costoEstimado":"~40.000 COP","puntosPosibles":350,"insignias":["Explorador Urbano"]},"tip":"..."}
''';

    final promptEN = '''
You are Rutero MDE, a tourism AI for Medellín, Colombia.
Create a personalized ${_dias}-day itinerary (FREE version: max 2 days) for a traveler:
- Arrival: ${_formatFecha(_llegada)}, Departure: ${_formatFecha(_salida)}, Arrival time: $_horaLlegada, Departure time last day: $_horaSalida
- Accommodation zone: $_zonaHotel, Type: $_alojamiento
- Interests: $interesesStr
- Traveling: $_compania
- Budget: $_presupuesto (${_presupuesto == 'Bajo' ? r'USD 10-30/day' : _presupuesto == 'Medio' ? r'USD 30-80/day' : r'over USD 80/day'})
- First time in Medellín: ${_primeraVez ? 'YES' : 'NO'}$hotelStr$feriaStr$familiarStr$descuentoStr$horarioStr$ritmoStr$transporteStr$experienciaStr
${_horaSalida != 'No sé aún' ? '- Departure time last day: $_horaSalida. Adjust activities accordingly.' : ''}
${_primeraVez ? '\nIMPORTANT: include Medellín icons mapped to routes: Provenza=HUELLAS VIVAS DE EL POBLADO, Pueblito Paisa=DEL ORIGEN PAISA A LA MEDELLIN MODERNA, Comuna 13=RUTA TRANSFORMACION URBANA, Botero=DEL ORIGEN PAISA A LA MEDELLIN MODERNA. If 2+ days add RUTA GUATAPE.' : ''}

Available routes:
$rutasDisponibles

Respond ONLY with valid JSON (no markdown):
{"saludo":"...","dias":[{"numero":1,"fecha":"...","esFeria":false,"bloques":[{"periodo":"Morning","periodoEN":"Morning","emoji":"🌅","rutaNombre":"EXACT NAME","descripcion":"...","duracion":"2-3 hours","precio":"Free","transporte":"Metro L.A → Est. Acevedo"}]}],"resumen":{"rutas":3,"horasTotales":"6-8 hours","costoEstimado":"~40,000 COP","puntosPosibles":350,"insignias":["Urban Explorer"]},"tip":"..."}
''';

    final prompt = kLang == 'en' ? promptEN : promptES;

    if (!mounted) return;
    final result = await Navigator.of(context).push<Map<String, dynamic>?>(
      MaterialPageRoute(builder: (_) => _PlannerLoadingScreen(prompt: prompt)));

    if (result != null && mounted) {
      await _guardarItinerario(result, _dias);
      Navigator.of(context).pushReplacement(MaterialPageRoute(
        builder: (_) => _PlannerResultScreen(data: result, dias: _dias)));
    }
  }

  // ── Build principal ────────────────────────────────────────────────
  @override
  Widget build(BuildContext context) {
    final pasoLabels = [
      t('Cuándo', 'When'), t('Cómo', 'How'), t('Qué', 'What'),
      t('Quién', 'Who'), t('Resumen', 'Summary'),
    ];

    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        // ── Header conversacional — pregunta como protagonista ──────────
        Container(
          color: RDSColor.base,
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(
              RDSSpace.lg, RDSSpace.sm + 4, RDSSpace.lg, RDSSpace.md),
            child: Column(children: [
              Row(children: [
                // Botón atrás
                GestureDetector(
                  onTap: _anterior,
                  child: Container(
                    width: 36, height: 36,
                    decoration: BoxDecoration(
                      color: RDSColor.surface,
                      shape: BoxShape.circle,
                      border: Border.all(color: RDSColor.borderSubtle)),
                    child: const Icon(RDSIcons.back,
                      color: RDSColor.textPrimary, size: 18))),
                const SizedBox(width: RDSSpace.md),
                // Tag + nombre planner
                Expanded(child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                  Text(t('✦ FELO', '✦ FELO'),
                    style: const TextStyle(fontFamily: 'SpaceGrotesk', fontSize: 10, fontWeight: FontWeight.w700, letterSpacing: 2.0, color: RDSColor.textMuted).copyWith(
                      color: RDSColor.gold, letterSpacing: 2.5)),
                  const SizedBox(height: 2),
                  Text(t('Tu aventura en Medellín',
                         'Your Medellín adventure'),
                    style: RDSType.bodyMd),
                ])),
                // Paso actual — compacto
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: RDSSpace.sm + 4, vertical: RDSSpace.xs + 2),
                  decoration: BoxDecoration(
                    color: RDSColor.gold.withOpacity(0.1),
                    borderRadius: RDSRadius.bFull,
                    border: Border.all(
                      color: RDSColor.gold.withOpacity(0.3))),
                  child: Text('${_paso + 1}/$_totalPasos',
                    style: RDSType.labelSm.copyWith(
                      color: RDSColor.gold))),
              ]),
              const SizedBox(height: RDSSpace.md),
              // Barra de progreso — 5 segmentos
              Row(children: List.generate(_totalPasos, (i) =>
                Expanded(child: AnimatedContainer(
                  duration: RDSDuration.fast, height: 2,
                  margin: EdgeInsets.only(
                    right: i < _totalPasos - 1 ? RDSSpace.xs : 0),
                  decoration: BoxDecoration(
                    color: i < _paso
                      ? RDSColor.gold
                      : i == _paso
                        ? RDSColor.gold.withOpacity(0.6)
                        : RDSColor.borderSubtle,
                    borderRadius: RDSRadius.bFull))))),
            ])))),

        Expanded(child: SingleChildScrollView(
          padding: const EdgeInsets.all(RDSSpace.lg),
          child: Column(children: [

            // ── Banner itinerario previo ──────────────────────────────
            // ── Banner itinerario previo — compacto y limpio ────────────
            if (!_cargandoPrevio && _itinerarioPrevio != null)
              GestureDetector(
                onTap: () => Navigator.of(context).push(MaterialPageRoute(
                  builder: (_) => _PlannerResultScreen(
                    data: _itinerarioPrevio!, dias: _diasPrevio))),
                child: Container(
                  margin: const EdgeInsets.only(bottom: RDSSpace.lg),
                  padding: const EdgeInsets.all(RDSSpace.md),
                  decoration: BoxDecoration(
                    color: RDSColor.surface,
                    borderRadius: RDSRadius.bLg,
                    border: Border.all(
                      color: RDSColor.gold.withOpacity(0.3))),
                  child: Row(children: [
                    Icon(Icons.calendar_today_rounded,
                      color: RDSColor.gold, size: 20),
                    const SizedBox(width: RDSSpace.md),
                    Expanded(child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                      Text(t('Felo guardó un plan para vos',
                             'Felo saved a plan for you'),
                        style: RDSType.headlineMd.copyWith(
                          color: RDSColor.gold)),
                      Text(t('Tocá para verlo', 'Tap to view it'),
                        style: RDSType.bodySm),
                    ])),
                    GestureDetector(
                      onTap: _borrarItinerarioPrevio,
                      child: Padding(
                        padding: const EdgeInsets.all(RDSSpace.sm),
                        child: Icon(RDSIcons.close,
                          color: RDSColor.textMuted, size: 16))),
                    Icon(RDSIcons.actionExplore,
                      color: RDSColor.gold, size: 16),
                  ]))),

            AnimatedSwitcher(
              duration: RDSDuration.fast,
              child: _paso == 0 ? _buildPaso0() :
                     _paso == 1 ? _buildPaso1() :
                     _paso == 2 ? _buildPaso2() :
                     _paso == 3 ? _buildPaso3() : _buildResumen()),
          ]))),

        Container(
          padding: const EdgeInsets.fromLTRB(24, 12, 24, 32),
          decoration: BoxDecoration(
            color: RDSColor.base,
            border: Border(top: BorderSide(color: Colors.white.withOpacity(0.06)))),
          child: _RDSButtonPrimary(
            label: _paso == 0
              ? t('CONTINUAR', 'CONTINUE')
              : _paso == 1
                ? t('CONTINUAR', 'CONTINUE')
                : _paso == 2
                  ? t('CONTINUAR', 'CONTINUE')
                  : _paso == 3
                    ? t('VER MI RESUMEN', 'SEE MY SUMMARY')
                    : t('✦ PREGUNTALE A FELO', '✦ ASK FELO'),
            onTap: _siguiente)),
      ]),
    );
  }

  // ── PASO 0 — Cuándo y cuánto ────────────────────────────────────
  Widget _buildPaso0() {
    final horasLlegada = [
      {'valor': 'Mañana', 'emoji': '🌅', 'label': 'Mañana',  'labelEN': 'Morning',   'sub': 'Antes del mediodía', 'subEN': 'Before noon'},
      {'valor': 'Tarde',  'emoji': '☀️', 'label': 'Tarde',   'labelEN': 'Afternoon', 'sub': '12pm – 6pm',         'subEN': '12pm – 6pm'},
      {'valor': 'Noche',  'emoji': '🌙', 'label': 'Noche',   'labelEN': 'Evening',   'sub': 'Después de las 6pm', 'subEN': 'After 6pm'},
    ];
    return Column(key: const ValueKey(0), crossAxisAlignment: CrossAxisAlignment.start, children: [
      // ── Pregunta conversacional ──────────────────────────────────────
      Text(t('¿Cuándo llegás?', 'When are you arriving?'),
        style: RDSType3.displayXl.copyWith(fontSize: 28, height: 1.1)),
      const SizedBox(height: RDSSpace.xs),
      Text(t('Versión gratuita hasta 2 días · Premium para más',
             'Free version up to 2 days · Premium for more'),
        style: RDSType.bodySm.copyWith(color: RDSColor.gold)),
      const SizedBox(height: RDSSpace.xl),
      Text(t('¿Cuántos días en Medellín?',
             'How many days in Medellín?'),
        style: RDSType.headlineLg),
      const SizedBox(height: RDSSpace.md),
      ...List.generate(4, (i) {
        final n = i + 1; final sel = _dias == n;
        return GestureDetector(
          onTap: () => setState(() { _dias = n; _salida = _llegada.add(Duration(days: n)); }),
          child: AnimatedContainer(
            duration: RDSDuration.fast,
            margin: const EdgeInsets.only(bottom: RDSSpace.sm),
            padding: const EdgeInsets.all(18),
            decoration: BoxDecoration(
              color: sel ? RDSColor.gold.withOpacity(0.12) : RDSColor.card,
              borderRadius: RDSRadius.bMd,
              border: Border.all(color: sel ? RDSColor.gold : Colors.white.withOpacity(0.06), width: sel ? 1.5 : 1)),
            child: Row(children: [
              Text(n == 1 ? '☀️' : n == 2 ? '🌅🌅' : n == 3 ? '🌄🌄🌄' : '🗓️',
                style: const TextStyle(fontSize: 24)),
              const SizedBox(width: 14),
              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(n == 1 ? t('1 día','1 day') : n == 2 ? t('2 días','2 days') :
                     n == 3 ? t('3 días','3 days') : t('4 días','4 days'),
                  style: RDSType.headlineMd.copyWith(color: sel ? RDSColor.gold : RDSColor.textPrimary)),
                Text(n == 1 ? t('Un día perfecto en Medellín','A perfect day') :
                     n == 2 ? t('El clásico fin de semana','The classic weekend') :
                     n == 3 ? t('Explorá lo mejor','Explore the best') :
                              t('Experiencia completa','Full experience'),
                  style: RDSType.bodySm),
              ])),
              if (n > 2) _RDSBadge(label: t('Premium','Premium'),
