}

// ── Pantalla de carga ─────────────────────────────────────────────────────
class _PlannerLoadingScreen extends StatefulWidget {
  final String prompt;
  const _PlannerLoadingScreen({required this.prompt});
  @override
  State<_PlannerLoadingScreen> createState() => _PlannerLoadingScreenState();
}

class _PlannerLoadingScreenState extends State<_PlannerLoadingScreen>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _anim;
  int _msgIdx = 0;
  final List<String> _msgs = [
    'Felo está revisando tus preferencias...',
    'Calculando distancias desde tu hospedaje...',
    'Eligiendo las mejores rutas para vos...',
    'Felo está armando tu plan...',
  ];
  final List<String> _msgsEN = [
    'Felo is checking your preferences...',
    'Calculating distances from your stay...',
    'Picking the best routes for you...',
    'Felo is building your plan...',
  ];

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(seconds: 2))..repeat();
    _anim = Tween<double>(begin: 0, end: 1).animate(_ctrl);
    _cycleMessages();
    _callClaude();
  }

  void _cycleMessages() {
    Future.delayed(const Duration(milliseconds: 1800), () {
      if (mounted) {
        setState(() => _msgIdx = (_msgIdx + 1) % _msgs.length);
        _cycleMessages();
      }
    });
  }

  Future<void> _callClaude() async {
    try {
      final response = await http.post(
        Uri.parse('https://planneriav2-u2yk2c4v7a-uc.a.run.app'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode({'prompt': widget.prompt}),
      );

      if (!mounted) return;

      if (response.statusCode == 200) {
        final data = jsonDecode(response.body);
        final text = data['result'] as String;
        final clean = text.replaceAll(RegExp(r'```json|```'), '').trim();
        final parsed = jsonDecode(clean) as Map<String, dynamic>;
        if (mounted) Navigator.of(context).pop(parsed);
      } else {
        if (mounted) {
          Navigator.of(context).pop(null);
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(t('Error generando itinerario. Intentá de nuevo.',
              'Error generating itinerary. Please try again.')),
            backgroundColor: Colors.red));
        }
      }
    } catch (e) {
      if (mounted) {
        Navigator.of(context).pop(null);
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('Sin conexión. Verificá tu internet.',
            'No connection. Check your internet.')),
          backgroundColor: Colors.red));
      }
    }
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Stack(children: [
        // Fondo radial — profundidad
        Positioned.fill(child: DecoratedBox(
          decoration: BoxDecoration(
            gradient: RadialGradient(
              center: Alignment.topCenter, radius: 1.5,
              colors: [
                RDSColor.gold.withOpacity(0.08),
                RDSColor.base,
              ])))),
        // Contenido centrado
        SafeArea(child: Center(child: Padding(
          padding: const EdgeInsets.all(RDSSpace.xxl),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
            // Ícono giratorio — más elegante
            AnimatedBuilder(
              animation: _anim,
              builder: (_, __) => Container(
                width: 88, height: 88,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: RDSColor.gold.withOpacity(0.06),
                  border: Border.all(
                    color: RDSColor.gold.withOpacity(
                      0.3 + 0.3 * _anim.value)),
                  boxShadow: RDSElevation.glow(
                    color: RDSColor.gold,
                    opacity: 0.15 + 0.15 * _anim.value)),
                child: const Center(child: Icon(
                  RDSIcons.planner,
                  color: RDSColor.gold, size: 36)))),
            const SizedBox(height: RDSSpace.xxl),
            // Título editorial
            Text(
              t('Felo está pensando tu plan', 'Felo is thinking your plan'),
              style: RDSType3.displayXl.copyWith(
                fontSize: 28, height: 1.1),
              textAlign: TextAlign.center),
            const SizedBox(height: RDSSpace.sm),
            Text(
              t('Conoce Medellín desde 2008',
                'Exploring Medellín since 2008'),
              style: RDSType.bodyMd),
            const SizedBox(height: RDSSpace.xxl),
            // Mensaje rotativo
            AnimatedSwitcher(
              duration: RDSDuration.normal,
              transitionBuilder: (child, anim) =>
                FadeTransition(opacity: anim, child: child),
              child: Text(
                kLang == 'en'
                  ? _msgsEN[_msgIdx]
                  : _msgs[_msgIdx],
                key: ValueKey(_msgIdx),
                textAlign: TextAlign.center,
                style: RDSType.headlineMd.copyWith(
                  color: RDSColor.textPrimary.withOpacity(0.8),
                  height: 1.5))),
            const SizedBox(height: RDSSpace.xl),
            // Barra de progreso dorada
            ClipRRect(
              borderRadius: RDSRadius.bFull,
              child: const LinearProgressIndicator(
                backgroundColor: Color(0xFF1A2010),
                valueColor: AlwaysStoppedAnimation<Color>(
                  RDSColor.gold),
                minHeight: 2)),
          ]))))]),
    );
  }
}

// ── Pantalla de resultado ─────────────────────────────────────────────────
class _PlannerResultScreen extends StatefulWidget {
  final Map<String, dynamic> data;
  final int dias;
  const _PlannerResultScreen({required this.data, required this.dias});

  @override
  State<_PlannerResultScreen> createState() => _PlannerResultScreenState();
}

class _PlannerResultScreenState extends State<_PlannerResultScreen> {
  // visitados[diaIdx][bloqueIdx] = true/false
  Map<String, bool> _visitados = {};

  @override
  void initState() {
    super.initState();
    _cargarVisitados();
  }

  String _keyVisitado(int diaIdx, int bloqueIdx) => 'planner_visitado_${diaIdx}_$bloqueIdx';

  Future<void> _cargarVisitados() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final diasList = (widget.data['dias'] as List? ?? []).cast<Map<String, dynamic>>();
      final Map<String, bool> v = {};
      for (int d = 0; d < diasList.length; d++) {
        final bloques = (diasList[d]['bloques'] as List? ?? []);
        for (int b = 0; b < bloques.length; b++) {
          final key = _keyVisitado(d, b);
          v[key] = prefs.getBool(key) ?? false;
        }
      }
      if (mounted) setState(() => _visitados = v);
    } catch (e) {
      debugPrint('Planner visitados: $e');
    }
  }

  Future<void> _toggleVisitado(int diaIdx, int bloqueIdx) async {
    final key = _keyVisitado(diaIdx, bloqueIdx);
    final nuevo = !(_visitados[key] ?? false);
    setState(() => _visitados[key] = nuevo);
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(key, nuevo);
    } catch (e) {
      debugPrint('Planner toggle: $e');
    }
  }

  int _visitadosEnDia(int diaIdx, int totalBloques) {
    int count = 0;
    for (int b = 0; b < totalBloques; b++) {
      if (_visitados[_keyVisitado(diaIdx, b)] == true) count++;
    }
    return count;
  }

  @override
  Widget build(BuildContext context) {
    final saludo = widget.data['saludo']?.toString() ?? '';
    final diasList = (widget.data['dias'] as List? ?? []).cast<Map<String, dynamic>>();
    final resumen = widget.data['resumen'] as Map<String, dynamic>? ?? {};
    final tip = widget.data['tip']?.toString() ?? '';

    // Progreso total
    int totalLugares = 0;
    int totalVisitados = 0;
    for (int d = 0; d < diasList.length; d++) {
      final bloques = (diasList[d]['bloques'] as List? ?? []);
      totalLugares += bloques.length;
      totalVisitados += _visitadosEnDia(d, bloques.length);
    }

    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        // Header resultado
        Container(
          decoration: BoxDecoration(
            gradient: const LinearGradient(
              colors: [Color(0xFF0A1A08), Color(0xFF0F2010)],
              begin: Alignment.topLeft, end: Alignment.bottomRight),
            border: Border(bottom: BorderSide(color: RDSColor.gold.withOpacity(0.2)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 20),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                GestureDetector(
                  onTap: () => Navigator.of(context).popUntil((r) => r.isFirst),
                  child: Container(width: 36, height: 36,
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(0.06), shape: BoxShape.circle,
                      border: Border.all(color: RDSColor.gold.withOpacity(0.2))),
                    child: const Center(child: Icon(Icons.arrow_back_ios_new_rounded,
                      color: RDSColor.textPrimary, size: 18)))),
                const SizedBox(width: 12),
                Expanded(child: Text(t('MI ITINERARIO', 'MY ITINERARY'),
                  style: const TextStyle(fontFamily: 'PlayfairDisplay',
                    fontSize: 18, fontWeight: FontWeight.w900, color: RDSColor.gold))),
                GestureDetector(
                  onTap: () {
                    final texto = '🗓️ ${t("Mi itinerario en Medellín", "My Medellín itinerary")}\n\n'
                      + diasList.map((d) {
                          final bloques = (d['bloques'] as List? ?? []).cast<Map>();
                          return '📅 ${d['fecha']}\n' + bloques.map((b) =>
                            '  ${b['emoji']} ${b['rutaNombre']} · ${b['duracion']}').join('\n');
                        }).join('\n\n')
                      + '\n\n🌿 Rutero MDE → rutero-mde.web.app';
                    Share.share(texto);
                  },
                  child: Container(
                    padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 7),
                    decoration: BoxDecoration(
                      color: RDSColor.gold.withOpacity(0.1),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: RDSColor.gold.withOpacity(0.4))),
                    child: Row(mainAxisSize: MainAxisSize.min, children: [
                      const Icon(Icons.share_outlined, color: RDSColor.gold, size: 14),
                      const SizedBox(width: 5),
                      Text(t('Compartir', 'Share'),
                        style: const TextStyle(color: RDSColor.gold, fontSize: 12,
                          fontWeight: FontWeight.w700)),
                    ]))),
              ]),

              // Barra de progreso total
              if (totalLugares > 0) ...[
                const SizedBox(height: 14),
                Row(children: [
                  Expanded(child: ClipRRect(
                    borderRadius: BorderRadius.circular(2),
                    child: LinearProgressIndicator(
                      value: totalVisitados / totalLugares,
                      backgroundColor: Colors.white.withOpacity(0.07),
                      valueColor: AlwaysStoppedAnimation<Color>(
                        totalVisitados == totalLugares ? RDSColor.gold : RDSColor.green),
                      minHeight: 3))),
                  const SizedBox(width: 10),
                  Text('$totalVisitados/$totalLugares ${t("lugares", "spots")}',
                    style: const TextStyle(fontSize: 10, color: RDSColor.textMuted,
                      fontWeight: FontWeight.w600)),
                ]),
              ],

              if (saludo.isNotEmpty) ...[
                const SizedBox(height: 10),
                Text(saludo,
                  style: const TextStyle(fontSize: 12, color: RDSColor.textPrimary, height: 1.4)),
              ],
            ])))),

        // Lista de días
        Expanded(child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 16, 20, 40),
          children: [
            ...diasList.asMap().entries.map((diaEntry) {
              final diaIdx = diaEntry.key;
              final dia = diaEntry.value;
              final esFeria = dia['esFeria'] == true;
              final bloques = (dia['bloques'] as List? ?? []).cast<Map<String, dynamic>>();
              final visitadosHoy = _visitadosEnDia(diaIdx, bloques.length);
              final diaCompleto = bloques.isNotEmpty && visitadosHoy == bloques.length;

              return Container(
                margin: const EdgeInsets.only(bottom: 20),
                decoration: BoxDecoration(
                  color: RDSColor.card,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(
                    color: diaCompleto
                      ? RDSColor.gold.withOpacity(0.5)
                      : esFeria
                        ? kFeriaRojo.withOpacity(0.4)
                        : RDSColor.gold.withOpacity(0.15))),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  // Header del día
                  Container(
                    padding: const EdgeInsets.fromLTRB(16, 14, 16, 14),
                    decoration: BoxDecoration(
                      color: diaCompleto
                        ? RDSColor.gold.withOpacity(0.12)
                        : esFeria
                          ? kFeriaRojo.withOpacity(0.1)
                          : RDSColor.gold.withOpacity(0.07),
                      borderRadius: const BorderRadius.vertical(top: Radius.circular(16))),
                    child: Row(children: [
                      Icon(
                        diaCompleto ? Icons.check_circle_rounded : Icons.calendar_today_rounded,
                        color: diaCompleto ? RDSColor.gold : esFeria ? kFeriaRojo : RDSColor.gold,
                        size: 18),
                      const SizedBox(width: 10),
                      Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        Text('${t("DÍA", "DAY")} ${dia['numero']}',
                          style: TextStyle(fontSize: 10,
                            color: esFeria ? kFeriaRojo : RDSColor.gold,
