class EmergenciaScreen extends StatelessWidget {
  const EmergenciaScreen({super.key});

  Future<void> _llamar(String telefono) async {
    final numeroLimpio = telefono.replaceAll(RegExp(r'[^\d+]'), '');
    final uri = Uri(scheme: 'tel', path: numeroLimpio);
    if (await canLaunchUrl(uri)) await launchUrl(uri);
  }

  Future<void> _comoLlegar(String query) async {
    final uri = Uri.parse('https://www.google.com/maps/search/?api=1&query=${Uri.encodeComponent(query)}');
    await launchUrl(uri, mode: LaunchMode.externalApplication);
  }

