class MonedaYJergaScreen extends StatefulWidget {
  const MonedaYJergaScreen({super.key});
  @override
  State<MonedaYJergaScreen> createState() => _MonedaYJergaScreenState();
}

class _MonedaYJergaScreenState extends State<MonedaYJergaScreen> {
  double? _tasaUsdCop;
  bool _cargando = true;
  bool _esOffline = false;
  final TextEditingController _usdCtrl = TextEditingController(text: '1');
  double _copResultado = 0;
  Set<String> _palabrasAprendidas = {};

  @override
  void initState() {
    super.initState();
    _cargarTasa();
    _cargarPalabrasAprendidas();
  }

  Future<void> _cargarPalabrasAprendidas() async {
    final prefs = await SharedPreferences.getInstance();
    final lista = prefs.getStringList('palabras_paisa_aprendidas') ?? [];
    if (mounted) setState(() => _palabrasAprendidas = lista.toSet());
  }

  Future<void> _marcarAprendida(String palabra) async {
    final prefs = await SharedPreferences.getInstance();
    _palabrasAprendidas.add(palabra);
    await prefs.setStringList('palabras_paisa_aprendidas', _palabrasAprendidas.toList());
    if (mounted) setState(() {});
  }

  Future<void> _cargarTasa() async {
    final prefs = await SharedPreferences.getInstance();
    try {
      final response = await http
        .get(Uri.parse('https://open.er-api.com/v6/latest/USD'))
        .timeout(const Duration(seconds: 6));
      if (response.statusCode == 200) {
        final data = json.decode(response.body);
        final tasa = (data['rates']?['COP'] as num?)?.toDouble();
        if (tasa != null) {
          await prefs.setDouble('tasa_usd_cop_cache', tasa);
          await prefs.setString('tasa_usd_cop_fecha', DateTime.now().toIso8601String());
          if (mounted) setState(() {
            _tasaUsdCop = tasa;
            _cargando = false;
            _esOffline = false;
            _recalcular();
          });
          return;
        }
      }
      throw Exception('Respuesta inválida');
    } catch (e) {
      debugPrint('⚠️ Error obteniendo tasa USD/COP: $e');
      final cache = prefs.getDouble('tasa_usd_cop_cache');
      if (mounted) setState(() {
        _tasaUsdCop = cache;
        _cargando = false;
        _esOffline = true;
        _recalcular();
      });
    }
  }

  void _recalcular() {
    final usd = double.tryParse(_usdCtrl.text.replaceAll(',', '.')) ?? 0;
    setState(() => _copResultado = usd * (_tasaUsdCop ?? 0));
  }

  String _formatoCop(double v) {
    final s = v.round().toString();
    final buf = StringBuffer();
    for (int i = 0; i < s.length; i++) {
      if (i > 0 && (s.length - i) % 3 == 0) buf.write('.');
      buf.write(s[i]);
    }
    return '\$$buf';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        Container(
          decoration: BoxDecoration(
            color: RDSColor.base,
            border: Border(bottom: BorderSide(color: RDSColor.gold.withOpacity(0.1)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
            child: Row(children: [
              GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06),
                    shape: BoxShape.circle,
                    border: Border.all(color: RDSColor.gold.withOpacity(0.2))),
                  child: const Center(child: Text('←',
                    style: TextStyle(color: RDSColor.textPrimary, fontSize: 16))))),
              const SizedBox(width: 12),
              Expanded(child: Text(t('Moneda y jerga paisa','Currency & paisa slang'),
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 18, fontWeight: FontWeight.w900,
                  color: RDSColor.textPrimary, letterSpacing: 0.2))),
              const Text('💱', style: TextStyle(fontSize: 20)),
            ])))),
        Expanded(child: ListView(
          padding: const EdgeInsets.fromLTRB(20, 16, 20, 40),
          children: [
            Text(t('Conversor USD → COP','USD → COP Converter'),
              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                color: RDSColor.textMuted, letterSpacing: 1.5)),
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.all(16),
              decoration: BoxDecoration(color: RDSColor.card, borderRadius: BorderRadius.circular(16),
                border: Border.all(color: RDSColor.gold.withOpacity(0.25))),
              child: _cargando
                ? const Center(child: Padding(
                    padding: EdgeInsets.symmetric(vertical: 12),
                    child: CircularProgressIndicator(color: RDSColor.gold, strokeWidth: 2)))
                : Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Row(children: [
                      Expanded(child: TextField(
                        controller: _usdCtrl,
                        keyboardType: const TextInputType.numberWithOptions(decimal: true),
                        style: const TextStyle(color: RDSColor.textPrimary, fontSize: 22, fontWeight: FontWeight.w700),
                        decoration: const InputDecoration(
                          prefixText: 'USD \$ ',
                          prefixStyle: TextStyle(color: RDSColor.gold, fontSize: 16, fontWeight: FontWeight.w700),
                          border: InputBorder.none),
                        onChanged: (_) => _recalcular())),
                    ]),
                    Padding(padding: const EdgeInsets.symmetric(vertical: 10),
                      child: Container(height: 1, color: Colors.white.withOpacity(0.08))),
                    Row(children: [
                      Text(t('Equivale a','Equals'),
                        style: const TextStyle(color: RDSColor.textMuted, fontSize: 12)),
                    ]),
                    const SizedBox(height: 4),
                    Text(
                      _tasaUsdCop != null ? _formatoCop(_copResultado) : '—',
                      style: const TextStyle(color: RDSColor.green, fontSize: 26, fontWeight: FontWeight.w900)),
                    const SizedBox(height: 10),
                    if (_tasaUsdCop != null)
                      Row(children: [
                        Text('1 USD ≈ ${_formatoCop(_tasaUsdCop!)} COP',
                          style: TextStyle(color: RDSColor.textMuted.withOpacity(0.7), fontSize: 11)),
                        const Spacer(),
                        if (_esOffline)
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                            decoration: BoxDecoration(
                              color: Colors.orange.withOpacity(0.15),
                              borderRadius: BorderRadius.circular(6)),
                            child: Text(t('Sin conexión · último valor','Offline · last value'),
                              style: const TextStyle(color: Colors.orange, fontSize: 9, fontWeight: FontWeight.w700))),
                      ])
                    else
                      Text(t('No se pudo obtener la tasa. Revisa tu conexión.',
                          'Could not fetch the rate. Check your connection.'),
                        style: const TextStyle(color: Colors.orange, fontSize: 11)),
                  ])),

            const SizedBox(height: 28),

            Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
              Text(t('Diccionario paisa','Paisa dictionary'),
                style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                  color: RDSColor.textMuted, letterSpacing: 1.5)),
              Text('${_palabrasAprendidas.length}/${kDiccionarioPaisa.length} ${t("aprendidas","learned")}',
                style: const TextStyle(color: RDSColor.gold, fontSize: 11, fontWeight: FontWeight.w700)),
            ]),
            const SizedBox(height: 4),
            Text(t('Toca una palabra para marcarla como aprendida','Tap a word to mark it as learned'),
              style: TextStyle(color: RDSColor.textMuted.withOpacity(0.6), fontSize: 11)),
            const SizedBox(height: 16),

            // ── Palabra del día ──
            Builder(builder: (_) {
              final hoy = DateTime.now();
              final idx = (hoy.year * 365 + hoy.month * 30 + hoy.day) % kDiccionarioPaisa.length;
              final p = kDiccionarioPaisa[idx];
              return Container(
                padding: const EdgeInsets.all(16),
                margin: const EdgeInsets.only(bottom: 16),
                decoration: BoxDecoration(
                  gradient: LinearGradient(colors: [RDSColor.gold.withOpacity(0.15), RDSColor.gold.withOpacity(0.05)]),
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: RDSColor.gold.withOpacity(0.4))),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    const Text('⭐', style: TextStyle(fontSize: 14)),
                    const SizedBox(width: 6),
                    Text(t('Palabra del día', 'Word of the day'),
                      style: const TextStyle(color: RDSColor.gold, fontSize: 10, fontWeight: FontWeight.w900, letterSpacing: 1.5)),
                  ]),
                  const SizedBox(height: 8),
                  Text(p.palabra, style: const TextStyle(color: RDSColor.gold, fontSize: 22, fontWeight: FontWeight.w900, letterSpacing: 1)),
                  const SizedBox(height: 4),
                  Text(t(p.significado, p.significadoEN), style: TextStyle(color: RDSColor.textMuted.withOpacity(0.9), fontSize: 13, height: 1.4)),
                  const SizedBox(height: 6),
                  Text(t(p.ejemplo, p.ejemploEN), style: TextStyle(color: RDSColor.textMuted.withOpacity(0.6), fontSize: 11, fontStyle: FontStyle.italic)),
                ]));
            }),

            const SizedBox(height: 4),
            ...kDiccionarioPaisa.map((p) {
              final aprendida = _palabrasAprendidas.contains(p.palabra);
              return GestureDetector(
                onTap: () => _marcarAprendida(p.palabra),
                child: Container(
                  margin: const EdgeInsets.only(bottom: 10),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: RDSColor.card, borderRadius: BorderRadius.circular(14),
                    border: Border.all(
                      color: aprendida ? RDSColor.gold.withOpacity(0.4) : Colors.white.withOpacity(0.08))),
                  child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Container(width: 30, height: 30,
                      decoration: BoxDecoration(shape: BoxShape.circle,
                        color: aprendida ? RDSColor.gold.withOpacity(0.15) : const Color(0xFF050A04)),
                      child: Center(child: Text(aprendida ? '✅' : '🗣️',
                        style: const TextStyle(fontSize: 14)))),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(p.palabra,
                        style: TextStyle(color: aprendida ? RDSColor.gold : RDSColor.textPrimary,
                          fontSize: 14, fontWeight: FontWeight.w800, letterSpacing: 0.5)),
                      const SizedBox(height: 4),
                      Text(t(p.significado, p.significadoEN),
                        style: TextStyle(color: RDSColor.textMuted.withOpacity(0.9), fontSize: 12, height: 1.4)),
                      const SizedBox(height: 6),
                      Text(t(p.ejemplo, p.ejemploEN),
                        style: TextStyle(color: RDSColor.textMuted.withOpacity(0.6), fontSize: 11,
                          fontStyle: FontStyle.italic, height: 1.4)),
                    ])),
                  ])));
            }),
          ])),
      ]));
  }

  @override
  void dispose() {
    _usdCtrl.dispose();
    super.dispose();
  }
}

// ═══════════════════════════════════════════════════════════════════════════
//  🆘 BOTÓN SOS
//  Configuración de contacto de emergencia (shared_preferences) +
//  obtención de GPS (mismo patrón de MapScreen) + envío por WhatsApp.
//  Sin backend nuevo, sin costo adicional.
// ═══════════════════════════════════════════════════════════════════════════

class SOSConfigScreen extends StatefulWidget {
  const SOSConfigScreen({super.key});
  @override
  State<SOSConfigScreen> createState() => _SOSConfigScreenState();
}

class _SOSConfigScreenState extends State<SOSConfigScreen> {
  final _nombreCtrl = TextEditingController();
  final _numeroCtrl = TextEditingController();
  bool _cargando = true;
  bool _guardando = false;
  bool _enviandoSOS = false;

  @override
  void initState() {
    super.initState();
    _cargarContacto();
  }

  Future<void> _cargarContacto() async {
    final prefs = await SharedPreferences.getInstance();
    _nombreCtrl.text = prefs.getString('sos_contacto_nombre') ?? '';
    _numeroCtrl.text = prefs.getString('sos_contacto_numero') ?? '';
    if (mounted) setState(() => _cargando = false);
  }

  Future<void> _guardarContacto() async {
    if (_nombreCtrl.text.trim().isEmpty || _numeroCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Completa nombre y número','Fill in name and number')),
        backgroundColor: Colors.orange));
      return;
    }
    setState(() => _guardando = true);
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('sos_contacto_nombre', _nombreCtrl.text.trim());
    await prefs.setString('sos_contacto_numero', _numeroCtrl.text.trim());
    if (mounted) {
      setState(() => _guardando = false);
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('✅ Contacto de emergencia guardado','✅ Emergency contact saved')),
        backgroundColor: RDSColor.green));
    }
  }

  Future<void> _enviarSOS() async {
    final numero = _numeroCtrl.text.trim();
    if (numero.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Configura un contacto primero','Set up a contact first')),
        backgroundColor: Colors.orange));
      return;
    }
    setState(() => _enviandoSOS = true);
    try {
      LocationPermission p = await Geolocator.checkPermission();
      if (p == LocationPermission.denied) p = await Geolocator.requestPermission();
      if (p == LocationPermission.deniedForever || p == LocationPermission.denied) {
        if (mounted) {
          setState(() => _enviandoSOS = false);
          ScaffoldMessenger.of(context).showSnackBar(SnackBar(
            content: Text(t('Activa el permiso de ubicación para enviar SOS',
                'Enable location permission to send SOS')),
            backgroundColor: Colors.orange));
        }
        return;
      }
      Position pos;
      try {
        pos = await Geolocator.getCurrentPosition(
          desiredAccuracy: LocationAccuracy.high,
        ).timeout(const Duration(seconds: 8));
      } catch (_) {
        // Fallback: precisión media, más rápida si el GPS de alta precisión tarda
        pos = await Geolocator.getCurrentPosition(
          desiredAccuracy: LocationAccuracy.medium,
        ).timeout(const Duration(seconds: 6));
      }
      final mapsLink = 'https://maps.google.com/?q=${pos.latitude},${pos.longitude}';
      final mensaje = Uri.encodeComponent(
        t('🆘 Necesito ayuda. Esta es mi ubicación actual: $mapsLink — Enviado desde Rutero MDE.',
          '🆘 I need help. This is my current location: $mapsLink — Sent from Rutero MDE.'));
      final numeroLimpio = numero.replaceAll(RegExp(r'[^\d+]'), '');
      final whatsappUri = Uri.parse('https://wa.me/$numeroLimpio?text=$mensaje');
      final abierto = await launchUrl(whatsappUri, mode: LaunchMode.externalApplication);
      if (!abierto && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('No se pudo abrir WhatsApp. ¿Está instalado?','Could not open WhatsApp. Is it installed?')),
          backgroundColor: Colors.red));
      }
    } catch (e) {
      debugPrint('🔴 Error enviando SOS: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('No se pudo obtener tu ubicación a tiempo. Verifica que el GPS esté activado e intenta de nuevo.',
              'Could not get your location in time. Make sure GPS is enabled and try again.')),
          backgroundColor: Colors.red,
          duration: const Duration(seconds: 4)));
      }
    } finally {
      if (mounted) setState(() => _enviandoSOS = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: RDSColor.base,
      body: Column(children: [
        Container(
          decoration: BoxDecoration(
            color: RDSColor.base,
            border: Border(bottom: BorderSide(color: RDSColor.gold.withOpacity(0.1)))),
          child: SafeArea(bottom: false, child: Padding(
            padding: const EdgeInsets.fromLTRB(20, 12, 20, 18),
            child: Row(children: [
              GestureDetector(onTap: () => Navigator.pop(context),
                child: Container(width: 36, height: 36,
                  decoration: BoxDecoration(
                    color: Colors.white.withOpacity(0.06),
                    shape: BoxShape.circle,
                    border: Border.all(color: RDSColor.gold.withOpacity(0.2))),
                  child: const Center(child: Text('←',
                    style: TextStyle(color: RDSColor.textPrimary, fontSize: 16))))),
              const SizedBox(width: 12),
              Expanded(child: Text(t('Botón SOS','SOS Button'),
                style: const TextStyle(
                  fontFamily: 'PlayfairDisplay',
                  fontSize: 19, fontWeight: FontWeight.w900,
                  color: RDSColor.textPrimary, letterSpacing: 0.3))),
              const Text('🆘', style: TextStyle(fontSize: 20)),
            ])))),
        Expanded(child: _cargando
          ? const Center(child: CircularProgressIndicator(color: RDSColor.gold))
          : ListView(
              padding: EdgeInsets.fromLTRB(20, 16, 20, 40 + MediaQuery.of(context).padding.bottom),
              children: [
                GestureDetector(
                  onTap: _enviandoSOS ? null : _enviarSOS,
                  child: Container(
                    width: double.infinity,
                    padding: const EdgeInsets.symmetric(vertical: 22),
                    decoration: BoxDecoration(
                      color: Colors.red.withOpacity(0.12),
                      borderRadius: BorderRadius.circular(20),
                      border: Border.all(color: Colors.red.withOpacity(0.5), width: 1.5)),
                    child: _enviandoSOS
                      ? const Center(child: CircularProgressIndicator(color: Colors.red, strokeWidth: 2))
                      : Column(children: [
                          const Text('🆘', style: TextStyle(fontSize: 38)),
                          const SizedBox(height: 8),
                          Text(t('ENVIAR SOS','SEND SOS'),
                            style: const TextStyle(color: Colors.red, fontSize: 16,
                              fontWeight: FontWeight.w900, letterSpacing: 1)),
                          const SizedBox(height: 4),
                          Text(t('Envía tu ubicación por WhatsApp','Send your location via WhatsApp'),
                            style: TextStyle(color: Colors.red.withOpacity(0.7), fontSize: 11)),
                        ]))),

                const SizedBox(height: 28),

                Text(t('Contacto de emergencia','Emergency contact'),
                  style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w900,
                    color: RDSColor.textMuted, letterSpacing: 1.5)),
                const SizedBox(height: 4),
                Text(t('Se usará para enviar tu ubicación cuando presiones SOS',
                    'Used to send your location when you press SOS'),
                  style: TextStyle(color: RDSColor.textMuted.withOpacity(0.6), fontSize: 11)),
                const SizedBox(height: 14),

                Container(
                  decoration: BoxDecoration(color: RDSColor.surface, borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: Colors.white.withOpacity(0.1))),
                  child: TextField(
                    controller: _nombreCtrl,
                    style: const TextStyle(color: RDSColor.textPrimary, fontSize: 14),
                    decoration: InputDecoration(
                      hintText: t('Nombre del contacto','Contact name'),
                      hintStyle: const TextStyle(color: RDSColor.textMuted),
                      prefixIcon: const Padding(padding: EdgeInsets.all(12),
                        child: Text('👤', style: TextStyle(fontSize: 16))),
                      border: InputBorder.none,
                      contentPadding: const EdgeInsets.symmetric(vertical: 14)))),

                const SizedBox(height: 10),

                Container(
                  decoration: BoxDecoration(color: RDSColor.surface, borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: Colors.white.withOpacity(0.1))),
                  child: TextField(
                    controller: _numeroCtrl,
                    keyboardType: TextInputType.phone,
                    style: const TextStyle(color: RDSColor.textPrimary, fontSize: 14),
                    decoration: InputDecoration(
                      hintText: t('Número con indicativo (ej: +57 300 1234567)',
                          'Number with country code (e.g: +57 300 1234567)'),
                      hintStyle: const TextStyle(color: RDSColor.textMuted, fontSize: 12),
                      prefixIcon: const Padding(padding: EdgeInsets.all(12),
                        child: Text('📱', style: TextStyle(fontSize: 16))),
                      border: InputBorder.none,
                      contentPadding: const EdgeInsets.symmetric(vertical: 14)))),

                const SizedBox(height: 16),

                _GoldButton(
                  label: _guardando
                    ? t('GUARDANDO...','SAVING...')
                    : t('GUARDAR CONTACTO','SAVE CONTACT'),
                  onTap: _guardando ? () {} : _guardarContacto),

                const SizedBox(height: 20),
                Container(
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: RDSColor.gold.withOpacity(0.06),
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(color: RDSColor.gold.withOpacity(0.15))),
                  child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    const Text('💡', style: TextStyle(fontSize: 16)),
                    const SizedBox(width: 10),
                    Expanded(child: Text(
                      t('El botón SOS abre WhatsApp con tu ubicación exacta lista para enviar a tu contacto de confianza.',
                        'The SOS button opens WhatsApp with your exact location ready to send to your trusted contact.'),
                      style: TextStyle(color: RDSColor.textMuted.withOpacity(0.8), fontSize: 11.5, height: 1.4))),
                  ])),
              ])),
      ]));
  }

  @override
  void dispose() {
    _nombreCtrl.dispose();
    _numeroCtrl.dispose();
    super.dispose();
  }
}

// ═══════════════════════════════════════════════════════════════════════════
//  💬 FEEDBACK BETA SCREEN
//  Formulario de opiniones → Firebase feedback_beta
// ═══════════════════════════════════════════════════════════════════════════
class FeedbackBetaScreen extends StatefulWidget {
  const FeedbackBetaScreen({super.key});
  @override
  State<FeedbackBetaScreen> createState() => _FeedbackBetaScreenState();
}

class _FeedbackBetaScreenState extends State<FeedbackBetaScreen> {
  int _estrellas = 0;
  bool? _recomendaria;
  final _comentarioCtrl = TextEditingController();
  final _nombreCtrl = TextEditingController();
  bool _enviando = false;
  bool _enviado = false;

  @override
  void dispose() { _comentarioCtrl.dispose(); _nombreCtrl.dispose(); super.dispose(); }

  Future<void> _enviar() async {
    if (_estrellas == 0) {
      ScaffoldMessenger.of(context).showSnackBar(SnackBar(
        content: Text(t('Por favor califica tu experiencia', 'Please rate your experience')),
        backgroundColor: RDSColor.orchid));
      return;
    }
    setState(() => _enviando = true);
    try {
      await FirebaseFirestore.instance.collection('feedback_beta').add({
        'estrellas': _estrellas,
        'comentario': _comentarioCtrl.text.trim(),
        'nombre': _nombreCtrl.text.trim().isEmpty ? t('Anónimo','Anonymous') : _nombreCtrl.text.trim(),
        'recomendaria': _recomendaria,
        'uid': AuthService.currentUser?.uid ?? 'anonimo',
        'email': AuthService.currentUser?.email ?? '',
        'fecha': FieldValue.serverTimestamp(),
        'version': 'beta-1.0',
      });
      if (mounted) setState(() { _enviado = true; _enviando = false; });
    } catch (_) {
      if (mounted) {
        setState(() => _enviando = false);
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          content: Text(t('Error al enviar. Intenta de nuevo.', 'Error sending. Please try again.')),
          backgroundColor: Colors.red));
      }
    }
  }

  @override
  Widget build(BuildContext context) => Scaffold(
    backgroundColor: RDSColor.overlay,
    appBar: AppBar(
      backgroundColor: RDSColor.base,
      title: Text(t('Tu opinión', 'Your feedback'),
        style: const TextStyle(color: RDSColor.textPrimary, fontWeight: FontWeight.w800)),
      leading: IconButton(
        icon: const Icon(RDSIcons.back, color: RDSColor.textPrimary),
        onPressed: () => Navigator.pop(context))),
    body: _enviado ? _PantallaEnviada() : SingleChildScrollView(
      padding: const EdgeInsets.all(24),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Container(
          padding: const EdgeInsets.all(16),
          decoration: BoxDecoration(
            color: RDSColor.green.withOpacity(0.08), borderRadius: BorderRadius.circular(14),
            border: Border.all(color: RDSColor.green.withOpacity(0.25))),
          child: Row(children: [
            const Text('🧪', style: TextStyle(fontSize: 20)),
            const SizedBox(width: 10),
            Expanded(child: Text(
              t('Versión beta · Tu experiencia mejora Rutero MDE para todos',
                'Beta · Your experience improves Rutero MDE for everyone'),
              style: const TextStyle(color: RDSColor.textMuted, fontSize: 12, height: 1.4))),
          ])),
        const SizedBox(height: 28),
        Text(t('¿Cómo fue tu experiencia?', 'How was your experience?'),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 15, fontWeight: FontWeight.w800)),
        const SizedBox(height: 12),
        Row(children: List.generate(5, (i) => GestureDetector(
          onTap: () => setState(() => _estrellas = i + 1),
          child: Padding(padding: const EdgeInsets.only(right: 8),
            child: Icon(i < _estrellas ? Icons.star_rounded : Icons.star_outline_rounded,
              color: RDSColor.gold, size: 36))))),
        const SizedBox(height: 28),
        Text(t('¿Recomendarías Rutero MDE?', 'Would you recommend Rutero MDE?'),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 15, fontWeight: FontWeight.w800)),
        const SizedBox(height: 12),
        Row(children: [
          _OpcionBtn(texto: t('Sí, claro','Yes!'), emoji: '👍',
            seleccionado: _recomendaria == true,
            onTap: () => setState(() => _recomendaria = true)),
          const SizedBox(width: 10),
          _OpcionBtn(texto: t('Todavía no','Not yet'), emoji: '🤔',
            seleccionado: _recomendaria == false,
            onTap: () => setState(() => _recomendaria = false)),
        ]),
        const SizedBox(height: 28),
        Text(t('Tu nombre (opcional)', 'Your name (optional)'),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 15, fontWeight: FontWeight.w800)),
        const SizedBox(height: 10),
        _campo(_nombreCtrl, t('Anónimo si prefieres','Anonymous if you prefer'), 1),
        const SizedBox(height: 20),
        Text(t('Comentarios o sugerencias', 'Comments or suggestions'),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 15, fontWeight: FontWeight.w800)),
        const SizedBox(height: 10),
        _campo(_comentarioCtrl,
          t('¿Qué te gustó? ¿Qué mejorarías?','What did you like? What would you improve?'), 4),
        const SizedBox(height: 32),
        GestureDetector(
          onTap: _enviando ? null : _enviar,
          child: Container(
            width: double.infinity,
            padding: const EdgeInsets.symmetric(vertical: 16),
            decoration: BoxDecoration(
              color: _enviando ? RDSColor.textMuted : RDSColor.green,
              borderRadius: BorderRadius.circular(16)),
            child: _enviando
              ? const Center(child: SizedBox(width: 20, height: 20,
                  child: CircularProgressIndicator(color: Colors.white, strokeWidth: 2)))
              : Text(t('Enviar mi opinión','Send my feedback'),
                  style: const TextStyle(color: Colors.white, fontSize: 15, fontWeight: FontWeight.w900),
                  textAlign: TextAlign.center))),
        const SizedBox(height: 20),
      ])));

  Widget _campo(TextEditingController ctrl, String hint, int lines) => TextField(
    controller: ctrl, maxLines: lines,
    style: const TextStyle(color: RDSColor.textPrimary, fontSize: 13),
    decoration: InputDecoration(
      hintText: hint, hintStyle: const TextStyle(color: RDSColor.textMuted),
      filled: true, fillColor: RDSColor.base,
      border: OutlineInputBorder(borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: RDSColor.green.withOpacity(0.2))),
      enabledBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: RDSColor.green.withOpacity(0.2))),
      focusedBorder: OutlineInputBorder(borderRadius: BorderRadius.circular(12),
        borderSide: BorderSide(color: RDSColor.green))));
}

class _OpcionBtn extends StatelessWidget {
  final String texto, emoji;
  final bool seleccionado;
  final VoidCallback onTap;
  const _OpcionBtn({required this.texto, required this.emoji,
    required this.seleccionado, required this.onTap});
  @override
  Widget build(BuildContext context) => GestureDetector(
    onTap: onTap,
    child: Container(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
      decoration: BoxDecoration(
        color: seleccionado ? RDSColor.green.withOpacity(0.15) : RDSColor.base,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: seleccionado ? RDSColor.green : RDSColor.green.withOpacity(0.2),
          width: seleccionado ? 1.5 : 1)),
      child: Row(mainAxisSize: MainAxisSize.min, children: [
        Text(emoji, style: const TextStyle(fontSize: 16)),
        const SizedBox(width: 6),
        Text(texto, style: TextStyle(color: seleccionado ? RDSColor.green : RDSColor.textMuted,
          fontSize: 12, fontWeight: FontWeight.w600)),
      ])));
}

