  @override
  State<WelcomeScreen> createState() => _WelcomeScreenState();
}

class _WelcomeScreenState extends State<WelcomeScreen> with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _fadeAnim;
  late Animation<Offset> _slideAnim;
  _CiudadRegistrada? _ciudadWelcome;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 900));
    _fadeAnim = CurvedAnimation(parent: _ctrl, curve: Curves.easeOut);
    _slideAnim = Tween<Offset>(begin: const Offset(0, 0.08), end: Offset.zero)
        .animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeOut));
    _ctrl.forward();
    _detectarCiudadWelcome();
  }

  Future<void> _detectarCiudadWelcome() async {
    final ciudad = await detectarCiudadActual();
    if (mounted) setState(() => _ciudadWelcome = ciudad);
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  void _goToHome() {
    final destino = AuthService.currentUser != null
      ? const MainShell()
      : const LoginScreen();
    Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
      PageRouteBuilder(
        pageBuilder: (_, __, ___) => destino,
        transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
        transitionDuration: const Duration(milliseconds: 500),
      ),
      (route) => false,
    );
  }

  void _goToRegister() {
    Navigator.of(context).push(PageRouteBuilder(
      pageBuilder: (_, __, ___) => const RegisterScreen(),
      transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
      transitionDuration: const Duration(milliseconds: 400),
    ));
  }

  void _goToLogin() {
    Navigator.of(context).push(PageRouteBuilder(
      pageBuilder: (_, __, ___) => const LoginScreen(),
      transitionsBuilder: (_, anim, __, child) => FadeTransition(opacity: anim, child: child),
      transitionDuration: const Duration(milliseconds: 400),
    ));
  }

  bool _cargandoGoogle = false;

  Future<void> _loginGoogleWelcome() async {
    setState(() => _cargandoGoogle = true);
    final cred = await AuthService.signInWithGoogle();
    if (mounted) {
      setState(() => _cargandoGoogle = false);
      if (cred != null) {
        Navigator.of(context, rootNavigator: true).pushAndRemoveUntil(
          MaterialPageRoute(builder: (_) => const MainShell()),
          (route) => false);
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return ValueListenableBuilder<String>(
      valueListenable: langNotifier,
      builder: (context, lang, _) => _buildContent(context),
    );
  }

  Widget _buildContent(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFF060A04),
      body: Stack(children: [

        // ── Mosaico de fotos — parte superior ──
        // 2 filas x 3 fotos = 6 imágenes de Antioquia
        Positioned(top: 0, left: 0, right: 0,
          height: MediaQuery.of(context).size.height * 0.52,
          child: Column(children: [
            Expanded(child: Row(children: [
              Expanded(child: Image.asset('assets/images/rutas/ruta_09_guatape.jpg',
                fit: BoxFit.cover, cacheWidth: 400,
                errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0D1A0A)))),
              const SizedBox(width: 2),
              Expanded(child: Image.asset('assets/images/rutas/ruta_04_metrocable.jpg',
                fit: BoxFit.cover, cacheWidth: 400,
                errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0A150A)))),
              const SizedBox(width: 2),
              Expanded(child: Image.asset('assets/images/rutas/ruta_12_jardin.jpg',
                fit: BoxFit.cover, cacheWidth: 400,
                errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0D200A)))),
            ])),
            const SizedBox(height: 2),
            Expanded(child: Row(children: [
              Expanded(child: Image.asset('assets/images/rutas/ruta_13_santa_fe.jpg',
                fit: BoxFit.cover, cacheWidth: 400,
                errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0A1510)))),
              const SizedBox(width: 2),
              Expanded(child: Image.asset('assets/images/rutas/ruta_01_transformacion.jpg',
                fit: BoxFit.cover, cacheWidth: 400,
                errorBuilder: (_, __, ___) => Container(color: const Color(0xFF0D1A0D)))),
