                    final pausada = r['pausada'] == true;
                    widgets.add(_RouteCard(
                      ruta: r, activa: !pausada,
                      proximaActivacion: pausada ? (r['tagPausada'] ?? '🚧 Próximamente') : '',
                      onTap: pausada ? null : () => RuteroNav.push(context, RouteDetailScreen(ruta: r))));
                  }
                }
                return widgets;
              })(),
