  // Validar y subir foto a Firebase Storage
  // FIX B: Guarda foto en Firestore PRIMERO (con localPath) ANTES de intentar subir.
  //        Si la subida a Storage falla, al menos hay registro y la foto queda
  //        disponible localmente en la galería.
  // FIX C: Si la subida falla, muestra snackbar amarillo informativo al usuario.
  // NOTA (13/05/2026): La re-verificación GPS se hace ANTES de llegar aquí,
  //        en _SitioInfoScreenState antes de abrir la cámara. Ver FIX 1, 2 y 4.
  Future<void> _validarFoto() async {
    if (_fotoTomada == null) return;
    setState(() { _validando = true; _subiendo = true; });

    // La foto NO se sube a Storage — queda en galería del usuario.
    // Solo registramos la validación como doc liviano en Firestore.
    if (!kModoDemo && AuthService.currentUser != null) {
      FirebaseFirestore.instance
        .collection('usuarios')
        .doc(AuthService.currentUser!.uid)
        .collection('validaciones')
        .add({
          'sitio': widget.sitioNombre,
          'sitioNumero': widget.sitioNumero,
          'ruta': widget.ruta['nombre'],
          'emoji': widget.sitioEmoji,
          'rutaEmoji': widget.ruta['emoji'],
          'acento': (kRutaColor(widget.ruta['acento'], RDSColor.green)).value,
          'fecha': FieldValue.serverTimestamp(),
        }).catchError((e) => debugPrint('⚠️ validación Firestore: $e'));
    }
    setState(() { _subiendo = false; _validando = false; });

        // 🎉 Celebración al validar foto
    await AudioManager().sonarCelebracion();
    // 🔔 Notificación push local de sitio validado
    NotificationManager().sitioValidado(
      widget.sitioNombre,
      widget.sitioNumero,
      widget.totalSitios,
    );
    if (mounted) setState(() {
      _mostrarTipAvatar = true;
      _tipActual = t(
        '🎉 ¡INCREÍBLE! Completaste toda la ruta. ¡Eres un verdadero Rutero MDE! Reclama tu premio ahora. 🏆',
        '🎉 AMAZING! You completed the entire route. You are a true Rutero MDE! Claim your reward now. 🏆');
      _poseActual = 'celebracion';
    });
    setState(() {
      _mostrarTipAvatar = true;
      _tipActual = t(
        '¡¡ESPECTACULAR!! 🎉 Completaste la ruta. ¡Eres un verdadero Rutero Paisa! Ya ganaste tu insignia. ¡Reclámaaa!',
        'SPECTACULAR!! 🎉 You completed the route. You are a true Rutero Paisa! You just earned your badge. Claim it!');
      _poseActual = 'celebracion';
    });
    await Future.delayed(const Duration(milliseconds: 800));

    if (mounted) {
      await Navigator.of(context).push(MaterialPageRoute(
        builder: (_) => RewardScreen(
          sitioNombre: widget.sitioNombre,
          sitioEmoji: widget.sitioEmoji,
          sitioNumero: widget.sitioNumero,
          totalSitios: widget.totalSitios,
          ruta: widget.ruta,
          urlFotoValidacion: null,
        )));
      if (mounted) Navigator.of(context).pop(true);
    }
  }

