class RewardScreen extends StatefulWidget {
  final String sitioNombre;
  final String sitioEmoji;
  final int sitioNumero;
  final int totalSitios;
  final Map<String, dynamic> ruta;
  final VoidCallback? onSiguiente;
  final String? urlFotoValidacion;

  const RewardScreen({
    super.key,
    this.sitioNombre = 'Sitio completado',
    this.sitioEmoji = '🏅',
    this.sitioNumero = 1,
    this.totalSitios = 1,
    required this.ruta,
    this.onSiguiente,
    this.urlFotoValidacion,
  });

  @override
  State<RewardScreen> createState() => _RewardScreenState();
}

class _RewardScreenState extends State<RewardScreen>
    with TickerProviderStateMixin {
  late AnimationController _ctrl;
  late AnimationController _confettiCtrl;
  late AnimationController _pulseCtrl;
  late Animation<double> _scaleAnim, _fadeAnim, _pulseAnim;
  final List<_ConfettiParticle> _particles = [];
  bool _rutaCompleta = false;

  // 💎 Sprint 1 — ALIADO FINAL
  String? _codigoAliado;
  AliadoComercial? _aliadoActual;

  @override
  void initState() {
    super.initState();
    _rutaCompleta = widget.sitioNumero >= widget.totalSitios;

    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 900));
    _scaleAnim = Tween<double>(begin: 0.3, end: 1.0)
        .animate(CurvedAnimation(parent: _ctrl, curve: Curves.elasticOut));
    _fadeAnim = CurvedAnimation(parent: _ctrl, curve: Curves.easeIn);

    _pulseCtrl = AnimationController(vsync: this,
        duration: const Duration(milliseconds: 1400))..repeat(reverse: true);
    _pulseAnim = Tween<double>(begin: 0.85, end: 1.0)
        .animate(CurvedAnimation(parent: _pulseCtrl, curve: Curves.easeInOut));

    _confettiCtrl = AnimationController(vsync: this,
        duration: const Duration(milliseconds: 2500));

    _ctrl.forward();
    AudioManager().sonarCelebracion();
    _verificarYGenerarCodigoAliado();

    // Lanzar confetti con delay
    Future.delayed(const Duration(milliseconds: 300), () {
      if (mounted) {
        _generarParticulas();
        _confettiCtrl.forward();
      }
    });
  }

  void _generarParticulas() {
    final acento = kRutaColor(widget.ruta['acento'], RDSColor.green);
    final colores = [acento, RDSColor.gold, RDSColor.green, Colors.white, acento.withOpacity(0.7)];
    final rand = List.generate(60, (i) => i);
    for (final i in rand) {
      _particles.add(_ConfettiParticle(
        color: colores[i % colores.length],
        x: (i * 0.017) % 1.0,
        delay: (i * 0.03) % 1.0,
        size: 4 + (i % 8).toDouble(),
        speed: 0.3 + (i % 5) * 0.15,
      ));
    }
  }

  void _verificarYGenerarCodigoAliado() {
    final user = FirebaseAuth.instance.currentUser;
    if (user == null) return;
    final rutaNombre = widget.ruta['nombre']?.toString() ?? 'RUTA';
    final esRutaCompleta = widget.sitioNumero >= widget.totalSitios;

    // ── MOBIPLAB — aliado piloto B2B ─────────────────────────────
    // Al completar ruta del Centro → código QR 20% descuento mano de obra
    if (esRutaCompleta && kRutasMobiplab.contains(rutaNombre)) {
      final aliado = kAliadosReales['mobiplab'];
      if (aliado == null) return;
      final codigo = generarCodigoAliado(
        rutaNombre: rutaNombre, aliadoId: aliado.id, userId: user.uid);
      setState(() { _codigoAliado = codigo; _aliadoActual = aliado; });
      registrarCodigoAliado(codigo: codigo, aliado: aliado, rutaNombre: rutaNombre);
      return;
    }

    // ── Otros aliados por sitio específico ────────────────────────
    final aliado = kAliadosFinales[widget.sitioNombre];
    if (aliado == null || !aliado.activo) return;
    final codigo = generarCodigoAliado(
      rutaNombre: rutaNombre, aliadoId: aliado.id, userId: user.uid);
    setState(() { _codigoAliado = codigo; _aliadoActual = aliado; });
    registrarCodigoAliado(codigo: codigo, aliado: aliado, rutaNombre: rutaNombre);
  }

  @override
  void dispose() {
    _ctrl.dispose();
    _confettiCtrl.dispose();
    _pulseCtrl.dispose();
    super.dispose();
  }

  void _compartirLogro(BuildContext context) {
    final rutaNombre = kLang == 'en'
        ? (widget.ruta['nombreEN'] ?? widget.ruta['nombre'])
        : widget.ruta['nombre'];
    final progreso = '${widget.sitioNumero}/${widget.totalSitios}';
    final puntos = widget.sitioNumero * 30;
    final user = AuthService.currentUser;
    final nombreUsuario = user?.displayName ?? user?.email?.split('@').first ?? 'Rutero';
    final insignia = widget.ruta['insignia']?.toString() ?? 'Medalla Rutero';
    final linkLogro = DeepLinkManager.linkLogro(nombreUsuario, insignia);
    final linkRuta = DeepLinkManager.linkRuta(widget.ruta['nombre'].toString());
    final textoES =
        '¡Acabo de validar "${widget.sitioNombre}" en $rutaNombre! '
        '$progreso sitios · +$puntos puntos 🏆\n'
        '🌿 Descarga Rutero MDE: rutero-mde.web.app\n'
        '#RuteroMDE #Medellín';
    final textoEN =
        'Just validated "${widget.sitioNombre}" on $rutaNombre! '
        '$progreso spots · +$puntos points 🏆\n'
        '🌿 Download Rutero MDE: rutero-mde.web.app\n'
        '#RuteroMDE #Medellin';
    final texto = kLang == 'en' ? textoEN : textoES;
    Share.share(texto,
      subject: t('Rutero MDE — Logro desbloqueado', 'Rutero MDE — Achievement unlocked'),
      sharePositionOrigin: Rect.fromLTWH(
        MediaQuery.of(context).size.width / 4,
