              child: StreamBuilder<DocumentSnapshot>(
                stream: AuthService.currentUser != null
                  ? FirebaseFirestore.instance.collection('usuarios').doc(AuthService.currentUser!.uid).snapshots()
                  : const Stream.empty(),
                builder: (ctx, snap) {
                  final data = snap.data?.data() as Map<String, dynamic>? ?? {};
                  final int puntos = (data['puntosTotal'] ?? 0) as int;
                  const niveles = [
                    {'min': 0,    'emoji': '🌱', 'nombre': 'Novato Rutero',       'nombreEN': 'Rutero Novice'},
                    {'min': 300,  'emoji': '🌿', 'nombre': 'Explorador Urbano',   'nombreEN': 'Urban Explorer'},
                    {'min': 700,  'emoji': '⛰️', 'nombre': 'Rutero Paisa',        'nombreEN': 'Paisa Rutero'},
                    {'min': 1200, 'emoji': '🦅', 'nombre': 'Aventurero MDE',      'nombreEN': 'MDE Adventurer'},
                    {'min': 2000, 'emoji': '🏆', 'nombre': 'Leyenda de Medellín', 'nombreEN': 'Medellín Legend'},
                  ];
                  final nivel = niveles.lastWhere((n) => puntos >= ((n['min'] as int?) ?? 0), orElse: () => niveles[0]);
                  final int nivelIdx = niveles.indexOf(nivel) + 1;
                  final String nombreNivel = kLang == 'en' ? nivel['nombreEN']?.toString() ?? '' : nivel['nombre']?.toString() ?? '';
                  final String nivelEmoji = nivel['emoji']?.toString() ?? '';
                  return Column(children: [
                    // Avatar con foto/emoji + botón editar + emoji nivel
                    Stack(alignment: Alignment.bottomRight, children: [
                      Container(width: 100, height: 100,
                        decoration: BoxDecoration(shape: BoxShape.circle,
                          color: RDSColor.card,
                          border: Border.all(color: RDSColor.gold.withOpacity(0.5), width: 2),
                          boxShadow: [BoxShadow(color: RDSColor.gold.withOpacity(0.25), blurRadius: 24, spreadRadius: 2)]),
                        child: ClipOval(child: AuthService.currentUser?.photoURL != null
                          ? Image.network(AuthService.currentUser!.photoURL!,
                              fit: BoxFit.cover,
                              errorBuilder: (_, __, ___) => Center(
                                child: Text(nivelEmoji, style: const TextStyle(fontSize: 48))))
                          : Center(child: Text(nivelEmoji, style: const TextStyle(fontSize: 48))))),
                      // Botón lápiz + emoji nivel
                      Row(mainAxisSize: MainAxisSize.min, children: [
                        // Emoji nivel
                        Container(width: 28, height: 28,
                          decoration: BoxDecoration(shape: BoxShape.circle,
                            color: RDSColor.base,
                            border: Border.all(color: RDSColor.gold.withOpacity(0.4), width: 1.5)),
                          child: Center(child: Text(nivelEmoji, style: const TextStyle(fontSize: 14)))),
                        const SizedBox(width: 4),
                        // Botón editar — ícono sistema
                        GestureDetector(
                          onTap: () => _mostrarEditarPerfil(context),
