          Text(t('MI AVENTURA', 'MY ADVENTURE'),
            style: const TextStyle(fontFamily: 'SpaceGrotesk', fontSize: 10, fontWeight: FontWeight.w700, letterSpacing: 2.0, color: RDSColor.textMuted).copyWith(
              color: RDSColor.textMuted, letterSpacing: 2.5)),
          const SizedBox(height: RDSSpace.md),
          StreamBuilder<DocumentSnapshot>(
            stream: AuthService.currentUser != null
              ? FirebaseFirestore.instance.collection('usuarios').doc(AuthService.currentUser!.uid).snapshots()
              : const Stream.empty(),
            builder: (ctx, snap) {
              final data = snap.data?.data() as Map<String, dynamic>? ?? {};
              final puntos = (data['puntosTotal'] ?? 0) as int;
              // Niveles: 0→Novato, 300→Explorador, 700→Rutero, 1200→Aventurero, 2000→Leyenda
              final niveles = [
                {'min': 0,    'max': 299,  'nombre': t('Novato Rutero','Rutero Novice'),       'emoji': '🌱', 'siguiente': t('Explorador Urbano','Urban Explorer')},
                {'min': 300,  'max': 699,  'nombre': t('Explorador Urbano','Urban Explorer'),   'emoji': '🌿', 'siguiente': t('Rutero Paisa','Paisa Rutero')},
                {'min': 700,  'max': 1199, 'nombre': t('Rutero Paisa','Paisa Rutero'),        'emoji': '⛰️', 'siguiente': t('Aventurero','Adventurer')},
                {'min': 1200, 'max': 1999, 'nombre': t('Aventurero MDE','MDE Adventurer'),      'emoji': '🦅', 'siguiente': t('Leyenda','Legend')},
                {'min': 2000, 'max': 99999,'nombre': t('Leyenda de Medellín','Medellín Legend'), 'emoji': '🏆', 'siguiente': ''},
              ];
              final nivel = niveles.lastWhere((n) => puntos >= ((n['min'] as int?) ?? 0), orElse: () => niveles[0]);
              final maxNivel = (nivel['max'] as int?) ?? 0;
              final minNivel = (nivel['min'] as int?) ?? 0;
              final progreso = maxNivel < 99999
                ? (puntos - minNivel) / (maxNivel - minNivel + 1)
                : 1.0;
              final ptsFaltantes = maxNivel < 99999 ? maxNivel + 1 - puntos : 0;
              return Container(padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(color: RDSColor.card, borderRadius: BorderRadius.circular(14),
                  border: Border.all(color: RDSColor.gold.withOpacity(0.15))),
                child: Column(children: [
                  Row(children: [
                    Container(width: 36, height: 36,
                      decoration: BoxDecoration(shape: BoxShape.circle,
                        gradient: LinearGradient(colors: [RDSColor.green.withOpacity(0.3), RDSColor.gold.withOpacity(0.2)])),
                      child: Center(child: Text(nivel['emoji']?.toString() ?? '', style: const TextStyle(fontSize: 18)))),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text('${nivel['nombre']}', style: const TextStyle(color: RDSColor.textPrimary, fontSize: 13, fontWeight: FontWeight.w600)),
                      Text('$puntos / ${maxNivel < 99999 ? maxNivel + 1 : puntos} ${t("puntos","pts")}',
                        style: const TextStyle(color: RDSColor.textMuted, fontSize: 11)),
                    ])),
                    Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(color: RDSColor.gold.withOpacity(0.1), borderRadius: BorderRadius.circular(8)),
                      child: Text('${(progreso * 100).toInt()}%',
                        style: const TextStyle(color: RDSColor.gold, fontSize: 12, fontWeight: FontWeight.w700))),
                  ]),
                  const SizedBox(height: 12),
                  ClipRRect(borderRadius: BorderRadius.circular(6),
                    child: TweenAnimationBuilder<double>(
                      tween: Tween(begin: 0.0, end: progreso.clamp(0.0, 1.0)),
                      duration: const Duration(milliseconds: 900),
                      curve: Curves.easeOutCubic,
                      builder: (_, value, __) => LinearProgressIndicator(
                        value: value,
                        backgroundColor: Colors.white.withOpacity(0.06),
                        valueColor: const AlwaysStoppedAnimation<Color>(RDSColor.gold),
                        minHeight: 10))),
                  const SizedBox(height: 8),
                  Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
                    Text(maxNivel < 99999
                      ? '$ptsFaltantes ${t("pts para","pts to")} ${nivel['siguiente']} 🎯'
                      : t('¡Leyenda de Medellín! 🏆','Medellín Legend! 🏆'),
                      style: TextStyle(color: RDSColor.textMuted.withOpacity(0.7), fontSize: 10)),
                    if (maxNivel < 99999)
                      Text('${t("Próximo","Next")}: ${nivel['siguiente']}',
                        style: TextStyle(color: RDSColor.gold.withOpacity(0.5), fontSize: 10)),
                  ]),
                ]));
            }),

          const SizedBox(height: 24),

          const SizedBox(height: RDSSpace.xl),
          // ── Mis insignias ────────────────────────────────────────────
          Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [
            Text(t('MIS INSIGNIAS', 'MY BADGES'),
              style: const TextStyle(fontFamily: 'SpaceGrotesk', fontSize: 10, fontWeight: FontWeight.w700, letterSpacing: 2.0, color: RDSColor.textMuted).copyWith(
                color: RDSColor.textMuted, letterSpacing: 2.5)),
            GestureDetector(
