  Future<BitmapDescriptor> _markerConLogo({
    Color fondo = const Color(0xFF2E7D32),
    String label = '',
  }) async {
    // Cargar logo
    final ByteData logoData = await rootBundle.load('assets/images/logo_splash.png');
    final ui.Codec codec = await ui.instantiateImageCodec(
      logoData.buffer.asUint8List(), targetWidth: 44, targetHeight: 44);
    final ui.FrameInfo fi = await codec.getNextFrame();
    final ui.Image logoImg = fi.image;

    // Canvas del marcador
    final recorder = ui.PictureRecorder();
    final canvas = Canvas(recorder);
    const double w = 64, h = 80, r = 28;
    const Offset c = Offset(w/2, r+4);

    // Sombra
    canvas.drawCircle(Offset(c.dx, c.dy+4), r+2,
      Paint()..color=Colors.black45..maskFilter=const MaskFilter.blur(BlurStyle.normal,6));
    // Fondo blanco
    canvas.drawCircle(c, r+3, Paint()..color=Colors.white);
    // Círculo de color
    canvas.drawCircle(c, r, Paint()..color=fondo);
    // Logo recortado en círculo
    final clip = Path()..addOval(Rect.fromCircle(center:c, radius:r-2));
    canvas.save(); canvas.clipPath(clip);
    canvas.drawImage(logoImg, Offset(c.dx-22, c.dy-22), Paint());
    canvas.restore();
    // Punta del pin
    final tri = Path()
      ..moveTo(w/2-8, c.dy+r-1)..lineTo(w/2, h-4)..lineTo(w/2+8, c.dy+r-1)..close();
    canvas.drawPath(tri, Paint()..color=fondo);
    canvas.drawPath(tri, Paint()..color=Colors.white..style=PaintingStyle.stroke..strokeWidth=1.5);
    // Label si hay
    if (label.isNotEmpty) {
      final tp = TextPainter(
        text: TextSpan(text:label, style:const TextStyle(fontSize:10,color:Colors.white,fontWeight:FontWeight.w800)),
        textDirection: TextDirection.ltr)..layout();
      tp.paint(canvas, Offset(c.dx-tp.width/2, c.dy+r-tp.height-2));
    }

    final img = await recorder.endRecording().toImage(w.toInt(), h.toInt());
    final bytes = await img.toByteData(format: ui.ImageByteFormat.png);
    return BitmapDescriptor.fromBytes(bytes!.buffer.asUint8List());
  }

  Future<BitmapDescriptor> _crearPinBloqueado() async {
    final rec = ui.PictureRecorder();
    final c = Canvas(rec);
    const double w = 72.0, h = 88.0, r = 28.0;
    final Offset center = const Offset(w/2, r+6);
    c.drawCircle(Offset(center.dx, center.dy+4), r+2,
      Paint()..color=Colors.black45..maskFilter=const MaskFilter.blur(BlurStyle.normal,6));
    c.drawCircle(center, r+3, Paint()..color=Colors.white);
    c.drawCircle(center, r, Paint()..color=const Color(0xFF1B4332));
    c.drawCircle(center, r-3,
      Paint()..color=RDSColor.gold..style=PaintingStyle.stroke..strokeWidth=2);
    final tp = TextPainter(
      text: const TextSpan(text: '🔒', style: TextStyle(fontSize: 26)),
      textDirection: TextDirection.ltr)..layout();
    tp.paint(c, Offset(center.dx-tp.width/2, center.dy-tp.height/2-1));
    final tri = Path()
      ..moveTo(w/2-8, center.dy+r-1)..lineTo(w/2, h-4)..lineTo(w/2+8, center.dy+r-1)..close();
    c.drawPath(tri, Paint()..color=const Color(0xFF1B4332));
    c.drawPath(tri, Paint()..color=Colors.white..style=PaintingStyle.stroke..strokeWidth=1.5);
    c.drawCircle(Offset(w/2, h-6), 2.5, Paint()..color=RDSColor.gold.withOpacity(0.8));
    final img = await rec.endRecording().toImage(w.toInt(), h.toInt());
    final bytes = await img.toByteData(format: ui.ImageByteFormat.png);
    return BitmapDescriptor.fromBytes(bytes!.buffer.asUint8List());
  }

  Future<BitmapDescriptor> _crearIconoAgrupado(int count) async {
    final rec = ui.PictureRecorder();
    final c = Canvas(rec);
    const double w = 72.0, h = 80.0;
    c.drawCircle(const Offset(w/2, w/2+3), w/2-2,
      Paint()..color=Colors.black.withOpacity(0.5)..maskFilter=const MaskFilter.blur(BlurStyle.normal,5));
    c.drawCircle(const Offset(w/2, w/2), w/2-3, Paint()..color=const Color(0xFFFFD700));
    c.drawCircle(const Offset(w/2, w/2), w/2-3,
      Paint()..color=Colors.white..style=PaintingStyle.stroke..strokeWidth=2.5);
    final tp = TextPainter(
      text: const TextSpan(text: '🔒', style: TextStyle(fontSize: 26)),
      textDirection: TextDirection.ltr)..layout();
    tp.paint(c, Offset((w-tp.width)/2, (w/2-tp.height)/2));
    if (count > 0) {
      final label = TextPainter(
        text: TextSpan(text: '$count RUTAS',
          style: const TextStyle(fontSize: 11, color: Colors.white,
            fontWeight: FontWeight.w800, letterSpacing: 0.5)),
        textDirection: TextDirection.ltr)..layout();
      label.paint(c, Offset((w-label.width)/2, w/2+6));
    }
    final img = await rec.endRecording().toImage(w.toInt(), h.toInt());
    final bytes = await img.toByteData(format: ui.ImageByteFormat.png);
    return BitmapDescriptor.fromBytes(bytes!.buffer.asUint8List());
  }

  Future<void> _cargarIconos() async {
    // Logo Rutero MDE — cargar uno a uno para no perder todos si uno falla
    try { _iconCache['Logo']         = await _markerConLogo(fondo: RDSColor.green); }
    catch (e) { debugPrint('🔴 Logo error: \$e'); }
    try { _iconCache['LogoVisitado'] = await _markerConLogo(fondo: RDSColor.gold, label: '✓'); }
    catch (e) { debugPrint('🔴 LogoVisitado error: \$e'); }
    try { _iconCache['LogoSel']      = await _markerConLogo(fondo: RDSColor.accent); }
    catch (e) { debugPrint('🔴 LogoSel error: \$e'); }
    // Candados
    try { _iconCache['PinBloqueado'] = await _crearPinBloqueado(); }
    catch (e) { debugPrint('🔴 PinBloqueado error: \$e'); }
    try { _iconCache['Agrupado_2']   = await _crearIconoAgrupado(2); }
    catch (e) { debugPrint('🔴 Agrupado_2 error: \$e'); }
    try { _iconCache['Agrupado_3']   = await _crearIconoAgrupado(3); }
    catch (e) { debugPrint('🔴 Agrupado_3 error: \$e'); }
    try { _iconCache['Agrupado_4']   = await _crearIconoAgrupado(4); }
    catch (e) { debugPrint('🔴 Agrupado_4 error: \$e'); }
    // Pin EnCicla — círculo verde pequeño con ícono de bicicleta
    try { _iconCache['encicla']     = await _crearPinEnCicla(seleccionado: false); }
    catch (e) { debugPrint('🔴 encicla error: $e'); }
    try { _iconCache['encicla_sel'] = await _crearPinEnCicla(seleccionado: true); }
    catch (e) { debugPrint('🔴 encicla_sel error: $e'); }
    if (mounted) setState(() => _iconsLoaded = true);
  }


  Future<BitmapDescriptor> _crearPinEnCicla({required bool seleccionado}) async {
    const size = 28.0;
    final recorder = ui.PictureRecorder();
    final canvas = Canvas(recorder);
    final paint = Paint()
      ..color = seleccionado ? const Color(0xFF004FA3) : const Color(0xFF0066CC)
      ..style = PaintingStyle.fill;
    final border = Paint()
      ..color = Colors.white.withOpacity(seleccionado ? 1.0 : 0.7)
      ..style = PaintingStyle.stroke
      ..strokeWidth = seleccionado ? 2.5 : 1.5;
    canvas.drawCircle(const Offset(size / 2, size / 2), size / 2 - 1, paint);
    canvas.drawCircle(const Offset(size / 2, size / 2), size / 2 - 1, border);
    final tp = TextPainter(
      text: const TextSpan(text: '🚲', style: TextStyle(fontSize: 14)),
      textDirection: TextDirection.ltr);
    tp.layout();
    tp.paint(canvas, Offset((size - tp.width) / 2, (size - tp.height) / 2));
    final img = await recorder.endRecording().toImage(size.toInt(), size.toInt());
    final bytes = await img.toByteData(format: ui.ImageByteFormat.png);
    return BitmapDescriptor.fromBytes(bytes!.buffer.asUint8List());
  }

  Future<void> _cargarRutasDesbloqueadas() async {
    // Rutas siempre visibles (punto de entrada gratuito)
    final rutasBase = {
      'RUTA TRANSFORMACIÓN URBANA',
    };

    final user = AuthService.currentUser;
    if (user == null) {
      if (mounted) setState(() => _rutasDesbloqueadas = rutasBase);
      return;
    }
    try {
      final snapC = await FirebaseFirestore.instance
        .collection('usuarios').doc(user.uid)
        .collection('rutasCompletadas').get();
      final completadas = snapC.docs.map((d) => d.id).toSet();

      final snapP = await FirebaseFirestore.instance
        .collection('usuarios').doc(user.uid)
        .collection('progreso')
        .where('completada', isEqualTo: true).get();
      final completadasProgreso = snapP.docs.map((d) => d.id).toSet();

      final snapR = await FirebaseFirestore.instance
        .collection('usuarios').doc(user.uid)
        .collection('rutasCompradas').get();
      final compradas = snapR.docs.map((d) => d.id).toSet();

      if (mounted) setState(() {
        _rutasDesbloqueadas = {...rutasBase, ...completadas, ...completadasProgreso, ...compradas};
      });
    } catch (e) {
      debugPrint('Error cargando rutas mapa: $e');
      if (mounted) setState(() => _rutasDesbloqueadas = rutasBase);
    }
  }

  // Verifica si un sitio está visible
  // Ruta desbloqueada → todos sus sitios visibles
  // Ruta bloqueada → solo el primer sitio (pin 🔒 en el punto de inicio de la ruta)
  bool _sitioVisible(_SitioMapa sitio) {
    if (_rutasDesbloqueadas.contains(sitio.ruta)) return true;
    // Buscar el primer sitio con coords de esta ruta en Firestore
    final ruta = RutasService().rutas.firstWhere(
      (r) => r['nombre']?.toString() == sitio.ruta,
      orElse: () => <String, dynamic>{});
    if (ruta.isEmpty) {
      // Fallback: kSitiosMapa
      final sitiosDeRuta = kSitiosMapa.where((s) => s.ruta == sitio.ruta).toList();
      return sitiosDeRuta.isNotEmpty && sitiosDeRuta.first.nombre == sitio.nombre;
    }
    // Obtener primer sitio con coords válidas
    final detalle = parseSitiosDetalle(ruta['sitiosDetalle']);
    final gpsRaw = ruta['gpsSitios'];
    final gpsList = gpsRaw is List ? gpsRaw : <dynamic>[];
    final fuente = detalle.isNotEmpty ? detalle : gpsList;
    for (final s in fuente) {
      if (s is! Map) continue;
      final lat = (s['lat'] as num?)?.toDouble();
      final lng = (s['lng'] as num?)?.toDouble();
      if (lat == null || lng == null) continue;
      // Este es el primer sitio válido — es el único que debe mostrar el candado
      return s['nombre']?.toString() == sitio.nombre;
    }
    return false;
  }

  bool _rutaBloqueada(String ruta) => !_rutasDesbloqueadas.contains(ruta);

  // _filtros se genera dinámicamente según ciudad seleccionada
  List<String> get _filtros {
    // Combinar rutas de kSitiosMapa + rutas de Firestore
    final rutasHardcoded = kSitiosMapa.map((s) => s.ruta).toSet();
    final rutasFirestore = <String>{};
    for (final ruta in RutasService().rutas) {
      final nombre = ruta['nombre']?.toString() ?? '';
      final gpsRaw = ruta['gpsSitios'];
      final gpsList = gpsRaw is List ? gpsRaw : <dynamic>[];
      final detalle = parseSitiosDetalle(ruta['sitiosDetalle']);
      if (nombre.isNotEmpty && (gpsList.isNotEmpty || detalle.isNotEmpty)) {
        rutasFirestore.add(nombre);
      }
    }
    final todas = {...rutasHardcoded, ...rutasFirestore}.toList()..sort();
    return ['Todas', ...todas];
  }

  static const _centerMDE = LatLng(6.2518, -75.5636);

  static const String _mapStyle = '''[
    {"elementType":"geometry","stylers":[{"color":"#0f1a0a"}]},
    {"elementType":"labels.text.fill","stylers":[{"color":"#8a9278"}]},
    {"elementType":"labels.text.stroke","stylers":[{"color":"#0d0d0d"}]},
    {"featureType":"road","elementType":"geometry","stylers":[{"color":"#1a2a14"}]},
    {"featureType":"road.highway","elementType":"geometry","stylers":[{"color":"#2a3a1a"}]},
    {"featureType":"water","elementType":"geometry","stylers":[{"color":"#0a1a2a"}]},
    {"featureType":"poi.park","elementType":"geometry","stylers":[{"color":"#0d1f0d"}]},
    {"featureType":"transit","elementType":"geometry","stylers":[{"color":"#1a2a14"}]}
  ]''';

  List<_SitioMapa> get _sitiosFiltrados {
    // Combinar sitios hardcodeados + sitios de Firestore (gpsSitios/sitiosDetalle)
    final todos = <_SitioMapa>[...kSitiosMapa];

    // Agregar sitios de rutas de Firestore que NO están en kSitiosMapa
    final nombresExistentes = kSitiosMapa.map((s) => '${s.nombre}||${s.ruta}').toSet();
    for (final ruta in RutasService().rutas) {
      final rutaNombre = ruta['nombre']?.toString() ?? '';
      final acento = ruta['acento'];
      final color = acento is Color ? acento : const Color(0xFFC9A84C);

      // Usar sitiosDetalle si existe, sino gpsSitios
      final detalle = parseSitiosDetalle(ruta['sitiosDetalle']);
      final gpsRaw = ruta['gpsSitios'];
      final gpsList = gpsRaw is List ? gpsRaw : <dynamic>[];

      if (detalle.isNotEmpty) {
        for (final s in detalle) {
          if (s is! Map) continue;
          final nombre = s['nombre']?.toString() ?? '';
          final lat = (s['lat'] as num?)?.toDouble();
          final lng = (s['lng'] as num?)?.toDouble();
          if (nombre.isEmpty || lat == null || lng == null) continue;
          if (nombresExistentes.contains('$nombre||$rutaNombre')) continue;
          nombresExistentes.add('$nombre||$rutaNombre');
          todos.add(_SitioMapa(
            nombre: nombre,
            emoji: s['emoji']?.toString() ?? '📍',
            posicion: LatLng(lat, lng),
            ruta: rutaNombre,
            color: color,
            radioGps: 60,
          ));
        }
      } else if (gpsList.isNotEmpty) {
        for (final g in gpsList) {
          if (g is! Map) continue;
          final nombre = g['nombre']?.toString() ?? '';
          final lat = (g['lat'] as num?)?.toDouble();
          final lng = (g['lng'] as num?)?.toDouble();
          if (nombre.isEmpty || lat == null || lng == null) continue;
          if (nombresExistentes.contains('$nombre||$rutaNombre')) continue;
          nombresExistentes.add('$nombre||$rutaNombre');
          todos.add(_SitioMapa(
            nombre: nombre,
            emoji: '📍',
            posicion: LatLng(lat, lng),
            ruta: rutaNombre,
            color: color,
            radioGps: 60,
          ));
        }
      }
    }

    // Filtrar por ruta seleccionada
    final porRuta = _filtroRuta == 'Todas'
      ? todos
      : todos.where((s) => s.ruta == _filtroRuta).toList();
    return porRuta;
  }

  // Zona de cada ruta para elegir ícono


  Set<Marker> _buildMarkers() {
    final bool selHay = _sitioSeleccionado != null;
    final Set<Marker> markers = {};

    // ── Marcadores EnCicla ────────────────────────────────────────────────
    if (_mostrarEnCicla && _zoomActual >= 13.5) {
      for (final est in _estacionesEnCicla) {
        final lat = (est['lat'] as num?)?.toDouble() ?? 0;
        final lng = (est['lng'] as num?)?.toDouble() ?? 0;
        if (lat == 0 && lng == 0) continue;
        final id = est['id']?.toString() ?? '';
        final nombre = est['nombre']?.toString() ?? '';
        final esSeleccionada = _estacionEnCiclaSeleccionada?['id'] == id;
        final icon = _iconCache['encicla${esSeleccionada ? '_sel' : ''}']
            ?? BitmapDescriptor.defaultMarkerWithHue(BitmapDescriptor.hueGreen);
        markers.add(Marker(
          markerId: MarkerId('encicla_$id'),
          position: LatLng(lat, lng),
          icon: icon,
          zIndex: esSeleccionada ? 2.5 : 0.8,
          anchor: const Offset(0.5, 0.5),
          onTap: () {
            setState(() {
              _estacionEnCiclaSeleccionada = est;
              _sitioSeleccionado = null;
            });
            _mapController?.animateCamera(
                CameraUpdate.newLatLngZoom(LatLng(lat, lng), 16));
            _mostrarInfoEnCicla(est);
          },
        ));
      }
    }

    for (final sitio in _sitiosFiltrados) {
      final bool bloqueado = _rutaBloqueada(sitio.ruta);
      final bool visible = _sitioVisible(sitio);

      // Solo mostrar el primer sitio de cada ruta bloqueada — el resto se
      // revela a medida que el usuario visita y valida cada lugar.
      // Esto evita que el mapa sirva de guía turística sin usar la app.
      if (bloqueado && !visible) continue;

      // Deduplicar pines bloqueados con mismas coordenadas
      if (bloqueado) {
        final String coordKey = sitio.posicion.latitude.toStringAsFixed(4) + ',' + sitio.posicion.longitude.toStringAsFixed(4);
        final String lockId = 'lock_' + coordKey;
        if (markers.any((m) => m.markerId.value == lockId)) continue;
      }

      final bool esSel = selHay && sitio.nombre == (_sitioSeleccionado?.nombre ?? '');
      BitmapDescriptor icon;

      // Fallback: marcador neutro — evita el pin verde nativo de Google Maps
      // que aparecía debajo del logo Rutero cuando el icono custom tardaba en cargar.
      // BitmapDescriptor.defaultMarker es el pin rojo estándar y no genera conflicto visual.
      final BitmapDescriptor _logoFallback =
        _iconCache['Logo'] ?? BitmapDescriptor.defaultMarker;

      if (bloqueado) {
        final String coordKey = sitio.posicion.latitude.toStringAsFixed(4) + ',' + sitio.posicion.longitude.toStringAsFixed(4);
        final int rutasEnPunto = _sitiosFiltrados.where((s) {
          if (!_rutaBloqueada(s.ruta)) return false;
          final primero = kSitiosMapa.where((x) => x.ruta == s.ruta).isNotEmpty
              ? kSitiosMapa.where((x) => x.ruta == s.ruta).first
              : null;
          if (primero == null) return false;
          return primero.posicion.latitude.toStringAsFixed(4) + ',' + primero.posicion.longitude.toStringAsFixed(4) == coordKey;
        }).map((s) => s.ruta).toSet().length;

        if (rutasEnPunto > 1) {
          icon = _iconCache['Agrupado_${rutasEnPunto.clamp(2,4)}'] ?? _iconCache['PinBloqueado'] ?? _logoFallback;
        } else {
          icon = _iconCache['PinBloqueado'] ?? _logoFallback;
        }
      } else if (esSel) {
        icon = _iconCache['LogoSel'] ?? _logoFallback;
      } else if (sitio.visitado) {
        icon = _iconCache['LogoVisitado'] ?? _logoFallback;
      } else {
        icon = _iconCache['Logo'] ?? _logoFallback;
      }

      // markerId único — sin escapado erróneo
      final String mId = bloqueado
        ? 'lock_${sitio.posicion.latitude.toStringAsFixed(4)},${sitio.posicion.longitude.toStringAsFixed(4)}'
        : sitio.nombre;
      markers.add(Marker(
        markerId: MarkerId(mId),
        position: sitio.posicion,
        icon: icon,
        zIndex: esSel ? 2.0 : (bloqueado ? 0.5 : 1.0),
        anchor: const Offset(0.5, 1.0),
        onTap: () {
          if (bloqueado) {
            setState(() { _sitioSeleccionado = sitio; _fabExpandido = false; });
            _mapController?.animateCamera(
              CameraUpdate.newLatLngZoom(sitio.posicion, 16));
            _mostrarAlertaBloqueado(sitio.ruta);
          } else {
            setState(() { _sitioSeleccionado = sitio; _fabExpandido = false; });
            _mapController?.animateCamera(
              CameraUpdate.newLatLngZoom(sitio.posicion, 16));
          }
        },
      ));
    }
    return markers;
  }

