//  AVATAR RUTERO WIDGET
// ─────────────────────────────────────────
class _AvatarRutero extends StatefulWidget {
  final String mensaje;
  final String pose; // 'normal','tip','celebracion','camara','señalando','listo'
  final bool visible;
  final VoidCallback? onCerrar;
  const _AvatarRutero({required this.mensaje, this.pose = 'normal',
    this.visible = true, this.onCerrar});
  @override
  State<_AvatarRutero> createState() => _AvatarRuteroState();
}

class _AvatarRuteroState extends State<_AvatarRutero>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<double> _slideAnim;
  late Animation<double> _fadeAnim;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 500));
    _slideAnim = Tween<double>(begin: 80, end: 0).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeOutBack));
    _fadeAnim = Tween<double>(begin: 0, end: 1).animate(
      CurvedAnimation(parent: _ctrl, curve: Curves.easeOut));
    if (widget.visible) _ctrl.forward();
  }

  @override
  void didUpdateWidget(_AvatarRutero old) {
    super.didUpdateWidget(old);
    if (widget.visible && !old.visible) _ctrl.forward();
    else if (!widget.visible && old.visible) _ctrl.reverse();
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  String get _imgPose {
    switch (widget.pose) {
      case 'celebracion': return 'assets/images/avatar/avatar_celebracion.png';
      case 'camara':      return 'assets/images/avatar/avatar_camara.png';
      case 'señalando':   return 'assets/images/avatar/avatar_señalando.png';
      case 'listo':       return 'assets/images/avatar/avatar_listo.png';
      case 'tip':         return 'assets/images/avatar/avatar_tip.png';
      default:            return 'assets/images/avatar/avatar_normal.png';
    }
  }

  @override
  Widget build(BuildContext context) => AnimatedBuilder(
    animation: _ctrl,
    builder: (_, __) => Transform.translate(
      offset: Offset(0, _slideAnim.value),
      child: Opacity(opacity: _fadeAnim.value,
        child: Row(crossAxisAlignment: CrossAxisAlignment.end,
          mainAxisAlignment: MainAxisAlignment.start,
          children: [
            Image.asset(_imgPose, height: 130, fit: BoxFit.contain,
              errorBuilder: (_, __, ___) => const Text('🧑', style: TextStyle(fontSize: 60))),
            const SizedBox(width: 8),
            Flexible(child: Stack(children: [
              Container(
                margin: const EdgeInsets.only(bottom: 8),
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),
                decoration: BoxDecoration(
                  color: RDSColor.card,
                  borderRadius: const BorderRadius.only(
                    topLeft: Radius.circular(16), topRight: Radius.circular(16),
                    bottomRight: Radius.circular(16)),
                  border: Border.all(color: RDSColor.green.withOpacity(0.3), width: 1.5),
                  boxShadow: [BoxShadow(color: RDSColor.green.withOpacity(0.1), blurRadius: 12)]),
                child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                  Row(children: [
                    Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 2),
                      decoration: BoxDecoration(
                        color: RDSColor.green.withOpacity(0.15),
                        borderRadius: BorderRadius.circular(8)),
                      child: const Text('RUTERO MDE', style: TextStyle(
                        color: RDSColor.green, fontSize: 9, fontWeight: FontWeight.w900, letterSpacing: 1))),
                    const Spacer(),
                    if (widget.onCerrar != null)
                      GestureDetector(onTap: widget.onCerrar,
                        child: const Text('✕', style: TextStyle(color: RDSColor.textMuted, fontSize: 12))),
                  ]),
                  const SizedBox(height: 6),
                  Text(widget.mensaje,
                    style: const TextStyle(color: RDSColor.textPrimary, fontSize: 12, height: 1.4)),
                ])),
              Positioned(left: 0, bottom: 0,
                child: CustomPaint(size: const Size(12, 10),
                  painter: _BubbleTailPainter())),
            ])),
          ]))));
}

class _BubbleTailPainter extends CustomPainter {
  @override
  void paint(Canvas canvas, Size size) {
    final p = Paint()..color = RDSColor.card;
    final path = Path()
      ..moveTo(0, 0) ..lineTo(size.width, 0) ..lineTo(size.width, size.height) ..close();
    canvas.drawPath(path, p);
    final border = Paint()..color = RDSColor.green.withOpacity(0.3)..style = PaintingStyle.stroke..strokeWidth = 1.5;
    canvas.drawPath(path, border);
  }
  @override bool shouldRepaint(_) => false;
}

