// ─────────────────────────────────────────
//  WIDGET AVATAR CON TIP
// ─────────────────────────────────────────
class AvatarTip extends StatefulWidget {
  final String mensaje;
  final String pose; // 'tip', 'normal', 'celebracion', 'señalando', 'camara', 'mochila'
  final VoidCallback? onCerrar;
  final bool autoClose;
  const AvatarTip({super.key, required this.mensaje, this.pose = 'tip',
    this.onCerrar, this.autoClose = true});
  @override State<AvatarTip> createState() => _AvatarTipState();
}

class _AvatarTipState extends State<AvatarTip> with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;
  late Animation<Offset> _slideAnim;
  late Animation<double> _fadeAnim;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(vsync: this, duration: const Duration(milliseconds: 500));
    _slideAnim = Tween<Offset>(begin: const Offset(0, 1), end: Offset.zero)
      .animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeOutBack));
    _fadeAnim = Tween<double>(begin: 0, end: 1)
      .animate(CurvedAnimation(parent: _ctrl, curve: Curves.easeOut));
    _ctrl.forward();
    if (widget.autoClose) {
      Future.delayed(const Duration(seconds: 12), () {
        if (mounted) _ctrl.reverse().then((_) => widget.onCerrar?.call());
      });
    }
  }

  @override
  void dispose() { _ctrl.dispose(); super.dispose(); }

  String get _imagenPose {
    switch (widget.pose) {
      case 'celebracion': return 'assets/images/avatar/avatar_celebracion.png';
      case 'camara':      return 'assets/images/avatar/avatar_camara.png';
      case 'señalando':   return 'assets/images/avatar/avatar_señalando.png';
      case 'mochila':     return 'assets/images/avatar/avatar_mochila.png';
      case 'normal':      return 'assets/images/avatar/avatar_normal.png';
      default:            return 'assets/images/avatar/avatar_tip.png';
    }
  }

  @override
  Widget build(BuildContext context) => SlideTransition(
    position: _slideAnim,
    child: FadeTransition(
      opacity: _fadeAnim,
      child: Container(
        margin: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
        child: Row(crossAxisAlignment: CrossAxisAlignment.end, children: [
          Image.asset(_imagenPose, height: 120,
            errorBuilder: (_, __, ___) => const Text('🧑', style: TextStyle(fontSize: 60))),
          const SizedBox(width: 8),
          Expanded(child: Stack(children: [
            Container(
              padding: const EdgeInsets.fromLTRB(14, 12, 36, 12),
              decoration: BoxDecoration(
                color: RDSColor.card,
                borderRadius: const BorderRadius.only(
                  topLeft: Radius.circular(18),
                  topRight: Radius.circular(18),
                  bottomRight: Radius.circular(18),
                  bottomLeft: Radius.circular(4)),
                border: Border.all(color: RDSColor.green.withOpacity(0.4), width: 1.5),
                boxShadow: [
                  BoxShadow(color: RDSColor.green.withOpacity(0.1), blurRadius: 12),
                  BoxShadow(color: Colors.black.withOpacity(0.3), blurRadius: 8),
                ]),
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Row(children: [
                  Container(width: 6, height: 6,
                    decoration: const BoxDecoration(color: RDSColor.green, shape: BoxShape.circle)),
                  const SizedBox(width: 6),
                  const Text('RUTERO', style: TextStyle(
                    color: RDSColor.green, fontSize: 9, fontWeight: FontWeight.w900, letterSpacing: 2)),
                ]),
                const SizedBox(height: 6),
                Text(widget.mensaje,
                  style: const TextStyle(color: RDSColor.textPrimary, fontSize: 12, height: 1.5)),
              ])),
            if (widget.onCerrar != null)
              Positioned(top: 6, right: 6,
                child: GestureDetector(
                  onTap: () => _ctrl.reverse().then((_) => widget.onCerrar?.call()),
                  child: Container(
                    width: 22, height: 22,
                    decoration: BoxDecoration(
                      color: Colors.white.withOpacity(0.08),
                      shape: BoxShape.circle),
                    child: const Center(
                      child: Text('✕',
                        style: TextStyle(color: RDSColor.textMuted, fontSize: 10)))))),
          ])),
        ]))));
}

