          ])),

        const SizedBox(height: 12),
        // Instrucciones
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: RDSColor.card,
            borderRadius: BorderRadius.circular(12),
            border: Border.all(color: Colors.white.withOpacity(0.06))),
          child: const Row(children: [
            Text('ℹ️', style: TextStyle(fontSize: 16)),
            SizedBox(width: 8),
            Expanded(child: Text(
              'El código tiene validez de 30 días. Preséntalo en el establecimiento aliado junto con tu nombre.',
              style: TextStyle(color: RDSColor.textMuted, fontSize: 11, height: 1.4))),
          ])),

        // ── ALIADO ASOCIADO A LA RUTA ──
        Builder(builder: (_) {
          final aliado = AliadosService().aliadoParaRuta(widget.ruta['nombre']?.toString() ?? '');
          if (aliado == null) return const SizedBox.shrink();
          return Padding(
            padding: const EdgeInsets.only(top: 14),
            child: _AliadoRutaCard(aliado: aliado, nombreRuta: widget.ruta['nombre']?.toString(), codigoRuta: _codigo));
        }),
      ]));
  }
