// ════════════════════════════════════════════════════════════════════════════
//  ALIANZA LOCAL TOURS — Card de transporte Hop-On/Hop-Off (16/05/2026)
// ════════════════════════════════════════════════════════════════════════════
//  CONTEXTO ESTRATÉGICO:
//   • Modelo: Transporte como valor agregado SIN cobro adicional al turista
//   • Turista contacta a Alianza Local Tours directamente por WhatsApp
//   • Rutero MDE cobra comisión por referido (10-15%)
//   • Sin doble pago, sin necesidad de Wompi para esta integración
//   • Permite validar el modelo ANTES de tener Wompi integrado
//
//  TÉCNICO:
//   • Card embebida en RouteDetailScreen entre Premio y Sitios
//   • Solo se muestra si la ruta cubre destinos de Alianza Local Tours
//   • Genera código único RUT-XXX-NNNN al tocar WhatsApp
//   • Mensaje predefinido bilingüe ES/EN
//   • Cumple control: códigos generados quedan en log para cruce con Alianza
//
//  DESTINOS CUBIERTOS POR ALIANZA LOCAL TOURS:
// ════════════════════════════════════════════════════════════════════════════

/// Determina si una ruta tiene aliado de transporte (Alianza Local Tours).
/// Por ahora se evalúa por palabras clave en el nombre. En el futuro:
/// se obtendrá de Firestore (campo aliados[] de la ruta).
bool _tieneAliadoTransporte(Map<String, dynamic> ruta) {
  // 🚫 PAUSADO — Alianza Local Tours pendiente de formalizar alianza
  // Reactivar cuando se confirme convenio con Fredy (573148057983)
  return false;
}

/// Devuelve el prefijo del código según la ruta (RUT-GTP, RUT-CON, etc.)
String _prefijoCodigoTransporte(Map<String, dynamic> ruta) {
  final nombre = (ruta['nombre']?.toString() ?? '').toUpperCase();
  if (nombre.contains('GUATAP') || nombre.contains('PEÑOL') || nombre.contains('PENOL')) return 'RUT-GTP';
  if (nombre.contains('CONCEPCI')) return 'RUT-CON';
  if (nombre.contains('ALEJANDR')) return 'RUT-ALE';
  if (nombre.contains('SAN VICENTE')) return 'RUT-SVI';
  if (nombre.contains('CISNEROS')) return 'RUT-CIS';
  if (nombre.contains('SAN RAFAEL')) return 'RUT-SRF';
  if (nombre.contains('NECOCL')) return 'RUT-NEC';
  return 'RUT-GEN';  // genérico (no debería ocurrir si pasa _tieneAliadoTransporte)
}

/// Devuelve el destino legible según la ruta (para WhatsApp message)
String _destinoLegibleTransporte(Map<String, dynamic> ruta) {
  final nombre = (ruta['nombre']?.toString() ?? '').toUpperCase();
  if (nombre.contains('GUATAP') || nombre.contains('PEÑOL') || nombre.contains('PENOL')) return 'Guatapé';
  if (nombre.contains('ALEJANDR')) return 'Alejandría';
  if (nombre.contains('SAN VICENTE')) return 'San Vicente Ferrer';
  if (nombre.contains('CISNEROS')) return 'Cisneros';
  if (nombre.contains('SAN RAFAEL')) return 'San Rafael';
  return 'destino';
}

class _TransporteAliadoCard extends StatefulWidget {
  final Map<String, dynamic> ruta;
  const _TransporteAliadoCard({required this.ruta});

  @override
  State<_TransporteAliadoCard> createState() => _TransporteAliadoCardState();
}

class _TransporteAliadoCardState extends State<_TransporteAliadoCard> {
  // WhatsApp oficial de Alianza Local Tours (de su web alianzalocaltours.com)
  // TODO(16/05/2026): mover a constante o Firestore cuando esté la estructura de aliados
  static const String _whatsappAlianza = '573148057983';  // Alianza Local Tours (confirmado 20/05/2026)

  late final String _codigo;
  late final String _destino;
  late final String _prefijo;

  @override
  void initState() {
    super.initState();
    // Generar código único UNA SOLA VEZ por sesión de visualización
    // Formato: RUT-{DESTINO}-{4 dígitos aleatorios}
    // Ejemplo: RUT-GTP-7341
    _prefijo = _prefijoCodigoTransporte(widget.ruta);
    _destino = _destinoLegibleTransporte(widget.ruta);
    final rnd = math.Random();
    final numero = (1000 + rnd.nextInt(9000)).toString();  // 1000-9999
    _codigo = '$_prefijo-$numero';
  }

  Future<void> _abrirWhatsApp() async {
    // Mensajes predefinidos bilingües con código incrustado
    final mensajeES =
        'Hola Alianza Local Tours 👋 Vengo de Rutero MDE 🗺️ '
        'Me interesa el bus a $_destino. '
        'Mi código Rutero: $_codigo '
        '¿Cuál es el próximo horario de salida?';

    final mensajeEN =
        'Hi Alianza Local Tours 👋 I found you through Rutero MDE 🗺️ '
        "I'd like to take the bus to $_destino. "
        'My Rutero code: $_codigo '
        "What's the next departure time?";

    final mensaje = kLang == 'en' ? mensajeEN : mensajeES;
    final urlMensaje = Uri.encodeComponent(mensaje);
    final url = Uri.parse('https://wa.me/$_whatsappAlianza?text=$urlMensaje');

    try {
      final ok = await launchUrl(url, mode: LaunchMode.externalApplication);
      if (!ok && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          backgroundColor: Colors.red.shade700,
          content: Text(t('No se pudo abrir WhatsApp', 'Could not open WhatsApp'))));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(SnackBar(
          backgroundColor: Colors.red.shade700,
          content: Text(t('Error al abrir WhatsApp: $e', 'Error opening WhatsApp: $e'))));
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
          colors: [RDSColor.card, RDSColor.green.withOpacity(0.08)]),
        borderRadius: BorderRadius.circular(16),
        border: Border.all(color: RDSColor.green.withOpacity(0.35), width: 1.2),
        boxShadow: [BoxShadow(color: RDSColor.green.withOpacity(0.10), blurRadius: 16, offset: const Offset(0, 4))]),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        // ── Header: badge ALIADO + nombre + logo ──
        Row(children: [
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
            decoration: BoxDecoration(
              color: RDSColor.green.withOpacity(0.18),
              borderRadius: BorderRadius.circular(6),
              border: Border.all(color: RDSColor.green.withOpacity(0.4))),
            child: Text(t('ALIADO OFICIAL', 'OFFICIAL PARTNER'),
              style: TextStyle(color: RDSColor.green, fontSize: 9,
                fontWeight: FontWeight.w900, letterSpacing: 1.2)),
          ),
          const Spacer(),
          const Text('🚌', style: TextStyle(fontSize: 22)),
        ]),
        const SizedBox(height: 10),

        // ── Título principal ──
        const Text('Alianza Local Tours',
          style: TextStyle(color: RDSColor.textPrimary, fontSize: 18, fontWeight: FontWeight.w900, letterSpacing: 0.3)),
        const SizedBox(height: 2),
        Text(t('Respaldados por Sotra San Vicente · 70 años',
              'Backed by Sotra San Vicente · 70 years'),
          style: const TextStyle(color: RDSColor.textMuted, fontSize: 11, fontStyle: FontStyle.italic)),

        const SizedBox(height: 14),

        // ── Descripción del servicio ──
        Text(t('🚌 Hop On / Hop Off a $_destino', '🚌 Hop On / Hop Off to $_destino'),
          style: TextStyle(color: RDSColor.gold, fontSize: 13, fontWeight: FontWeight.w800)),
        const SizedBox(height: 6),
        Text(t(
            'Sube y baja del bus las veces que quieras durante el día. Frecuencia cada 15–20 minutos. Sin recargo por paradas extras.',
            'Get on and off the bus as many times as you want during the day. Frequency every 15–20 minutes. No extra charge for additional stops.'),
          style: const TextStyle(color: RDSColor.textPrimary, fontSize: 12, height: 1.4)),

        const SizedBox(height: 12),

        // ── Cómo funciona — 4 pasos ──
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: kDark.withOpacity(0.3),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: Colors.white.withOpacity(0.05))),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(t('CÓMO FUNCIONA', 'HOW IT WORKS'),
              style: TextStyle(color: RDSColor.textMuted, fontSize: 10,
                fontWeight: FontWeight.w800, letterSpacing: 1.5)),
