class _MuseoEscobarCardState extends State<_MuseoEscobarCard> {
  // WhatsApp de Laura Escobar — Museo Beyond Escobar (confirmado 29/06/2026)
  // Calle 39 # 107-72, Barrio 20 de Julio, Comuna 13, Medellín
  // Metro: Floresta (Línea B) a 3 min caminando
  // TODO: mover a Firestore cuando se formalice como aliado en admin.html
  static const String _whatsappMuseo = '573022449897';

  late final String _codigo;

  @override
  void initState() {
    super.initState();
    // Código único por sesión de visualización — formato RUT-PEM-NNNN
    final rnd = math.Random();
    final numero = (1000 + rnd.nextInt(9000)).toString();
    _codigo = 'RUT-PEM-$numero';
  }

  Future<void> _abrirWhatsApp() async {
    final mensajeES =
        'Hola 👋 Vengo de Rutero MDE 🗺️ '
        'Quiero programar mi visita al Museo Beyond Escobar. '
        'Mi código Rutero: $_codigo '
