        "I'd like to schedule my visit to the Museo Beyond Escobar. "
        'My Rutero code: $_codigo '
        'What times are available?';

    final mensaje = kLang == 'en' ? mensajeEN : mensajeES;
    final urlMensaje = Uri.encodeComponent(mensaje);
    final url = Uri.parse('https://wa.me/$_whatsappMuseo?text=$urlMensaje');

    try {
      final ok = await launchUrl(url, mode: LaunchMode.externalApplication);
