class _RDSMetricChip extends StatelessWidget {
  final IconData? icon;      // ícono premium (Material Symbol)
  final String? emoji;       // emoji fallback (BETA chip, etc.)
  final String label;
  final Color color;

  const _RDSMetricChip({
    this.icon,
    this.emoji,
    required this.label,
    required this.color,
