class _FeriaGameStats extends StatelessWidget {
  const _FeriaGameStats();

  static const _niveles = [
    {'min': 0,    'emoji': '🌱', 'nombre': 'Novato Rutero',       'nombreEN': 'Rutero Novice'},
    {'min': 300,  'emoji': '🌿', 'nombre': 'Explorador Urbano',   'nombreEN': 'Urban Explorer'},
    {'min': 700,  'emoji': '⛰️', 'nombre': 'Rutero Paisa',        'nombreEN': 'Paisa Rutero'},
    {'min': 1200, 'emoji': '🦅', 'nombre': 'Aventurero MDE',      'nombreEN': 'MDE Adventurer'},
    {'min': 2000, 'emoji': '🏆', 'nombre': 'Leyenda de Medellín', 'nombreEN': 'Medellín Legend'},
  ];

  @override
  Widget build(BuildContext context) {
    if (AuthService.currentUser == null) return const SizedBox.shrink();
    return StreamBuilder<DocumentSnapshot>(
      stream: FirebaseFirestore.instance
        .collection('usuarios')
        .doc(AuthService.currentUser!.uid)
        .snapshots(),
      builder: (ctx, snap) {
        final data = snap.data?.data() as Map<String, dynamic>? ?? {};
        final int puntos = (data['puntosTotal'] ?? 0) as int;
        final int sitios = (data['sitiosVisitados'] ?? 0) as int;
        final nivel = _niveles.lastWhere(
          (n) => puntos >= ((n['min'] as int?) ?? 0), orElse: () => _niveles.first);
        final int nivelIndex = _niveles.indexOf(nivel) + 1;

        return Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: Colors.black.withOpacity(0.55),
            borderRadius: BorderRadius.circular(16),
            border: Border.all(color: kFeriaDorado.withOpacity(0.25))),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(t('Tu guía personal de Medellín', 'Your personal Medellín guide'),
              style: const TextStyle(fontSize: 11, color: kFeriaDorado,
                fontWeight: FontWeight.w700, letterSpacing: 0.5)),
            const SizedBox(height: 10),
            Row(children: [
              _GameStatCell(
                emoji: nivel['emoji']?.toString() ?? '',
                valor: 'Nivel $nivelIndex',
                label: t(nivel['nombre']?.toString() ?? '', nivel['nombreEN']?.toString() ?? ''),
                color: RDSColor.green),
              const SizedBox(width: 8),
              _GameStatCell(
                emoji: '🌸',
                valor: '$sitios',
                label: t('flores', 'flowers'),
                color: kFeriaRojo),
              const SizedBox(width: 8),
              _GameStatCell(
                emoji: '⭐',
                valor: '$puntos',
                label: t('puntos', 'points'),
                color: kFeriaDorado),
            ]),
          ]));
      });
  }
}

