// ═══════════════════════════════════════════════════════════════════════════════
//  TAB 1 — AGENDA DÍA A DÍA
// ═══════════════════════════════════════════════════════════════════════════════

class _FeriaAgendaTab extends StatefulWidget {
  @override
  State<_FeriaAgendaTab> createState() => _FeriaAgendaTabState();
}

class _FeriaAgendaTabState extends State<_FeriaAgendaTab> {
  Position? _posUsuario;
  bool _ordenarPorCercania = false;

  @override
  void initState() {
    super.initState();
    _obtenerPosicion();
    // Seleccionar hoy si estamos en la feria
    final now = DateTime.now();
    for (int i = 0; i < _dias.length; i++) {
      if (_dias[i]['mes'] == now.month && _dias[i]['dia'] == now.day) {
        _selIdx = i; break;
      }
    }
  }

  Future<void> _obtenerPosicion() async {
    try {
      final pos = await Geolocator.getCurrentPosition(
        desiredAccuracy: LocationAccuracy.medium,
        timeLimit: const Duration(seconds: 5));
      if (mounted) setState(() => _posUsuario = pos);
    } catch (_) {}
  }

  double _distanciaKm(double lat, double lng) {
    if (_posUsuario == null) return 999;
    return Geolocator.distanceBetween(
      _posUsuario!.latitude, _posUsuario!.longitude, lat, lng) / 1000;
  }

  void _abrirMapa(double lat, double lng, String nombre) {
    final url = 'https://www.google.com/maps/dir/?api=1&destination=$lat,$lng&travelmode=transit';
    launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
  }
  // Días de la feria: 31jul, 1-9ago
  List<Map<String, dynamic>> get _dias => [
    {'dia': 31, 'mes': 7, 'label': t('31 Jul','Jul 31'), 'dow': t('Vie','Fri'), 'especial': t('Apertura','Opening')},
    {'dia': 1, 'mes': 8, 'label': t('1 Ago','Aug 1'), 'dow': t('Sáb','Sat'), 'especial': null},
    {'dia': 2, 'mes': 8, 'label': t('2 Ago','Aug 2'), 'dow': t('Dom','Sun'), 'especial': null},
    {'dia': 3, 'mes': 8, 'label': t('3 Ago','Aug 3'), 'dow': t('Lun','Mon'), 'especial': null},
    {'dia': 4, 'mes': 8, 'label': t('4 Ago','Aug 4'), 'dow': t('Mar','Tue'), 'especial': null},
    {'dia': 5, 'mes': 8, 'label': t('5 Ago','Aug 5'), 'dow': t('Mié','Wed'), 'especial': null},
    {'dia': 6, 'mes': 8, 'label': t('6 Ago','Aug 6'), 'dow': t('Jue','Thu'), 'especial': t('Autos','Cars')},
    {'dia': 7, 'mes': 8, 'label': t('7 Ago','Aug 7'), 'dow': t('Vie','Fri'), 'especial': t('Trova','Trova')},
    {'dia': 8, 'mes': 8, 'label': t('8 Ago','Aug 8'), 'dow': t('Sáb','Sat'), 'especial': t('Concierto','Concert')},
    {'dia': 9, 'mes': 8, 'label': t('9 Ago','Aug 9'), 'dow': t('Dom','Sun'), 'especial': t('Desfile 🌹','Parade 🌹')},
  ];

  int _selIdx = 0;

  List<Map<String, dynamic>> _eventosDia(Map<String, dynamic> d) =>
    kFeriaAgenda.where((e) => e['dia'] == d['dia'] && e['mes'] == d['mes']).toList();

  Color _colorTipo(String tipo) {
    switch (tipo) {
      case 'concierto': return kFeriaRojo;
      case 'desfile': return kFeriaDorado;
      case 'trova': return RDSColor.orchid;
      case 'tablado': return RDSColor.green;
      case 'silletera': return kFeriaVerde;
      case 'flores': return kFeriaRosa;
      case 'familiar': return const Color(0xFF5B8AD4);
      case 'especial': return RDSColor.gold;
      default: return RDSColor.textMuted;
    }
  }

  @override
  Widget build(BuildContext context) {
    final diaActual = _dias[_selIdx];
    final eventos = _eventosDia(diaActual);
    final now = DateTime.now();
    final esHoy = diaActual['mes'] == now.month && diaActual['dia'] == now.day;

    // Ordenar eventos según toggle
    final eventosMostrar = _ordenarPorCercania
        ? (List<Map<String, dynamic>>.from(eventos)
            ..sort((a, b) {
              final da = _distanciaKm((a['lat'] as num?)?.toDouble() ?? 999, (a['lng'] as num?)?.toDouble() ?? 999);
              final db = _distanciaKm((b['lat'] as num?)?.toDouble() ?? 999, (b['lng'] as num?)?.toDouble() ?? 999);
              return da.compareTo(db);
            }))
        : eventos;

    return CustomScrollView(
      slivers: [
      SliverToBoxAdapter(child: Container(
        height: 68,
        color: RDSColor.surface,
        child: ListView.builder(
          scrollDirection: Axis.horizontal,
          padding: const EdgeInsets.fromLTRB(12, 8, 12, 8),
          itemCount: _dias.length,
          itemBuilder: (_, i) {
            final d = _dias[i];
            final sel = i == _selIdx;
            final now2 = DateTime.now();
            final esHoy2 = d['mes'] == now2.month && d['dia'] == now2.day;
            final tieneEspecial = d['especial'] != null;
            return GestureDetector(
              onTap: () => setState(() => _selIdx = i),
              child: Container(
                margin: const EdgeInsets.only(right: 6),
                padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 0),
                decoration: BoxDecoration(
                  color: sel ? kFeriaRojo : (esHoy2 ? kFeriaRojo.withOpacity(0.15) : RDSColor.card),
                  borderRadius: BorderRadius.circular(10),
                  border: Border.all(
                    color: sel ? kFeriaRojo : (esHoy2 ? kFeriaRojo.withOpacity(0.4) : Colors.transparent))),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Text(d['dow']?.toString() ?? '',
                      style: TextStyle(fontSize: 9, color: sel ? Colors.white70 : RDSColor.textMuted)),
                    Text(d['label']?.toString() ?? '',
                      style: TextStyle(fontSize: 12, fontWeight: FontWeight.w700,
                        color: sel ? Colors.white : RDSColor.textPrimary)),
                    if (tieneEspecial)
                      Container(width: 4, height: 4,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: sel ? Colors.white70 : kFeriaDorado)),
                  ])));
          })),
      ),
      // Toggle cercanía
      SliverToBoxAdapter(child: Container(
        color: RDSColor.surface,
        padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
        child: Row(children: [
          const Text('📍', style: TextStyle(fontSize: 12)),
          const SizedBox(width: 6),
          Text(_posUsuario != null ? t('Tu ubicación activa','Your location active') : t('Obteniendo ubicación...','Getting location...'),
            style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
          const Spacer(),
          if (_posUsuario != null)
            GestureDetector(
              onTap: () => setState(() => _ordenarPorCercania = !_ordenarPorCercania),
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: _ordenarPorCercania ? RDSColor.green.withOpacity(0.2) : RDSColor.card,
                  borderRadius: BorderRadius.circular(20),
                  border: Border.all(color: _ordenarPorCercania ? RDSColor.green : RDSColor.textMuted.withOpacity(0.3))),
                child: Text(_ordenarPorCercania ? t('✅ Más cercano','✅ Nearest') : t('Por hora','By time'),
                  style: TextStyle(fontSize: 11,
                    color: _ordenarPorCercania ? RDSColor.green : RDSColor.textMuted,
                    fontWeight: FontWeight.w600)))),
        ]))),
      SliverPadding(
        padding: const EdgeInsets.all(16),
        sliver: SliverList(delegate: SliverChildListDelegate([
            // ── Widget HOY enriquecido ──
            if (esHoy) ...[
              Container(
                margin: const EdgeInsets.only(bottom: 16),
                decoration: BoxDecoration(
                  gradient: LinearGradient(
                    colors: [kFeriaRojo.withOpacity(0.25), kFeriaDorado.withOpacity(0.15)],
                    begin: Alignment.topLeft, end: Alignment.bottomRight),
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: kFeriaRojo.withOpacity(0.5))),
                child: Padding(
                  padding: const EdgeInsets.all(16),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Row(children: [
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                        decoration: BoxDecoration(
                          color: kFeriaRojo,
                          borderRadius: BorderRadius.circular(RDSRadius.xl)),
                        child: Text(t('🟢 AHORA · FERIA EN VIVO','🟢 NOW · LIVE FERIA'),
                          style: const TextStyle(fontSize: 10, color: Colors.white,
                            fontWeight: FontWeight.w800, letterSpacing: 1))),
                      const Spacer(),
                      GestureDetector(
                        onTap: () {
                          final eventosHoy = eventosMostrar.map((e) =>
                            '${e['emoji'] ?? '🎶'} ${e['titulo']} · ${e['hora'] ?? ''} · ${e['lugar'] ?? ''}').join('\n');
                          Share.share(
                            t('🌹 Feria de las Flores 2026 · HOY\n\n$eventosHoy\n\nDescubrí toda la programación en Rutero MDE → rutero-mde.web.app',
                              '🌹 Feria de las Flores 2026 · TODAY\n\n$eventosHoy\n\nDiscover the full program on Rutero MDE → rutero-mde.web.app'),
                            subject: t('Feria de las Flores · Hoy en Medellín','Feria de las Flores · Today in Medellín'));
                        },
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                          decoration: BoxDecoration(
                            color: kFeriaDorado.withOpacity(0.15),
                            borderRadius: BorderRadius.circular(8),
                            border: Border.all(color: kFeriaDorado.withOpacity(0.4))),
                          child: Row(mainAxisSize: MainAxisSize.min, children: [
                            const Icon(Icons.share, size: 14, color: RDSColor.gold),
                            const SizedBox(width: 4),
                            Text(t('Compartir','Share'),
                              style: const TextStyle(fontSize: 11, color: RDSColor.gold, fontWeight: FontWeight.w600)),
                          ]))),
                    ]),
                    const SizedBox(height: 12),
                    Text(t('📅 Hoy hay ${eventosMostrar.length} eventos','📅 ${eventosMostrar.length} events today'),
                      style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900, color: RDSColor.textPrimary)),
                    const SizedBox(height: 8),
                    ...eventosMostrar.take(3).map((e) => Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Row(children: [
                        Text(e['emoji']?.toString() ?? '🎶', style: const TextStyle(fontSize: 14)),
                        const SizedBox(width: 8),
                        Expanded(child: Text(
                          '${t(e['titulo']?.toString() ?? '', e['tituloEN']?.toString() ?? e['titulo']?.toString() ?? '')} · ${e['hora'] ?? ''}',
                          style: TextStyle(fontSize: 12, color: RDSColor.textPrimary.withOpacity(0.9)),
                          maxLines: 1, overflow: TextOverflow.ellipsis)),
                        if (e['gratuito'] == true)
                          Container(
                            padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                            decoration: BoxDecoration(
                              color: RDSColor.green.withOpacity(0.15),
                              borderRadius: BorderRadius.circular(4)),
                            child: Text(t('Gratis','Free'),
                              style: const TextStyle(fontSize: 9, color: RDSColor.green, fontWeight: FontWeight.w700))),
                      ]))),
                    if (eventosMostrar.length > 3)
                      Text(t('+ ${eventosMostrar.length - 3} eventos más abajo ↓',
                            '+ ${eventosMostrar.length - 3} more events below ↓'),
                        style: TextStyle(fontSize: 11, color: kFeriaDorado)),
                  ]))),
            ] else if (DateTime.now().isBefore(DateTime(2026, 7, 31))) ...[
              // Pre-feria: banner countdown
              Container(
                margin: const EdgeInsets.only(bottom: 16),
                padding: const EdgeInsets.all(14),
                decoration: BoxDecoration(
                  color: kFeriaRojo.withOpacity(0.08),
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: kFeriaRojo.withOpacity(0.3))),
                child: Row(children: [
                  const Text('🌹', style: TextStyle(fontSize: 28)),
                  const SizedBox(width: 12),
                  Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Text(textoContadorFeria,
                      style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w800, color: RDSColor.textPrimary)),
                    Text(t('Explorá la programación y planificá tu Feria',
                          'Explore the program and plan your Feria'),
                      style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
                  ])),
                ])),
            ],
            if (eventosMostrar.isEmpty)
              Center(
                child: Padding(
                  padding: EdgeInsets.all(32),
                  child: Text(t('Sin eventos programados este día','No events scheduled for this day'),
                    style: TextStyle(color: RDSColor.textMuted)))),
            for (final e in eventosMostrar) ...[
              Builder(builder: (_) {
                final color = _colorTipo(e['tipo']?.toString() ?? '');
                final esEstrella = e['esEstrellaFeria'] == true;
                final lat = (e['lat'] as num?)?.toDouble();
                final lng = (e['lng'] as num?)?.toDouble();
                final transporte = e['transporte']?.toString();
                final distancia = (lat != null && lng != null) ? _distanciaKm(lat, lng) : null;
                return Container(
                  margin: const EdgeInsets.only(bottom: 8),
                  padding: const EdgeInsets.all(14),
                  decoration: BoxDecoration(
                    color: esEstrella ? kFeriaRojo.withOpacity(0.12) : RDSColor.card,
                    borderRadius: BorderRadius.circular(12),
                    border: Border.all(
                      color: esEstrella ? kFeriaRojo.withOpacity(0.5) : color.withOpacity(0.2))),
                  child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                    Row(children: [
                    Container(
                      width: 3, height: 50, color: color,
                      margin: const EdgeInsets.only(right: 12)),
                    Text(e['emoji']?.toString() ?? '', style: const TextStyle(fontSize: 22)),
                    const SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(t(e['titulo']?.toString() ?? '', (e['tituloEN']?.toString()) ?? e['titulo']?.toString() ?? ''),
                            style: TextStyle(fontSize: 13, fontWeight: FontWeight.w700,
                              color: esEstrella ? kFeriaRojo : RDSColor.textPrimary)),
                          const SizedBox(height: 2),
                          Text('${e['hora']} · ${e['lugar']}',
                            style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
                          if (e['artistas'] != null) ...[
                            const SizedBox(height: 4),
                            Wrap(children: [
                              const Text('🎤 ', style: TextStyle(fontSize: 11)),
                              Text(e['artistas']?.toString() ?? '',
                                style: const TextStyle(
                                  fontSize: 11, color: RDSColor.gold,
                                  fontWeight: FontWeight.w600, height: 1.4)),
                            ]),
                          ],
                          if (e['tip'] != null) ...[
                            const SizedBox(height: 6),
                            Text(t(e['tip']?.toString() ?? '', e['tipEN']?.toString() ?? e['tip']?.toString() ?? ''),
                              style: TextStyle(
                                fontSize: 11,
                                color: RDSColor.textPrimary.withOpacity(0.65),
                                height: 1.4)),
                          ],
                        ])),
                    if (e['gratuito'] == true)
                      Container(
                        padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
                        decoration: BoxDecoration(
                          color: RDSColor.green.withOpacity(0.15),
                          borderRadius: BorderRadius.circular(6)),
                        child: const Text('FREE',
                          style: TextStyle(fontSize: 9, color: RDSColor.green, fontWeight: FontWeight.w700))),
                    ]),
                    // Transporte + distancia + botón mapa + compartir
                    if (transporte != null || lat != null) ...[
                      const SizedBox(height: 8),
                      const Divider(height: 1, color: Colors.white10),
                      const SizedBox(height: 8),
                      Row(children: [
                        if (transporte != null)
                          Expanded(child: _textoConWhoosh(transporte,
                            fontSize: 11, baseColor: RDSColor.textMuted)),
                        if (distancia != null && distancia < 50)
                          Text(' · ${distancia.toStringAsFixed(1)} km',
                            style: TextStyle(fontSize: 11,
                              color: distancia < 1.5 ? RDSColor.green : RDSColor.textMuted,
                              fontWeight: FontWeight.w600)),
                        const SizedBox(width: 6),
                        // Botón compartir
                        GestureDetector(
                          onTap: () {
                            final titulo = t(e['titulo']?.toString() ?? '', (e['tituloEN']?.toString()) ?? e['titulo']?.toString() ?? '');
                            final hora = e['hora'] ?? '';
                            final lugar = e['lugar'] ?? '';
                            final artistas = e['artistas'] != null ? '\n🎤 ${e['artistas']}' : '';
                            Share.share(
                              '🌹 Feria de las Flores 2026\n\n${e['emoji']} $titulo\n📍 $lugar\n🕐 $hora$artistas\n\n¡Seguímoslo en Rutero MDE! → rutero-mde.web.app',
                              subject: 'Feria de las Flores · $titulo');
                          },
                          child: Container(
                            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                            decoration: BoxDecoration(
                              color: Colors.white.withOpacity(0.05),
                              borderRadius: BorderRadius.circular(8)),
                            child: const Icon(Icons.share, size: 14, color: RDSColor.textMuted))),
                        const SizedBox(width: 6),
                        if (lat != null && lng != null)
                          GestureDetector(
                            onTap: () => _abrirMapa(lat, lng, e['titulo']?.toString() ?? ''),
                            child: Container(
                              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 5),
                              decoration: BoxDecoration(
                                color: kFeriaRojo.withOpacity(0.15),
                                borderRadius: BorderRadius.circular(8),
                                border: Border.all(color: kFeriaRojo.withOpacity(0.4))),
                              child: Row(mainAxisSize: MainAxisSize.min, children: [
                                Text('🗺️', style: TextStyle(fontSize: 12)),
                                SizedBox(width: 4),
                                Text(t('Cómo llegar','Get directions'),
                                  style: TextStyle(fontSize: 10, color: kFeriaRojo,
                                    fontWeight: FontWeight.w700)),
                              ]))),
                      ]),
                    ],
                  ]));
              }),
            ],
          ]))),
    ]);
  }
}

