class _FeriaRutaCard extends StatelessWidget {
  final Map<String, dynamic> ruta;
  const _FeriaRutaCard({required this.ruta});

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      onTap: () {
        // Buscar la ruta completa: primero en kFeriaRutasCompletas (siempre disponible),
        // luego en RutasService si está cargado
        const idToNombre = {
          'feria_clasica':    'FERIA CLÁSICA',
        };
        final nombreBuscado = idToNombre[ruta['id']?.toString() ?? ''] ?? ruta['nombre']?.toString() ?? '';
        // Buscar primero en kFeriaRutasCompletas (disponible sin esperar carga async)
        final rutaLocal = kFeriaRutasCompletas.firstWhere(
          (r) => r['nombre']?.toString() == nombreBuscado,
          orElse: () => <String, dynamic>{});
        // Si está en kFeriaRutasCompletas y tiene sitiosList → usar esa
        final localSitios = (rutaLocal['sitiosList'] as List?) ?? parseSitiosDetalle(rutaLocal['sitiosDetalle']);
        if (rutaLocal.isNotEmpty && localSitios?.isNotEmpty == true) {
          RuteroNav.push(context, RouteDetailScreen(ruta: rutaLocal));
          return;
        }
        // Fallback a RutasService (puede tener versión enriquecida desde Firestore)
        final rutaCompleta = RutasService().rutas.firstWhere(
          (r) => r['nombre']?.toString() == nombreBuscado,
          orElse: () => rutaLocal.isNotEmpty ? rutaLocal : ruta);
        final completaSitios = (rutaCompleta['sitiosList'] as List?) ?? parseSitiosDetalle(rutaCompleta['sitiosDetalle']);
        if (completaSitios?.isNotEmpty == true) {
          RuteroNav.push(context, RouteDetailScreen(ruta: rutaCompleta));
        } else {
          RuteroNav.push(context, FeriaRutaDetailScreen(rutaFeria: ruta));
        }
      },
      child: Container(
        margin: const EdgeInsets.only(bottom: 12),
        decoration: BoxDecoration(
          gradient: LinearGradient(
            begin: Alignment.topLeft, end: Alignment.bottomRight,
            colors: [kRutaColor(ruta['color1'], RDSColor.base), kRutaColor(ruta['color2'], const Color(0xFF050A04))]),
          borderRadius: BorderRadius.circular(16),
          border: Border.all(color: kRutaColor(ruta['acento'], RDSColor.gold).withOpacity(0.3))),
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              Text(ruta['emoji']?.toString() ?? '🗺️', style: const TextStyle(fontSize: 32)),
              const SizedBox(width: 12),
              Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                Text(t(ruta['nombre']?.toString() ?? '', ruta['nombreEN']?.toString() ?? ruta['nombre']?.toString() ?? ''),
                  style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w900,
                    color: RDSColor.textPrimary, letterSpacing: 1)),
                Text(t(ruta['desc']?.toString() ?? ruta['descripcion']?.toString() ?? '', ruta['descEN']?.toString() ?? ruta['descripcionEN']?.toString() ?? ''),
                  style: const TextStyle(fontSize: 11, color: RDSColor.textMuted, height: 1.4)),
              ])),
            ]),
            const SizedBox(height: 12),
            Row(children: [
              _RutaChip('${ruta['sitios'] ?? ''} sitios', kRutaColor(ruta['acento'], RDSColor.gold)),
              const SizedBox(width: 8),
              _RutaChip(ruta['tiempo']?.toString() ?? '', kRutaColor(ruta['acento'], RDSColor.gold)),
              const Spacer(),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 6),
                decoration: BoxDecoration(
                  color: kRutaColor(ruta['acento'], RDSColor.gold).withOpacity(0.15),
                  borderRadius: BorderRadius.circular(8),
                  border: Border.all(color: kRutaColor(ruta['acento'], RDSColor.gold).withOpacity(0.4))),
                child: Row(children: [
                  Text('${ruta['insigniaEmoji'] ?? ''} ${ruta['insignia'] ?? ''}',
                    style: const TextStyle(fontSize: 10, color: RDSColor.gold, fontWeight: FontWeight.w600)),
                ])),
            ]),
          ]))));
  }
}

class _RutaChip extends StatelessWidget {
  final String label; final Color color;
  const _RutaChip(this.label, this.color);
  @override
  Widget build(BuildContext context) => Container(
    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
    decoration: BoxDecoration(
      color: color.withOpacity(0.1), borderRadius: BorderRadius.circular(6)),
    child: Text(label, style: TextStyle(fontSize: 10, color: color, fontWeight: FontWeight.w600)));
}

