class _TabladoCard extends StatelessWidget {
  final Map<String, dynamic> tablado;
  const _TabladoCard({required this.tablado});

  @override
  Widget build(BuildContext context) {
    final lat = (tablado['lat'] as num).toDouble();
    final lng = (tablado['lng'] as num).toDouble();

    return Container(
      margin: const EdgeInsets.only(bottom: 10),
      decoration: BoxDecoration(
        color: RDSColor.card,
        borderRadius: BorderRadius.circular(14),
        border: Border.all(color: RDSColor.surface)),
      child: Padding(
        padding: const EdgeInsets.all(14),
        child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
          // Emoji zona
          Container(
            width: 42, height: 42,
            decoration: BoxDecoration(
              color: kFeriaDorado.withOpacity(0.1),
              borderRadius: BorderRadius.circular(10)),
            child: Center(child: Text('🪗', style: const TextStyle(fontSize: 20)))),
          const SizedBox(width: 12),
          Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Text(tablado['nombre']?.toString() ?? '',
              style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: RDSColor.textPrimary)),
            const SizedBox(height: 3),
            Text(tablado['zona']?.toString() ?? '',
              style: const TextStyle(fontSize: 11, color: kFeriaDorado, fontWeight: FontWeight.w600)),
            const SizedBox(height: 5),
            Row(children: [
              const Icon(Icons.location_on_outlined, size: 12, color: RDSColor.textMuted),
              const SizedBox(width: 3),
              Expanded(child: Text(tablado['lugar']?.toString() ?? '',
                style: const TextStyle(fontSize: 11, color: RDSColor.textMuted))),
            ]),
            const SizedBox(height: 2),
            Row(children: [
              const Icon(Icons.access_time, size: 12, color: RDSColor.textMuted),
              const SizedBox(width: 3),
              Text('${tablado['hora'] ?? ''} · ${t('Gratuito', 'Free')}',
                style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
            ]),
            const SizedBox(height: 2),
            Row(children: [
              const Icon(Icons.directions_transit, size: 12, color: RDSColor.textMuted),
              const SizedBox(width: 3),
              Expanded(child: Text(tablado['transporte']?.toString() ?? '',
                style: const TextStyle(fontSize: 11, color: RDSColor.textMuted))),
            ]),
          ])),
          // Botón GPS
          GestureDetector(
            onTap: () => _abrirMapa(lat, lng, tablado['nombre']?.toString() ?? ''),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: kFeriaDorado.withOpacity(0.15),
                borderRadius: BorderRadius.circular(10),
                border: Border.all(color: kFeriaDorado.withOpacity(0.4))),
              child: Column(mainAxisSize: MainAxisSize.min, children: [
                const Icon(Icons.navigation_outlined, size: 18, color: kFeriaDorado),
                const SizedBox(height: 2),
                Text(t('Ir','Go'),
                  style: const TextStyle(fontSize: 9, color: kFeriaDorado, fontWeight: FontWeight.w700)),
              ]))),
        ])));
  }

  void _abrirMapa(double lat, double lng, String nombre) {
    final uri = Uri.parse(
      'https://www.google.com/maps/dir/?api=1&destination=$lat,$lng&travelmode=transit');
    launchUrl(uri, mode: LaunchMode.externalApplication);
  }
}

class _FeriaTableadosTab extends StatefulWidget {
  @override
  State<_FeriaTableadosTab> createState() => _FeriaTableadosTabState();
}

class _FeriaTableadosTabState extends State<_FeriaTableadosTab> {
  int _zonaSeleccionada = -1;

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.all(16),
      children: [
        // Intro
        Container(
          margin: const EdgeInsets.only(bottom: 16),
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(
            color: RDSColor.card, borderRadius: BorderRadius.circular(12),
            border: Border.all(color: RDSColor.green.withOpacity(0.2))),
          child: Text(
            t('21 tablados musicales · GRATIS · Toda la feria. Esponsorados por Aguardiente Antioqueño y Pilsen · Una validación por zona',
              '21 free music stages · Throughout the festival. Sponsored by Aguardiente Antioqueño & Pilsen · One validation per zone'),
            style: TextStyle(fontSize: 12, color: RDSColor.textMuted, height: 1.5))),
        // Zonas
        ...kFeriaZonasTablero.asMap().entries.map((entry) {
          final i = entry.key;
          final zona = entry.value;
          final sel = i == _zonaSeleccionada;
          return GestureDetector(
            onTap: () => setState(() => _zonaSeleccionada = sel ? -1 : i),
            child: Container(
              margin: const EdgeInsets.only(bottom: 8),
              decoration: BoxDecoration(
                color: sel ? (zona['color'] as Color) : RDSColor.card,
                borderRadius: BorderRadius.circular(14),
                border: Border.all(
                  color: sel ? RDSColor.green.withOpacity(0.5) : RDSColor.textMuted.withOpacity(0.1))),
              child: Column(children: [
                Padding(
                  padding: const EdgeInsets.all(14),
                  child: Row(children: [
                    Text(zona['emoji']?.toString() ?? '', style: const TextStyle(fontSize: 24)),
                    const SizedBox(width: 12),
                    Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                      Text(zona['zona']?.toString() ?? '',
                        style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w700, color: RDSColor.textPrimary)),
                      Text('${(zona['tablados'] as List).length}' + t(' tablados · Gratis · Toda la feria',' stages · Free · All festival'),
                        style: const TextStyle(fontSize: 11, color: RDSColor.textMuted)),
                    ])),
                    Container(
                      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
                      decoration: BoxDecoration(
                        color: RDSColor.green.withOpacity(0.15),
                        borderRadius: BorderRadius.circular(6)),
                      child: const Text('GPS', style: TextStyle(fontSize: 10, color: RDSColor.green, fontWeight: FontWeight.w700))),
                    const SizedBox(width: 8),
                    Text(sel ? '▲' : '▼', style: const TextStyle(color: RDSColor.textMuted, fontSize: 12)),
                  ])),
                if (sel) ...[
                  const Divider(height: 1, color: Colors.white10),
                  Padding(
                    padding: const EdgeInsets.all(14),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        ...(zona['tablados'] as List).map<Widget>((tablado) {
                          final nombre = tablado['nombre']?.toString() ?? tablado.toString();
                          final barrio = tablado is Map ? tablado['barrio']?.toString() ?? '' : '';
                          final lugar = tablado is Map ? tablado['lugar']?.toString() ?? '' : '';
                          final lat = tablado is Map ? (tablado['lat'] as double?) : null;
                          final lng = tablado is Map ? (tablado['lng'] as double?) : null;
                          return Container(
                            margin: const EdgeInsets.only(bottom: 8),
                            padding: const EdgeInsets.all(10),
                            decoration: BoxDecoration(
                              color: Colors.black.withOpacity(0.2),
                              borderRadius: BorderRadius.circular(10),
                              border: Border.all(color: Colors.white.withOpacity(0.06))),
                            child: Row(children: [
                              const Text('🎶', style: TextStyle(fontSize: 18)),
                              const SizedBox(width: 10),
                              Expanded(child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(nombre,
                                    style: const TextStyle(fontSize: 13, fontWeight: FontWeight.w700, color: RDSColor.textPrimary)),
                                  if (barrio.isNotEmpty)
                                    Text(barrio,
                                      style: const TextStyle(fontSize: 10, color: RDSColor.green)),
                                  if (lugar.isNotEmpty)
                                    Text(lugar,
                                      style: const TextStyle(fontSize: 10, color: RDSColor.textMuted)),
                                ])),
                              if (lat != null && lng != null)
                                GestureDetector(
                                  onTap: () {
                                    final url = 'https://www.google.com/maps/dir/?api=1&destination=$lat,$lng&travelmode=transit';
                                    launchUrl(Uri.parse(url), mode: LaunchMode.externalApplication);
                                  },
                                  child: Container(
                                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
                                    decoration: BoxDecoration(
                                      color: RDSColor.green.withOpacity(0.15),
                                      borderRadius: BorderRadius.circular(8),
                                      border: Border.all(color: RDSColor.green.withOpacity(0.3))),
                                    child: const Text('📍', style: TextStyle(fontSize: 14)))),
                            ]));
                        }).toList(),
                        const SizedBox(height: 8),
                        if (zona['transporte'] != null)
                          Container(
                            padding: const EdgeInsets.all(10),
                            decoration: BoxDecoration(
                              color: RDSColor.card,
                              borderRadius: BorderRadius.circular(8)),
                            child: Row(children: [
                              const Text('🚇', style: TextStyle(fontSize: 14)),
                              const SizedBox(width: 8),
                              Expanded(child: Text(zona['transporte']?.toString() ?? '',
                                style: const TextStyle(fontSize: 11, color: RDSColor.textMuted))),
                            ])),
                      ])),
                ],
              ])));
        }),
      ]);
  }
}

